SERVER_LOG = CC_LOGS / "server.log"
_server_log_lock = threading.Lock()
# Persistent append handle for slog(), guarded by the lock above. See slog() for why
# open-per-line was the measured cause of the 08-03 wedge.
# NOT rotated here, deliberately: launchd sets BOTH StandardOutPath and
# StandardErrorPath to this same file, so its fds follow the inode across a rename.
# Rotating by rename would leave launchd appending to the orphaned file forever while
# this handle wrote to the new one — output split across two places, neither complete.
# Log size is a separate problem (49MB and growing) and needs a solution that accounts
# for those launchd fds; it is not what was causing the contention, since O_APPEND
# open cost does not scale with file size.
_server_log_fh = None
_server_log_fh_checked = 0.0

def slog(*args):
    """Append a timestamped line to ~/.amux/logs/server.log (and stderr if TTY)."""
    import datetime
    msg = " ".join(str(a) for a in args)
    line = f"{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')} {msg}\n"
    # Only write to stderr if it's a real terminal — launchd redirects stderr
    # to server.log, so writing to both would double every line.
    if sys.stderr.isatty():
        sys.stderr.write(line)
    # MEASURED HOT SPOT (AC-174). This used to be `with open(SERVER_LOG,"a") as f`
    # INSIDE the lock, so every one of the 244 slog() call sites paid a full
    # open + write + close — three syscalls plus a path resolution — while holding
    # a process-global lock. During the 2026-08-03 16:41Z wedge, 33 of ~65 threads
    # were blocked at exactly this line (the dump's single most common frame) with
    # the process at 97.3% CPU and /api/board returning HTTP 000. ThreadingHTTPServer
    # has no worker cap, so a burst of heavy requests serializes every handler here
    # and the server answers nothing while looking near-idle per-thread.
    # Keeping the handle open makes the critical section one buffered write.
    global _server_log_fh, _server_log_fh_checked
    try:
        with _server_log_lock:
            fh = _server_log_fh
            now = time.monotonic()
            if fh is None or fh.closed:
                fh = _server_log_fh = open(SERVER_LOG, "a", buffering=1)
                _server_log_fh_checked = now
            elif now - _server_log_fh_checked > 30:
                # A persistent handle keeps writing into a DELETED inode if the file
                # is moved or removed underneath us, and the lines just vanish with
                # no error — the silent-log failure this repo keeps getting bitten by.
                # Re-stat occasionally (not per line, that reintroduces the syscall
                # we are removing) and reopen if the path no longer names our inode.
                _server_log_fh_checked = now
                try:
                    if (not SERVER_LOG.exists()
                            or os.fstat(fh.fileno()).st_ino != SERVER_LOG.stat().st_ino):
                        try:
                            fh.close()
                        except Exception:
                            pass
                        fh = _server_log_fh = open(SERVER_LOG, "a", buffering=1)
                except Exception:
                    pass
            fh.write(line)
    except Exception:
        pass

_server_start_time = time.time()

# Cached process info — updated by background thread, never blocks request handlers
_proc_info_cache: dict = {}
_proc_info_lock = threading.Lock()
_proc_info_last_update: float = 0.0
_PROC_INFO_TTL = 10.0  # refresh every 10s

def _build_proc_info() -> dict:
    """Gather process-level diagnostics (blocks ~500ms for CPU sampling)."""
    info = {}
    try:
        # Longer sample window + actual elapsed time divisor: a 100ms window was
        # small enough that any brief multi-thread burst inflated the reading to
        # 150-200%, triggering false watchdog alerts.
        t1 = os.times()
        w1 = time.monotonic()
        time.sleep(0.5)
        t2 = os.times()
        elapsed = max(time.monotonic() - w1, 0.001)
        cpu_seconds = (t2.user - t1.user) + (t2.system - t1.system)
        info["cpu_percent"] = round(cpu_seconds / elapsed * 100, 1)
    except Exception:
        pass
    try:
        # Use current RSS (not peak) so the watchdog reacts to actual pressure,
        # not a one-time spike that has since been reclaimed.
        import resource as _res
        ru = _res.getrusage(_res.RUSAGE_SELF)
        peak_mb = round(ru.ru_maxrss / (1024 * 1024), 1) if sys.platform == "darwin" else round(ru.ru_maxrss / 1024, 1)
        info["peak_memory_mb"] = peak_mb
        # Current RSS from /proc or ps
        import subprocess as _sp
        current_mb = None
        try:
            with open(f"/proc/{os.getpid()}/status") as f:
                for line in f:
                    if line.startswith("VmRSS:"):
                        current_mb = round(int(line.split()[1]) / 1024, 1)
                        break
        except FileNotFoundError:
            r = _sp.run(["ps", "-o", "rss=", "-p", str(os.getpid())],
                        capture_output=True, text=True, timeout=3)
            if r.returncode == 0 and r.stdout.strip():
                current_mb = round(int(r.stdout.strip()) / 1024, 1)
        info["memory_mb"] = current_mb if current_mb is not None else peak_mb
    except Exception:
        pass
    try:
        info["fd_count"] = len(os.listdir(f"/dev/fd"))
    except Exception:
        pass
    try:
        import subprocess
        out = subprocess.check_output(["tmux", "list-sessions", "-F", "#{session_name}"], stderr=subprocess.DEVNULL, timeout=5)
        info["session_count"] = len([l for l in out.decode().strip().splitlines() if l])
    except Exception:
        info["session_count"] = -1
    return info

def psutil_process_info():
    """Return cached process info (non-blocking). Triggers background refresh if stale."""
    global _proc_info_last_update
    now = time.time()
    with _proc_info_lock:
        cached = dict(_proc_info_cache)
        age = now - _proc_info_last_update
    if age > _PROC_INFO_TTL:
        def _refresh():
            global _proc_info_last_update
            data = _build_proc_info()
            with _proc_info_lock:
                _proc_info_cache.update(data)
                _proc_info_last_update = time.time()
        if not cached:
            # Cold start: build synchronously so first call returns real data
            _refresh()
            with _proc_info_lock:
                return dict(_proc_info_cache)
        threading.Thread(target=_refresh, daemon=True).start()
    return cached

def _log_resource_snapshot(label="snapshot"):
    """Log a resource snapshot to server.log."""
    info = psutil_process_info()
    slog(f"[{label}] pid={os.getpid()} cpu={info.get('cpu_percent','?')}% mem={info.get('memory_mb','?')}MB fds={info.get('fd_count','?')} threads={threading.active_count()} sessions={info.get('session_count','?')} requests={_server_request_count}")

_active_servers: list = []  # populated in main(); used by signal handler for clean shutdown

def _install_signal_handlers():
    """Install signal handlers that log before exit."""
    import signal
    # SIGUSR1 -> dump every thread's stack into the log, WITHOUT exiting.
    #
    # The spin (AC-164/AC-170) pegs a core while /api/board and /api/email hang,
    # then launchd replaces the process, so the evidence is gone before anyone
    # looks. py-spy would answer it in one sample — but py-spy REQUIRES ROOT ON
    # macOS, which a session cannot do unattended, so on this machine it is not
    # an available instrument at all. faulthandler needs no privileges because
    # the process dumps ITSELF, and STAT=R means a pure-Python spin will service
    # the signal between bytecodes and name the function it is looping in.
    #
    # Deliberately not fatal: this is a probe, not a crash path. `kill -USR1
    # <pid>` any time the server is misbehaving and the stacks land in
    # ~/.amux/logs/server.log next to the request log that shows what hung.
    try:
        import faulthandler
        _dump_target = open(os.path.expanduser("~/.amux/logs/server.log"), "a")
        faulthandler.register(signal.SIGUSR1, file=_dump_target, all_threads=True, chain=False)
        slog("[diag] SIGUSR1 -> all-thread stack dump into server.log "
             "(kill -USR1 %d to catch a spin in the act)" % os.getpid())
    except Exception as e:
        slog(f"[diag] faulthandler unavailable, no spin dump on SIGUSR1: {e}")

    def _sig_handler(signum, frame):
        sig_name = signal.Signals(signum).name
        slog(f"[SIGNAL] received {sig_name} ({signum}) — logging diagnostics before exit")
        _log_resource_snapshot("crash-dump")
        # Close listening sockets so the port is freed immediately for the next
        # process (launchd KeepAlive respawn).  Without this, the socket lingers
        # in TIME_WAIT and the replacement process can't bind.
        for _s in _active_servers:
            try:
                _s.socket.close()
            except Exception:
                pass
        try:
            _db_conn().close()
        except Exception:
            pass
        slog(f"[SIGNAL] exiting due to {sig_name}")
        os._exit(128 + signum)
    signal.signal(signal.SIGTERM, _sig_handler)
    # Ignore SIGHUP so the server survives terminal disconnects and
    # os.execv auto-restarts (where nohup protection is lost).
    signal.signal(signal.SIGHUP, signal.SIG_IGN)

