_aria2_proc = None

def _aria2_ensure():
    """Start aria2c daemon if not running."""
    global _aria2_proc
    if _aria2_proc and _aria2_proc.poll() is None:
        return True
    # Check if already running
    try:
        r = _aria2_rpc("aria2.getVersion")
        if r: return True
    except Exception:
        pass
    aria2 = shutil.which("aria2c")
    if not aria2:
        return False
    os.makedirs(_ARIA2_DOWNLOAD_DIR, exist_ok=True)
    _aria2_proc = subprocess.Popen([
        aria2, "--enable-rpc", "--rpc-listen-port", str(_ARIA2_RPC_PORT),
        "--rpc-secret", _ARIA2_RPC_SECRET,
        "--dir", _ARIA2_DOWNLOAD_DIR,
        "--seed-time=0",  # don't seed after download
        "--bt-enable-lpd=true",
        "--enable-dht=true",
        "--enable-peer-exchange=true",
        "--max-concurrent-downloads=5",
        "--file-allocation=none",
        "--daemon=false",
        "--quiet=true",
    ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    time.sleep(0.5)
    return _aria2_proc.poll() is None

def _aria2_rpc(method, params=None):
    """Call aria2 JSON-RPC."""
    payload = {
        "jsonrpc": "2.0",
        "id": "amux",
        "method": method,
        "params": [f"token:{_ARIA2_RPC_SECRET}"] + (params or [])
    }
    import urllib.request
    req = urllib.request.Request(
        f"http://localhost:{_ARIA2_RPC_PORT}/jsonrpc",
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=5) as resp:
        return json.loads(resp.read()).get("result")

def _aria2_list_all():
    """Get all torrents (active + waiting + stopped)."""
    torrents = []
    for method in ("aria2.tellActive", "aria2.tellWaiting", "aria2.tellStopped"):
        try:
            params = [0, 100] if method != "aria2.tellActive" else []
            items = _aria2_rpc(method, params) or []
            torrents.extend(items)
        except Exception:
            pass
    result = []
    for t in torrents:
        gid = t.get("gid", "")
        total = int(t.get("totalLength", 0))
        completed = int(t.get("completedLength", 0))
        speed = int(t.get("downloadSpeed", 0))
        status = t.get("status", "unknown")
        bt = t.get("bittorrent", {})
        name = ""
        if bt.get("info"):
            name = bt["info"].get("name", "")
        if not name and t.get("files"):
            name = t["files"][0].get("path", "").split("/")[-1]
        files = []
        for f in t.get("files", []):
            fp = f.get("path", "")
            if not fp:
                continue
            fsize = int(f.get("length", 0))
            fcomplete = int(f.get("completedLength", 0)) >= fsize and fsize > 0
            files.append({"path": fp, "size": fsize, "complete": fcomplete})
        result.append({
            "gid": gid, "name": name, "status": status,
            "total": total, "completed": completed, "speed": speed,
            "files": files,
        })
    return result


# ── Browser automation helpers (browser-use CLI) ─────────────────────────────
_BROWSER_USE_BIN = shutil.which("browser-use") or "/usr/local/bin/browser-use"
_browser_session_activity: dict[str, float] = {}  # session_name -> last_activity epoch
_browser_locks: dict[str, threading.Lock] = {}     # per-session lock to serialize subprocess calls
_browser_locks_mu = threading.Lock()               # protects _browser_locks dict

def _browser_lock_for(session: str) -> threading.Lock:
    """Return (or create) the per-session lock for browser-use calls."""
    with _browser_locks_mu:
        if session not in _browser_locks:
            _browser_locks[session] = threading.Lock()
        return _browser_locks[session]

def _browser_touch(session: str = "amux"):
    """Record activity for a browser-use session (called on every _bu_call)."""
    _browser_session_activity[session] = time.time()

_ILOG_MAX = 200_000          # rows kept; ~weeks of fleet activity
_ILOG_BLOB_CAP = 4000        # per-field cap so one huge eval cannot bloat the table
_ilog_seq_lock = threading.Lock()

_depr_hits: dict = {}          # old-name usage since boot (AMUX-2352)
_depr_last_report = [0.0]


def _hdr_worker(headers) -> str:
    """The calling worker's identity, from either header spelling (AMUX-2352).

    X-Amux-Worker is canonical; X-Amux-Session still works and is COUNTED, so
    the old header can be retired on evidence rather than on a guess about who
    has migrated. Every attribution path — board writes, sends, schedules, env
    mutations, the staged-guard — goes through this, so neither spelling can
    silently produce an unattributed write.
    """
    try:
        w = (headers.get("X-Amux-Worker", "") or "").strip()
        if w:
            return w
        old = (headers.get("X-Amux-Session", "") or "").strip()
        if old:
            _depr_hits["header"] = _depr_hits.get("header", 0) + 1
        return old
    except Exception:
        return ""


def _depr_report():
    """Report old-name usage periodically. A counter nobody reads is the same as
    no counter (ethos rule 4) — the point is to know when /api/sessions and
    X-Amux-Session have actually stopped being called, not to accumulate a number
    in memory that dies with the process."""
    try:
        now = time.time()
        if now - _depr_last_report[0] < 3600 or not _depr_hits:
            return
        _depr_last_report[0] = now
        snap = dict(_depr_hits)
        _depr_hits.clear()
        _ilog("deprecation", "old_names_used", actor="amux", ok=True, detail=snap)
        slog(f"[deprecation] old session/tag names used in the last hour: {snap}")
    except Exception:
        pass


def _ilog(kind, action, actor="", target="", url="", detail=None,
          before=None, result=None, ok=True, ms=0):
    """Record one interaction. Best-effort: logging must never break the action.

    Deliberately called at the CHOKEPOINTS (_bu_call/_cdp_call/send_text) rather
    than at each API handler. /api/browser/action alone has ~20 return paths,
    and the one that gets missed is the one you needed in the audit."""
    try:
        def _blob(v):
            if v is None:
                return ""
            s = v if isinstance(v, str) else json.dumps(v, default=str)
            return s[:_ILOG_BLOB_CAP]
        db = get_db()
        with _ilog_seq_lock:
            row = db.execute(
                "SELECT COALESCE(MAX(seq),0) FROM interaction_log WHERE kind=? AND target=?",
                (kind, target or "")).fetchone()
            seq = (row[0] if row else 0) + 1
            db.execute(
                "INSERT INTO interaction_log "
                "(ts,kind,actor,target,action,url,detail,before,result,ok,ms,seq) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
                (int(time.time() * 1000), kind, actor or "", target or "", action or "",
                 url or "", _blob(detail), _blob(before), _blob(result),
                 1 if ok else 0, int(ms), seq))
            db.commit()
    except Exception as e:
        slog(f"[ilog] failed to record {kind}/{action}: {e}")


def _ilog_prune():
    """Keep the ledger bounded. Runs on the existing scheduler tick."""
    try:
        db = get_db()
        db.execute("DELETE FROM interaction_log WHERE id NOT IN "
                   "(SELECT id FROM interaction_log ORDER BY id DESC LIMIT ?)", (_ILOG_MAX,))
        db.commit()
    except Exception:
        pass


def _bu_page_state(session: str) -> dict:
    """Current URL/title for a browser session — the 'where' of an interaction.

    Captured BEFORE each action so a replay knows what page the step assumed,
    and a rollback knows where to return to. Silent on failure: a state probe
    that throws must not stop the action the user actually asked for."""
    try:
        lock = _browser_locks.get(session)
        if lock and lock.locked():
            return {}          # mid-action; probing would deadlock on the per-session lock
        # `eval location.href` rather than a `url` subcommand — browser-use has
        # no `url` verb, and the version that did returned usage text that
        # parsed to an empty URL, i.e. a rollback point pointing nowhere.
        # Direct subprocess (not _bu_call) so this cannot recurse into logging.
        r = subprocess.run(
            [_BROWSER_USE_BIN, "--json", "--session", session, "eval",
             "JSON.stringify({u:location.href,t:document.title})"],
            capture_output=True, text=True, timeout=8)
        d = json.loads((r.stdout or "").strip() or "{}")
        raw = (d.get("data") or {}).get("result") or ""
        try:
            p = json.loads(raw) if isinstance(raw, str) and raw.startswith("{") else {}
        except Exception:
            p = {}
        return {"url": p.get("u", ""), "title": p.get("t", "")}
    except Exception:
        return {}


# Actions that CHANGE the page. Only these get a before-state probe: a probe
# costs a subprocess, and capturing it for read-only verbs would double the cost
# of every screenshot for a rollback point identical to the one before it.
_BU_MUTATING = {"click", "type", "input", "keys", "scroll", "eval", "back",
                "navigate", "goto", "select", "upload", "press"}

# ── Profile-true session server (AMUX-2133) ─────────────────────────────────
# browser-use's CLI hardwires the session server's user-data-dir to the REAL
# Chrome directory; --profile only names a folder inside it. amux profiles
# live elsewhere, so the named identity never loaded — and locally the real
# dir is locked by the user's Chrome, so sessions silently fell back to temp
# dirs (AMUX-1979). Fix: pre-spawn the SAME daemon the CLI would spawn,
# through a bootstrap that patches get_chrome_profile_path(None) to return
# the amux-resolved dir. The CLI finds the server already running and every
# verb hits the correctly-pathed daemon unchanged. profile_verified is the
# regression tripwire that proves the directory actually taken.
# ── Profile-true sessions via self-patching daemon (AMUX-2133/2159 v2) ──────
# v1 pre-spawned a patched daemon and raced the CLI's own ensure-server; the
# bootstrap needed ~9s to import browser_use while the CLI spawns instantly,
# so the CLI's unpatched daemon won the session lock every time (watched
# second-by-second: pidfile appears at t≈9s, owner '-m skill_cli.server').
# v2 stops racing: a sitecustomize shim on PYTHONPATH patches
# get_chrome_profile_path inside ANY python that starts with
# AMUX_BU_USER_DATA_DIR set — including the daemon the CLI itself spawns,
# which copies our env. The CLI can win every race; its daemon is ours now.
_BU_SHIM_DIR = CC_HOME / "bu-shim"
_BU_SHIM_SRC = (
    "import os, sys\n"
    "def _amux_log(msg):\n"
    "    try:\n"
    "        open('/tmp/amux-bu-shim.log', 'a').write(msg + chr(10))\n"
    "    except Exception:\n"
    "        pass\n"
    "if os.environ.get('AMUX_BU_USER_DATA_DIR'):\n"
    "    try:\n"
    "        import browser_use.skill_cli.utils as _U\n"
    "        _o = _U.get_chrome_profile_path\n"
    "        def _amux_gcpp(profile=None, *a, **k):\n"
    "            _r = os.environ['AMUX_BU_USER_DATA_DIR'] if profile is None else _o(profile, *a, **k)\n"
    "            _amux_log('resolve pid=%s argv0=%s profile=%r -> %s' % (os.getpid(), sys.argv[0:2], profile, _r))\n"
    "            return _r\n"
    "        _U.get_chrome_profile_path = _amux_gcpp\n"
    "        import browser_use.browser.profile as _BP\n"
    "        _oc = _BP.BrowserProfile._copy_profile\n"
    "        def _amux_copy(self):\n"
    "            _amux_log('copy_profile pid=%s udd=%r pdir=%r' % (os.getpid(), str(self.user_data_dir), str(getattr(self, chr(112)+'rofile_directory', '?'))))\n"
    "            return _oc(self)\n"
    "        _BP.BrowserProfile._copy_profile = _amux_copy\n"
    "        _amux_log('patched pid=%s argv=%s dir=%s' % (os.getpid(), sys.argv[0:2], os.environ['AMUX_BU_USER_DATA_DIR']))\n"
    "    except Exception as _e:\n"
    "        _amux_log('PATCH FAILED pid=%s: %r' % (os.getpid(), _e))\n"
)

def _bu_write_shim():
    try:
        _BU_SHIM_DIR.mkdir(parents=True, exist_ok=True)
        f = _BU_SHIM_DIR / "sitecustomize.py"
        if not f.exists() or f.read_text() != _BU_SHIM_SRC:
            f.write_text(_BU_SHIM_SRC)
    except Exception as e:
        slog(f"[browser] shim write failed: {e}")

_bu_daemon_checked: dict = {}   # session -> monotonic ts of last provenance check

def _bu_ensure_profile_env(session: str, profile: str, env: dict) -> dict:
    """Arm env so the CLI (and the daemon it spawns) self-patch to the amux
    profile store, and kill a live UNARMED daemon once so the next spawn
    inherits the armed env. No pre-spawn: the CLI owns its daemon lifecycle."""
    udir, pdir = _bu_profile_launch_target(profile)
    _bu_write_shim()
    env["AMUX_BU_USER_DATA_DIR"] = str(udir)
    env["PYTHONPATH"] = str(_BU_SHIM_DIR) + (os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else "")
    try:
        now_m = time.monotonic()
        if now_m - _bu_daemon_checked.get(session, 0) > 10:
            _bu_daemon_checked[session] = now_m
            import tempfile as _tf
            _pidf = Path(_tf.gettempdir()) / f"browser-use-{session}.pid"
            if _pidf.exists():
                _pid = int(_pidf.read_text().strip() or 0)
                _r = subprocess.run(["ps", "-wwwE", "-p", str(_pid)],
                                    capture_output=True, text=True)
                _alive = subprocess.run(["ps", "-p", str(_pid)], capture_output=True).returncode == 0
                if _alive and "AMUX_BU_USER_DATA_DIR=" + str(udir) not in (_r.stdout or ""):
                    slog(f"[browser] recycling unarmed daemon pid={_pid} for {session} "
                         f"(target store: {udir})")
                    os.kill(_pid, signal.SIGTERM)
                    for _ in range(20):
                        if subprocess.run(["ps", "-p", str(_pid)],
                                          capture_output=True).returncode != 0:
                            break
                        time.sleep(0.25)
    except Exception as e:
        slog(f"[browser] daemon provenance check failed for {session}: {e}")
    return env, pdir


def _bu_click_selector(session: str, selector: str) -> dict:
    """Click by CSS selector on the driver backend (AMUX-2272).

    The driver's own `click` verb takes an INDEX out of its last snapshot, so
    every caller had to snapshot, parse the tree, and hope the index still
    pointed at the same element. The CDP backend has accepted a selector all
    along, so the same request succeeded or 400'd depending on which backend
    happened to be up — and two sessions independently failed to verify a UI
    change on the same day because of it.

    The driver does expose `eval`, so a selector click is just resolve-then-
    click. NOTE the eval contract: it takes a bare EXPRESSION. A `return`
    statement evaluates to null and comes back as {"result": null}, which reads
    like "ran, produced nothing" rather than "wrong script shape" — that is
    what made this look like a dead end rather than a missing feature.

    Distinguishes no-match from hidden from clicked, because a click that
    silently hits nothing is indistinguishable from one that worked."""
    js = ("(function(){var e=document.querySelector(%s);"
          "if(!e)return 'NOMATCH';"
          "e.scrollIntoView({block:'center'});"
          "var r=e.getBoundingClientRect();"
          "if(r.width===0&&r.height===0)return 'NOTVISIBLE';"
          "e.click();"
          "return 'OK|'+(e.tagName||'')+'|'+((e.textContent||'').trim().slice(0,60));})()"
          % json.dumps(selector))
    res = _bu_eval(session, js)
    if res.get("error"):
        return {"error": res["error"], "selector": selector}
    out = res.get("result")
    if out == "NOMATCH":
        return {"error": f"no element matches selector {selector!r}",
                "selector": selector, "hint": "check the selector against GET /api/browser/state"}
    if out == "NOTVISIBLE":
        return {"error": f"element for {selector!r} has zero size (hidden or not laid out)",
                "selector": selector}
    if isinstance(out, str) and out.startswith("OK|"):
        _, tag, txt = out.split("|", 2)
        return {"ok": True, "selector": selector, "clicked": {"tag": tag, "text": txt}}
    return {"error": "click produced no result — the eval backend may be down",
            "selector": selector, "raw": res}


def _bu_call(args: list, timeout_s: int = 30, session: str = "amux") -> dict:
    """Logging wrapper over the raw browser-use call.

    Wraps rather than patching each return path: the raw function has seven,
    and an audit trail with a hole in it is worse than none — you would trust
    it. Captures the page the action ran against BEFORE executing, so a
    sequence can be both replayed (what was done, where) and rolled back
    (what the page was before)."""
    # The real verb is the first NON-flag token: several callers lead with
    # `-b real --profile <name>`, which logged the action as "-b" and made the
    # ledger useless for exactly the profile-browser calls it most needed.
    verb, _skip = "", False
    for a in (args or []):
        a = str(a)
        if _skip:
            _skip = False; continue
        if a.startswith("-"):
            _skip = a in ("-b", "--profile", "--browser", "--session", "--timeout", "--amount")
            continue
        verb = a
        break
    before = _bu_page_state(session) if verb in _BU_MUTATING else {}
    t0 = time.time()
    res = _bu_call_raw(args, timeout_s, session)
    ok = not (isinstance(res, dict) and res.get("error"))
    _ilog("browser", verb, actor=session, target=session,
          url=before.get("url", ""), detail={"args": args, "backend": "profile"},
          before=before, result=res, ok=ok, ms=int((time.time() - t0) * 1000))
    return res


def _bu_call_raw(args: list, timeout_s: int = 30, session: str = "amux") -> dict:
    """Run a browser-use CLI command, return parsed JSON result.

    Serialized per-session via lock to prevent concurrent subprocess spawning
    (multiple Chromium launches cause sustained high CPU).
    """
    lock = _browser_lock_for(session)
    if not lock.acquire(timeout=timeout_s + 5):
        return {"error": "browser session busy, try again later"}
    try:
        if args and args[0] != "close":
            _browser_touch(session)
        # Profile-carrying calls get the profile-true daemon (AMUX-2133): the
        # pre-spawn must happen before the CLI's own ensure-server logic runs,
        # or the CLI spawns the hardwired-directory one and wins the lock.
        _sargs = [str(a) for a in (args or [])]
        _env = None
        if "--profile" in _sargs:
            try:
                _pi = _sargs.index("--profile")
                _pname = _sargs[_pi + 1] if _pi + 1 < len(_sargs) else ""
                _env, _pdir = _bu_ensure_profile_env(session, _pname, dict(os.environ))
                # --profile carries the CHROME profile-directory inside the
                # armed store, never the amux name (the name doubled the path
                # into a fresh empty profile — first red of the discriminator).
                if _pdir:
                    _sargs[_pi + 1] = _pdir
                else:
                    del _sargs[_pi:_pi + 2]
                args = _sargs
            except Exception:
                pass
        cmd = [_BROWSER_USE_BIN, "--json", "--session", session] + args
        # Self-heal the transient "SessionManager not initialized" race: the
        # persistent browser-use session server can lag a beat behind /start, so
        # the next action/screenshot lands before it's ready. Retry ONLY that
        # (and empty-output) transient — real command errors return immediately.
        last = None
        for attempt in range(3):
            try:
                r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_s,
                                   env=_env)
            except subprocess.TimeoutExpired:
                return {"error": "browser operation timed out"}
            except Exception as e:
                return {"error": str(e)}
            out = r.stdout.strip()
            if not out:
                last = {"error": r.stderr.strip() or f"browser-use exited {r.returncode}"}
            else:
                try:
                    res = json.loads(out)
                except json.JSONDecodeError:
                    return {"error": out[:200]}
                err = (res.get("error") or "") if isinstance(res, dict) else ""
                if not (err and ("SessionManager" in err or "not initialized" in err)):
                    return res  # success, or a real (non-transient) error
                last = res
            if attempt < 2:
                time.sleep(1.2)
        return last or {"error": "browser call failed"}
    finally:
        lock.release()

# ── Live-Chrome backend (CDP): same /api/browser verbs, executed in the USER'S
# real Chrome (real logins, cookies, residential IP) via skills/chrome-cdp.
# Design (2026-07-17, "get out of the model's way"): amux provides two execution
# surfaces behind ONE tool interface — a profile browser for parallel/unattended
# work, the live browser when acting-as-you matters. No agent loop lives here;
# the session's model does all reasoning against these primitives.
_CDP_SCRIPT = str(Path(__file__).resolve().parent / "skills" / "chrome-cdp" / "scripts" / "cdp.mjs")
_live_targets: dict = {}   # amux browser-session name -> CDP target-id prefix

def _cdp_local_only() -> bool:
    """CDP drives the USER'S OWN Chrome on their machine. A hosted container has
    no such Chrome, and pointing it at one would mean reaching a browser that is
    not the caller's — so the live backend is local-only.

    Detected from capability, not an IS_CLOUD flag: a hosted deployment is the
    one with no DISPLAY (headless linux box), and AMUX_BROWSER_HEADLESS forces
    it explicitly. Local macOS/desktop keeps CDP exactly as it is today."""
    if os.environ.get("AMUX_BROWSER_HEADLESS") == "1":
        return True
    return sys.platform.startswith("linux") and not os.environ.get("DISPLAY")


def _cdp_call(args: list, timeout_s: int = 30) -> dict:
    """Logging wrapper over the live-Chrome CDP call. See _bu_call for why the
    wrap is at this level rather than at the API handlers."""
    if _cdp_local_only():
        return {"error": "live-Chrome (CDP) is local-only — this deployment has no "
                         "desktop Chrome to attach to. Use a Playwright profile "
                         "instead: POST /api/browser/profile/create then /api/browser/start "
                         "with that profile."}
    verb = (args[0] if args else "") or ""
    tid = str(args[1]) if len(args) > 1 else ""
    t0 = time.time()
    res = _cdp_call_raw(args, timeout_s)
    ok = not (isinstance(res, dict) and res.get("error"))
    # The live backend drives the user's OWN Chrome — real logins, real
    # sessions. That makes its audit trail more important than the profile
    # browser's, not less.
    _ilog("browser", verb, actor="live-chrome", target=tid,
          url=(res.get("url") if isinstance(res, dict) else "") or "",
          detail={"args": [str(a) for a in args], "backend": "live-chrome"},
          result=res, ok=ok, ms=int((time.time() - t0) * 1000))
    return res


def _cdp_call_raw(args: list, timeout_s: int = 30) -> dict:
    """Run one cdp.mjs command against the user's real Chrome."""
    try:
        r = subprocess.run(["node", _CDP_SCRIPT] + [str(a) for a in args],
                           capture_output=True, text=True, timeout=timeout_s,
                           cwd=str(Path(__file__).resolve().parent))
    except subprocess.TimeoutExpired:
        return {"error": "live-chrome operation timed out"}
    except FileNotFoundError:
        return {"error": "node not found — the live backend needs Node 22+"}
    out = (r.stdout or "").strip(); err = (r.stderr or "").strip()
    if r.returncode != 0:
        msg = err or out or f"cdp exited {r.returncode}"
        if "Allow" in msg or "Daemon failed" in msg:
            msg += " | live backend drives YOUR Chrome — click 'Allow debugging?' on the tab (first use only)"
        elif "ECONNREFUSED" in msg or "connect" in msg.lower():
            msg += " | enable Chrome remote debugging (relaunch Chrome with --remote-debugging-port=9222)"
        return {"error": msg[:500]}
    return {"ok": True, "output": out}

# Observation budgets: hard caps so a page dump can never flood the session's
# context. The URL is always surfaced as the restorable pointer instead.
# Budget knobs, not constants (ethos dev-4): these bound what the model may SEE,
# which is context-scarcity policy — it belongs in ~/.amux/server.env where it can
# grow with the model's window, not hardcoded where it silently becomes the ceiling.
# Bring sessions back after the container/host they lived in was replaced.
# OFF by default and deliberately so: on a desktop this would launch every
# session in the fleet on every server restart. The cloud gateway sets it per
# user container, where the opposite default is the right one — a session a
# person created should not silently disappear because we shipped an image.
_AUTOSTART_SESSIONS = (os.environ.get("AMUX_AUTOSTART_SESSIONS", "") or "").strip().lower() \
    in ("1", "true", "yes", "on")
_OBS_EVAL_CAP = int(os.environ.get("AMUX_OBS_EVAL_CAP", "8000"))
_OBS_STATE_CAP = int(os.environ.get("AMUX_OBS_STATE_CAP", "24000"))

def _obs_cap(text, limit: int):
    if not isinstance(text, str) or len(text) <= limit:
        return text
    return text[:limit] + f"\n…[truncated at {limit} chars — page stays live; re-query narrower or reopen via the url pointer]"

_CDP_KEYS = {
    "Enter": ("Enter", "Enter", 13, "\r"), "Tab": ("Tab", "Tab", 9, "\t"),
    "Escape": ("Escape", "Escape", 27, ""), "Backspace": ("Backspace", "Backspace", 8, ""),
    "ArrowDown": ("ArrowDown", "ArrowDown", 40, ""), "ArrowUp": ("ArrowUp", "ArrowUp", 38, ""),
    "ArrowLeft": ("ArrowLeft", "ArrowLeft", 37, ""), "ArrowRight": ("ArrowRight", "ArrowRight", 39, ""),
    "PageDown": ("PageDown", "PageDown", 34, ""), "PageUp": ("PageUp", "PageUp", 33, ""),
}

def _live_key(session: str, key: str) -> dict:
    tid = _live_targets.get(session)
    spec = _CDP_KEYS.get(key)
    if not spec:
        return {"error": f"unsupported key {key!r} on live backend (supported: {', '.join(sorted(_CDP_KEYS))})"}
    k, code, vk, text = spec
    events = [{"type": "rawKeyDown", "key": k, "code": code,
               "windowsVirtualKeyCode": vk, "nativeVirtualKeyCode": vk}]
    if text:
        events.append({"type": "char", "text": text, "key": k})
    events.append({"type": "keyUp", "key": k, "code": code,
                   "windowsVirtualKeyCode": vk, "nativeVirtualKeyCode": vk})
    for ev in events:
        r = _cdp_call(["evalraw", tid, "Input.dispatchKeyEvent", json.dumps(ev)], 10)
        if not r.get("ok"):
            return r
    return {"ok": True, "key": key}

def _live_url(session: str) -> str:
    tid = _live_targets.get(session)
    if not tid:
        return ""
    r = _cdp_call(["eval", tid, "location.href"], 10)
    return (r.get("output") or "").strip() if r.get("ok") else ""


def _bu_list_profiles() -> list:
    """List available Chrome profiles via browser-use."""
    try:
        r = subprocess.run(
            [_BROWSER_USE_BIN, "-b", "real", "profile", "list"],
            capture_output=True, text=True, timeout=10,
        )
        profiles = []
        for line in r.stdout.strip().splitlines():
            line = line.strip()
            if line.startswith("Local Chrome") or not line:
                continue
            # Format: "Profile 11: Ethan (email@example.com)"
            if ":" in line:
                name = line.split(":")[0].strip()
                profiles.append(name)
        return profiles
    except Exception:
        return []

# ── Browser profile registry ──────────────────────────────────────────────────
# A "profile" is a named persistent Chrome context: browser-use runs it via
# `-b real --profile <name>`, which reuses the real Chrome user-data-dir with
# <name> as the profile sub-directory. Logging in once under a name persists —
# so the whole game is to ALWAYS run under a named profile and remember which
# domains each is logged into. The registry below is that memory: a small JSON
# mapping profile name -> {domains, label, updated}. It lets us AUTO-SELECT the
# right (already-logged-in) profile from a target URL's host. An agent only has
# to call /api/browser/start with a URL — the matching profile loads itself.
_PROFILES_REGISTRY = CC_HOME / "playwright-auth" / "profiles.json"
_registry_lock = threading.Lock()

_PW_AUTH_DIR = CC_HOME / "playwright-auth"
_PW_PROFILES_DIR = _PW_AUTH_DIR / "profiles"


def _bu_pw_profile_dirs() -> list:
    """Named Playwright persistent-context profiles that exist on disk.

    These are the ones an agent actually launches with
    launchPersistentContext(playwright-auth/profiles/<name>). 'default' is the
    bare playwright-auth/profile directory and is surfaced under that name.
    """
    out = []
    try:
        if _PW_PROFILES_DIR.is_dir():
            out = [p.name for p in _PW_PROFILES_DIR.iterdir()
                   if p.is_dir() and not p.name.startswith(".")]
    except Exception:
        out = []
    # Profiles created since the two stores were unified live in the Chrome
    # user-data-dir. Listing only the legacy location is how a profile could be
    # created successfully and then not appear in the picker at all.
    try:
        cud = _chrome_user_data_dir()
        if cud.is_dir():
            for p in cud.iterdir():
                if not p.is_dir() or p.name.startswith("."):
                    continue
                # Chrome keeps non-profile state (Crashpad, ShaderCache, …)
                # beside the profiles; a profile is the thing with Preferences.
                if (p / "Preferences").exists():
                    out.append(p.name)
    except Exception:
        pass
    try:
        if (_PW_AUTH_DIR / "profile").is_dir():
            out.append("default")
    except Exception:
        pass
    return sorted(set(out))


def _chrome_user_data_dir() -> Path:
    """The Chrome user-data-dir that browser-use's `-b real` mode opens.

    Mirrors browser_use.skill_cli.utils.get_chrome_profile_path(None). A named
    profile is a SUBDIRECTORY of this dir (Chrome's --profile-directory), which
    is the whole reason this function exists: amux used to CREATE profiles with
    Playwright under playwright-auth/profiles/<name> while browsing opened
    <chrome-user-data-dir>/<name>. Two different directories, so signing in
    through the UI could never affect the browser that actually ran — the login
    appeared to save and then silently did nothing.
    """
    if sys.platform == "darwin":
        return Path.home() / "Library" / "Application Support" / "Google" / "Chrome"
    if sys.platform.startswith("win"):
        return Path(os.path.expandvars(r"%LocalAppData%\Google\Chrome\User Data"))
    return Path.home() / ".config" / "google-chrome"


def _bu_profile_dir(name: str):
    """Absolute path for a profile name ('default' maps to the bare dir).

    New profiles live where browser-use will look for them, so create-path and
    use-path are the same bytes. Profiles that already exist in the old location
    keep resolving there — people are logged into those, and relocating them
    would silently sign everyone out.
    """
    n = (name or "").strip()
    if not n or n == "default":
        return _PW_AUTH_DIR / "profile"
    legacy = _PW_PROFILES_DIR / n
    if legacy.is_dir():
        return legacy
    return _chrome_user_data_dir() / n


def _bu_profile_launch_target(name: str):
    """(user_data_dir, profile_directory) for launching a profile.

    Playwright's launchPersistentContext treats its argument as the USER-DATA-DIR
    and nests a Default/ inside it, while Chrome's --profile-directory selects a
    named folder within that dir. Handing Playwright the profile folder itself
    therefore produced <profile>/Default while browser-use read <profile> — the
    off-by-one-level version of the same mismatch.
    """
    d = _bu_profile_dir(name)
    if d.parent == _chrome_user_data_dir():
        return d.parent, d.name       # shared with browser-use `-b real`
    return d, ""                      # legacy/default: the dir IS the user-data-dir


def _bu_profile_size_mb(name: str) -> float:
    """Rough on-disk size. Cheap enough for a listing: Chrome profiles are a few
    hundred files, and the number is what tells you a profile is real and
    logged in versus an empty directory left behind by a crashed run."""
    try:
        d = _bu_profile_dir(name)
        if not d.is_dir():
            return 0.0
        total = 0
        for root, _dirs, files in os.walk(d):
            for f in files:
                try:
                    total += os.path.getsize(os.path.join(root, f))
                except OSError:
                    pass
            if total > 400 * 1024 * 1024:   # stop early; exact size is not the point
                break
        return round(total / 1048576.0, 1)
    except Exception:
        return 0.0


# Headed sign-in window for a NAMED profile. `amux playwright-auth capture`
# only ever wrote the single default profile, so there was no supported way to
# create a named one and log into it — which is why 35 profiles existed on disk
# with an empty registry: every one was made by hand in a throwaway script.
#
# Runs detached so the HTTP request returns immediately; the window stays open
# until the person closes it, and closing the context is what flushes cookies
# and localStorage to disk. cwd is the repo so `require('playwright')` resolves.
_PW_SIGNIN_JS = r"""
const { chromium } = require('playwright');
// argv: <user-data-dir> <profile-directory|""> <url>
// profileDir empty => the user-data-dir IS the profile (legacy/default store).
const dir = process.argv[2], profileDir = process.argv[3] || '',
      url = process.argv[4] || 'about:blank';
(async () => {
  // Headless when no display is available (cloud) — the SAME persistent-context
  // path either way, so a profile captured in one mode is reusable in the other.
  // Capability-driven, never an IS_CLOUD branch: DISPLAY present => headed.
  const headless = process.env.AMUX_BROWSER_HEADLESS === '1'
    || (!process.env.DISPLAY && process.platform === 'linux');
  // Use whatever browser this machine actually has. The cloud image ships
  // branded Chrome only (no playwright-chromium), so launching plain chromium
  // failed silently in a detached process and the profile dir was never
  // created. Try the installed Chrome first, fall back to bundled chromium.
  const opts = {
    headless,
    ignoreHTTPSErrors: true,
    viewport: null,
    args: ['--no-first-run', '--no-default-browser-check']
      // Select the SAME named folder browser-use opens with
      // `-b real --profile <name>`, so the login captured here is the login
      // the browser later runs with.
      .concat(profileDir ? ['--profile-directory=' + profileDir] : []),
  };
  let ctx;
  // A headless launcher must never outlive its job. There is no window for a
  // human to close, and for as long as it lives it HOLDS this profile's Chrome
  // locks — so the next `browser-use -b real --profile <name>` cannot open the
  // profile and silently runs a throwaway temp user-data-dir instead, sending
  // every cookie and localStorage write to /tmp. That is AMUX-2070, and it
  // presents as "the profile saves but never reloads". The code below already
  // closes on the headless path; this covers it HANGING before it gets there
  // (goto, storageState and close are each an await that can stall), because a
  // stall here poisons the profile for the life of the container.
  if (headless) {
    const t = setTimeout(async () => {
      try {
        await Promise.race([
          ctx ? ctx.close() : Promise.resolve(),
          new Promise(r => setTimeout(r, 10000)),
        ]);
      } catch (e) {}
      console.error(JSON.stringify({ ok: false, headless: true,
        error: 'watchdog: launcher exceeded 30s; exiting so the profile lock is released' }));
      process.exit(1);
    }, 30000);
    if (t.unref) t.unref();
  }
  try {
    ctx = await chromium.launchPersistentContext(dir, { ...opts, channel: 'chrome' });
  } catch (e) {
    ctx = await chromium.launchPersistentContext(dir, opts);
  }
  const page = ctx.pages()[0] || await ctx.newPage();
  // 60s is for a HUMAN signing in, where waiting for the page is the point. In
  // headless there is nobody to sign in: the job is to materialize the profile
  // and get out. Waiting longer does not make the profile better, it just holds
  // the profile's Chrome locks — and for as long as they are held, the next
  // `browser-use -b real --profile <name>` cannot open it and silently runs a
  // temp user-data-dir instead. That is AMUX-2070, and it was not a hang: with
  // goto at 60s and the watchdog at 90s, the launcher was ENTITLED to hold the
  // profile for a minute and a half, while the verify starts writing at t+25s.
  // The overlap was the bug.
  try { await page.goto(url, { waitUntil: 'domcontentloaded',
                               timeout: headless ? 15000 : 60000 }); } catch (e) {}
  // Resolve when the user closes the window. Persistent context writes its
  // storage on close, so this is the moment the login becomes reusable.
  if (headless) {
    // No window for a human to close, so the close-to-save handshake cannot
    // apply. Persist immediately: this is what makes a cloud profile reusable.
    const profPath = profileDir ? require('path').join(dir, profileDir) : dir;
    await ctx.storageState({ path: require('path').join(profPath, 'storage-state.json') });
    await ctx.close();
    console.log(JSON.stringify({ ok: true, headless: true, dir: profPath }));
    process.exit(0);
  }
  await new Promise(res => ctx.on('close', res));
  process.exit(0);
})().catch(e => { console.error(String(e)); process.exit(1); });
"""


def _bu_profile_signin(name: str, url: str) -> dict:
    """Open a headed browser under `name` so a human can sign in."""
    safe = re.sub(r"[^A-Za-z0-9._-]", "-", (name or "").strip())[:48]
    if not safe:
        return {"error": "profile name required"}
    d = _bu_profile_dir(safe)
    udd, profdir = _bu_profile_launch_target(safe)
    try:
        d.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        return {"error": f"could not create profile dir: {e}"}
    _log_dir = _PW_PROFILES_DIR
    script = TLS_DIR.parent / "pw-signin.cjs"
    try:
        _log_dir.mkdir(parents=True, exist_ok=True)
        script.write_text(_PW_SIGNIN_JS)
    except Exception as e:
        return {"error": f"could not write launcher: {e}"}
    try:
        # Node resolves require() from the SCRIPT's directory, not cwd — the
        # launcher lives in ~/.amux while playwright is installed beside
        # amux-server.py, so cwd alone gave MODULE_NOT_FOUND and the profile was
        # never created. NODE_PATH makes the resolution explicit and works
        # wherever the two happen to sit.
        _app = Path(__file__).resolve().parent
        _env = dict(os.environ)
        _env["NODE_PATH"] = os.pathsep.join(
            x for x in [str(_app / "node_modules"), _env.get("NODE_PATH", "")] if x)
        subprocess.Popen(
            ["node", str(script), str(udd), profdir, url or "about:blank"],
            cwd=str(_app), env=_env,
            # Launcher logs always land in ONE predictable place, whichever
            # store the profile itself lives in — a log you have to guess the
            # location of is a log nobody reads when the launch fails.
            stdout=open(str(_log_dir / f"{safe}.log"), "ab"),
            stderr=subprocess.STDOUT,
            start_new_session=True,
        )
    except Exception as e:
        return {"error": f"could not launch browser: {e}"}
    return {"ok": True, "profile": safe, "dir": str(d), "url": url,
            "next": "Sign in, then CLOSE the browser window — closing is what saves the session."}


_bu_chrome_cache = {"ts": 0.0, "v": []}


def _bu_list_profiles_cached() -> list:
    """`browser-use profile list` is a subprocess with a 10s timeout, run on
    every profiles fetch. The set of real Chrome profiles changes rarely, so
    cache it for a minute rather than gating the picker on a process spawn."""
    now = time.time()
    if now - _bu_chrome_cache["ts"] < 60 and _bu_chrome_cache["v"]:
        return _bu_chrome_cache["v"]
    v = _bu_list_profiles()
    _bu_chrome_cache.update({"ts": now, "v": v})
    return v


def _bu_registry_load() -> dict:
    try:
        if _PROFILES_REGISTRY.exists():
            data = json.loads(_PROFILES_REGISTRY.read_text())
            return data if isinstance(data, dict) else {}
    except Exception:
        pass
    return {}

def _bu_registry_save(reg: dict) -> bool:
    try:
        _PROFILES_REGISTRY.parent.mkdir(parents=True, exist_ok=True)
        tmp = _PROFILES_REGISTRY.with_name(_PROFILES_REGISTRY.name + ".tmp")
        tmp.write_text(json.dumps(reg, indent=2, sort_keys=True))
        tmp.replace(_PROFILES_REGISTRY)
        return True
    except Exception:
        return False

def _host_of(url: str) -> str:
    """Return the lowercase hostname of a URL (tolerates missing scheme)."""
    try:
        from urllib.parse import urlparse
        u = url if "://" in url else "https://" + url
        return (urlparse(u).hostname or "").lower()
    except Exception:
        return ""

def _domain_matches(host: str, domain: str) -> bool:
    """Suffix match: host equals domain or is a sub-domain of it."""
    host = (host or "").lower().lstrip(".")
    domain = (domain or "").lower().lstrip(".")
    if not host or not domain:
        return False
    return host == domain or host.endswith("." + domain)

def _bu_registry_register(name: str, host: str = "", label: str = "") -> dict:
    """Ensure a profile is registered; add host to its domains. Returns the entry."""
    with _registry_lock:
        reg = _bu_registry_load()
        entry = reg.get(name) if isinstance(reg.get(name), dict) else None
        if entry is None:
            entry = {"domains": [], "label": "", "updated": 0}
        if host and host not in entry["domains"]:
            entry["domains"].append(host)
        if label:
            entry["label"] = label
        entry["updated"] = int(time.time())
        reg[name] = entry
        _bu_registry_save(reg)
        return entry

def _bu_pick_profile(url: str, explicit: str = "") -> tuple:
    """Resolve which profile to use for a URL.

    Explicit wins. Otherwise auto-select the registered profile whose domains
    best (longest / most specific) match the URL's host. Falls back to 'default'.
    Returns (name, auto_selected_bool).
    """
    if explicit:
        return explicit, False
    host = _host_of(url)
    reg = _bu_registry_load()
    best, best_len = None, -1
    for name, meta in reg.items():
        if not isinstance(meta, dict):
            continue
        for dom in (meta.get("domains") or []):
            if _domain_matches(host, dom) and len(dom) > best_len:
                best, best_len = name, len(dom)
    if best:
        return best, True
    return "default", False

def _bu_session_profile(session: str) -> str:
    """Profile the running browser-use session was created with (from its meta), or ''."""
    try:
        import tempfile
        meta = Path(tempfile.gettempdir()) / f"browser-use-{session}.meta"
        if meta.exists():
            return json.loads(meta.read_text()).get("profile") or ""
    except Exception:
        pass
    return ""

def _chrome_user_data_dirs_in_use() -> list:
    """Every --user-data-dir a live Chrome is actually running with.

    Read from the processes themselves, because every other signal here lies.
    browser-use answers a profile-backed open with mode:'real' and the profile
    NAME it was asked for even when its Chrome is on
    /tmp/browser-use-user-data-dir-*, and that response is what sent two
    sessions chasing a directory-resolution bug that had already been ruled out.
    Returns [] when it cannot tell (no /proc, no ps) — the caller must treat
    empty as UNKNOWN, never as "not running".
    """
    dirs, seen = [], set()

    def _add(v):
        v = (v or "").strip()
        if v and v not in seen:
            seen.add(v)
            dirs.append(v)

    # /proc keeps the argv boundaries (NUL-separated), so a path containing a
    # space stays one argument.
    argvs = []
    try:
        proc = Path("/proc")
        if proc.is_dir():
            for p in proc.iterdir():
                if not p.name.isdigit():
                    continue
                try:
                    raw = (p / "cmdline").read_bytes()
                except OSError:
                    continue
                if raw:
                    argvs.append([a.decode("utf-8", errors="replace")
                                  for a in raw.split(b"\0") if a])
    except Exception:
        pass
    if argvs:
        for argv in argvs:
            # Chrome is not the only thing that takes --user-data-dir: every
            # Electron app does. Without this filter the probe reported Docker
            # Desktop's and Granola's directories as "Chrome is running on".
            if not re.search(r"chrom(e|ium)", argv[0], re.I):
                continue
            for tok in argv:
                if tok.startswith("--user-data-dir="):
                    _add(tok.split("=", 1)[1])
        return dirs
    # ps flattens argv into one string, so splitting on whitespace CUTS a path
    # that contains a space — macOS's is
    # "~/Library/Application Support/Google/Chrome", which truncated to
    # ".../Library/Application" and would have reported a correctly-running
    # profile as a mismatch. Match to the next " --" instead.
    try:
        r = subprocess.run(["ps", "-ax", "-o", "command="],
                           capture_output=True, text=True, timeout=8)
    except Exception:
        return []
    for line in r.stdout.splitlines():
        if not re.search(r"chrom(e|ium)", line, re.I):
            continue
        for m in re.finditer(r"--user-data-dir=(.*?)(?=\s+--|$)", line):
            _add(m.group(1))
    return dirs


def _bu_profile_in_use(profile: str) -> dict:
    """Is a live Chrome actually running on the profile we asked for?

    {"verified": True|False|None, ...} — None means undeterminable, which is a
    different answer from False and must not be reported as success.
    """
    try:
        want_udd, _ = _bu_profile_launch_target(profile)
    except Exception:
        return {"verified": None, "why": "could not resolve the profile directory"}
    in_use = _chrome_user_data_dirs_in_use()
    if not in_use:
        return {"verified": None, "why": "no Chrome process readable from here"}
    if str(want_udd) in in_use:
        return {"verified": True, "user_data_dir": str(want_udd)}
    return {"verified": False, "expected_user_data_dir": str(want_udd),
            "actual_user_data_dirs": in_use[:4],
            "why": ("Chrome is running on a different user-data-dir than the profile "
                    "asked for — writes will not persist to that profile")}


_CHROME_SINGLETONS = ("SingletonLock", "SingletonCookie", "SingletonSocket")


def _chrome_locks_present(user_data_dir) -> list:
    """Which Singleton* entries Chrome still holds in a user-data-dir.

    lstat, not exists(): these are symlinks pointing at <host>-<pid>, and
    exists() follows the link, so a LIVE lock whose target is unresolvable
    reads as absent — the check would pass exactly when it should fail.
    """
    out = []
    for n in _CHROME_SINGLETONS:
        try:
            (Path(user_data_dir) / n).lstat()
            out.append(n)
        except OSError:
            pass
    return out


def _chrome_terminate_automation(user_data_dir) -> list:
    """SIGTERM the AUTOMATION Chrome(s) holding `user_data_dir`. Returns pids.

    Deliberately narrow. A process qualifies only if all three hold:
      - it is chrome/chromium,
      - its --user-data-dir is exactly this one,
      - it carries --headless or a --remote-debugging flag.
    That last condition is what keeps a human's own browser safe: a normal
    Chrome window has neither, so this can never close the browser someone is
    using. Only the browser amux itself launched is in scope.

    SIGTERM, never SIGKILL. TERM is the signal Chrome flushes Cookies and Local
    Storage on; KILL is precisely what loses them, which is the bug this exists
    to fix — killing harder would make it worse, not better.
    """
    want = str(user_data_dir)
    killed = []
    try:
        proc = Path("/proc")
        if not proc.is_dir():
            return []          # POSIX-but-no-/proc (macOS): leave it alone
        for p in proc.iterdir():
            if not p.name.isdigit():
                continue
            try:
                argv = [a.decode("utf-8", errors="replace")
                        for a in (p / "cmdline").read_bytes().split(b"\0") if a]
            except OSError:
                continue
            if not argv or not re.search(r"chrom(e|ium)", argv[0], re.I):
                continue
            if not any(a == f"--user-data-dir={want}" for a in argv):
                continue
            if not any(a.startswith("--headless") or a.startswith("--remote-debugging")
                       for a in argv):
                continue      # looks like a human's window — never touch it
            try:
                os.kill(int(p.name), signal.SIGTERM)
                killed.append(int(p.name))
            except (OSError, ValueError):
                continue
    except Exception:
        return killed
    if killed:
        slog(f"[browser] SIGTERM to automation Chrome {killed} on {want} — it "
             f"survived its own close and was holding the profile")
    return killed


def _bu_wait_for_exit(profile: str, timeout_s: float = 8.0) -> dict:
    """Block until Chrome has actually exited after a close, or the wait runs out.

    Chrome writes Cookies and Local Storage on graceful shutdown; a killed
    Chrome never flushes them, which is why a profile could be written, verified
    live in the page, and still come back empty in the next session. The tell is
    the Singleton* symlinks: Chrome removes them on a clean exit and leaves them
    behind when it dies. Returning from /api/browser/stop the moment browser-use
    replies means returning BEFORE that flush, so the caller starts the next
    session against a half-written profile.

    Never kills anything. On a desktop the profile backend shares its
    user-data-dir with the human's own Chrome, so a lingering lock may just mean
    the user has a window open — reporting that honestly is right, killing it
    would not be. Reports rather than raises: `clean_exit` false with the
    remaining locks named is a usable answer, a silent success is not.
    """
    if not profile:
        return {"clean_exit": None,
                "note": "no profile recorded for this session; nothing to wait on"}
    try:
        user_data_dir, _ = _bu_profile_launch_target(profile)
    except Exception as e:
        return {"clean_exit": None, "note": f"could not resolve profile dir: {e}"}
    t0 = time.time()
    remaining = _chrome_locks_present(user_data_dir)
    while remaining and (time.time() - t0) < timeout_s:
        time.sleep(0.25)
        remaining = _chrome_locks_present(user_data_dir)
    out = {"profile": profile, "user_data_dir": str(user_data_dir),
           "clean_exit": not remaining,
           "waited_ms": int((time.time() - t0) * 1000)}
    if remaining:
        # It did not go. Ask the OS, gracefully.
        #
        # SIGTERM is what makes Chrome flush Cookies and Local Storage and drop
        # its Singleton locks — the same path a window close takes. Without this
        # the browser survives its own stop, keeps the profile locked, and the
        # NEXT session cannot open that profile: browser-use silently falls back
        # to a throwaway temp user-data-dir, so the login just written is
        # invisible and the profile looks like it never persisted (AMUX-2070).
        #
        # Only ever an AUTOMATION Chrome on this exact profile: the process must
        # carry --headless or a --remote-debugging flag, which a human's own
        # browser window never does. amux started this browser; stop has to mean
        # stopped. Never SIGKILL — that is the thing that loses the storage.
        killed = _chrome_terminate_automation(user_data_dir)
        if killed:
            t1 = time.time()
            while remaining and (time.time() - t1) < 6:
                time.sleep(0.25)
                remaining = _chrome_locks_present(user_data_dir)
            out["terminated_pids"] = killed
            out["clean_exit"] = not remaining
            out["waited_ms"] = int((time.time() - t0) * 1000)
    if remaining:
        out["locks_remaining"] = remaining
        out["note"] = (f"Chrome still holds {', '.join(remaining)} after {timeout_s:g}s — "
                       f"storage may not be flushed. Another Chrome (e.g. the user's own "
                       f"window) may share this user-data-dir.")
    return out


# ── v3 profile driver (AMUX-2159): amux owns the browser process ───────────
# Five instrument layers proved the CLI+daemon path cannot be made
# profile-true from outside on browser_use 0.12.2 (the launch BrowserProfile
# does not descend from any patched instance). The driver removes every
# intermediary: ONE Playwright persistent context opened directly on the
# amux profile store — no copy, so reads AND writes persist, and the
# desktop-Chrome lock is irrelevant because the store is not the real Chrome
# dir. JSON-lines REPL, one process per amux browser session. The CLI path
# remains for non-profile modes. Acceptance is the seeded-from-source ROUND
# TRIP (amux-cloud's contract): dir equality (profile_verified) is a
# tripwire, never a verdict.
_BU_DRIVER_SRC = r"""
import asyncio, base64, json, sys
async def main():
    udir, headless = sys.argv[1], sys.argv[2] == "1"
    from playwright.async_api import async_playwright
    pw = await async_playwright().start()
    ctx = await pw.chromium.launch_persistent_context(
        udir, headless=headless, ignore_https_errors=True, viewport={"width": 1280, "height": 900})
    page = ctx.pages[0] if ctx.pages else await ctx.new_page()
    print(json.dumps({"ready": True, "user_data_dir": udir}), flush=True)
    loop = asyncio.get_event_loop()
    while True:
        line = await loop.run_in_executor(None, sys.stdin.readline)
        if not line:
            break
        try:
            req = json.loads(line)
        except Exception:
            continue
        rid, verb = req.get("id"), req.get("verb")
        out = {"id": rid, "ok": True}
        try:
            if verb == "open":
                await page.goto(req["url"], wait_until="domcontentloaded", timeout=45000)
                out.update(url=page.url, title=await page.title())
            elif verb == "state":
                txt = await page.evaluate("document.body ? document.body.innerText.slice(0, 4000) : ''")
                out.update(url=page.url, title=await page.title(), text=txt)
            elif verb == "screenshot":
                img = await page.screenshot(full_page=False)
                out.update(b64=base64.b64encode(img).decode())
            elif verb == "click":
                await page.mouse.click(float(req["x"]), float(req["y"]))
            elif verb == "type":
                await page.keyboard.type(str(req.get("text", "")), delay=20)
            elif verb == "keys":
                await page.keyboard.press(str(req.get("key", "Enter")))
            elif verb == "eval":
                out.update(value=await page.evaluate(str(req.get("js", ""))))
            elif verb == "cookies":
                out.update(cookies=await ctx.cookies())
            elif verb == "set_cookie":
                await ctx.add_cookies([req["cookie"]])
            elif verb == "close":
                await ctx.close()
                await pw.stop()
                print(json.dumps({"id": rid, "ok": True, "closed": True}), flush=True)
                return
            else:
                out = {"id": rid, "ok": False, "error": "unknown verb: %s" % verb}
        except Exception as e:
            out = {"id": rid, "ok": False, "error": str(e)[:300]}
        print(json.dumps(out), flush=True)
asyncio.run(main())
"""

_bu_drivers: dict = {}          # session -> {proc, profile, udir}
_bu_driver_lock = threading.Lock()

def _bu_driver_stop(session: str):
    d = _bu_drivers.pop(session, None)
    if not d:
        return
    try:
        d["proc"].stdin.write('{"id":"x","verb":"close"}\n')
        d["proc"].stdin.flush()
        d["proc"].wait(timeout=8)
    except Exception:
        try:
            d["proc"].kill()
        except Exception:
            pass

def _bu_driver_call(session: str, profile: str, verb: str, params: dict | None = None,
                    timeout_s: int = 45) -> dict:
    """Run a verb against the profile-true driver, spawning it on demand.
    Returns {ok, ...} or {error}. Serialized per session."""
    with _bu_driver_lock:
        d = _bu_drivers.get(session)
        if d and (d["profile"] != profile or d["proc"].poll() is not None):
            _bu_driver_stop(session)
            d = None
        if not d:
            udir, _pdir = _bu_profile_launch_target(profile)
            # Interpreter: the server's own python may not have playwright
            # (the first live spawn died at import with stderr on DEVNULL —
            # 'driver failed to start: <empty>', undiagnosable). stderr is now
            # captured into the error, and the interpreter is configurable.
            _py = os.environ.get("AMUX_BU_DRIVER_PYTHON") or sys.executable
            proc = subprocess.Popen(
                [_py, "-c", _BU_DRIVER_SRC, str(udir), "1"],
                stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                stderr=subprocess.PIPE, text=True)
            ready = proc.stdout.readline()
            try:
                if not json.loads(ready or "{}").get("ready"):
                    raise ValueError(ready[:200])
            except Exception as e:
                try:
                    _err = (proc.stderr.read() or "")[-400:]
                except Exception:
                    _err = ""
                try: proc.kill()
                except Exception: pass
                return {"error": f"driver failed to start: {e} :: {_err}".strip()}
            d = {"proc": proc, "profile": profile, "udir": str(udir)}
            _bu_drivers[session] = d
            slog(f"[browser] v3 driver up session={session} profile={profile!r} store={udir}")
        req = dict(params or {})
        req.update(id="r", verb=verb)
        try:
            d["proc"].stdin.write(json.dumps(req) + "\n")
            d["proc"].stdin.flush()
            import select as _select
            r, _, _ = _select.select([d["proc"].stdout], [], [], timeout_s)
            if not r:
                return {"error": "driver timeout"}
            line = d["proc"].stdout.readline()
            res = json.loads(line or "{}")
            if res.get("closed"):
                _bu_drivers.pop(session, None)
            return res
        except Exception as e:
            _bu_driver_stop(session)
            return {"error": f"driver io: {e}"}


def _bu_active_driver(session: str):
    """The live v3 driver for this session, or None. See _bu_eval."""
    with _bu_driver_lock:
        d = _bu_drivers.get(session)
        if d and d["proc"].poll() is None:
            return d
    return None


def _bu_eval(session: str, js: str, timeout_s: int = 20) -> dict:
    """Evaluate JS against the browser that is ACTUALLY driving this session.

    THE BUG THIS EXISTS FOR (AMUX-2272). /api/browser/start and /navigate route
    to the v3 Playwright driver when the profile resolves to an amux-managed
    store, and return early. But every verb under /api/browser/action went
    straight to _bu_call, which shells out to the browser-use CLI — a DIFFERENT
    browser process that nobody had navigated. So /state (driver) showed the
    dashboard while /action eval (CLI) reported about:blank, and a selector
    click reported "no element matches" against a blank page.

    Two sessions independently concluded the browser API was broken, and both
    conclusions were the honest reading of the data available: every symptom
    was real, and every diagnosis pointed at the wrong layer, because the two
    halves of the API were driving different browsers and nothing said so. I
    first blamed the self-signed certificate on amux's own origin — plausible,
    and wrong; the driver had loaded the dashboard fine all along.

    Returns {"ok": True, "result": <value>} or {"error": ...}."""
    d = _bu_active_driver(session)
    if d:
        r = _bu_driver_call(session, d["profile"], "eval", {"js": js}, timeout_s=timeout_s)
        if r.get("ok"):
            return {"ok": True, "result": r.get("value"), "backend": "driver"}
        return {"error": r.get("error") or "driver eval failed", "backend": "driver"}
    r = _bu_call(["eval", js], session=session, timeout_s=timeout_s)
    if isinstance(r, dict) and r.get("error"):
        return {"error": r["error"], "backend": "cli"}
    return {"ok": True, "result": ((r or {}).get("data") or {}).get("result"), "backend": "cli"}


def _bu_landing_check(url: str, session: str) -> dict:
    """Did the page we asked for actually LOAD? Returns {} when fine.

    `open` echoes the REQUESTED url and reports success whether or not the
    navigation worked. Chromium lands on chrome-error://chromewebdata/ when it
    refuses a page — which it does for amux's OWN dashboard, because the server
    serves a self-signed cert and the driver's Chromium has no exception for it.

    That combination cost two sessions a day of work on the same afternoon
    (AMUX-2272): every later verb ran against the error page, so a selector
    click reported "no element matches" and the honest conclusion from the
    available data was "selector clicks are broken" — when the truth was "you
    are not on the page you think you are". An open that cannot fail sends the
    caller to debug the wrong layer, which is the ethos-#7 shape applied to an
    instrument rather than a check."""
    try:
        r = _bu_eval(session, "location.href", timeout_s=15)
        landed = r.get("result")
        if not isinstance(landed, str):
            return {}
        if landed.startswith("chrome-error://"):
            return {"nav_failed": True, "landed": landed,
                    "why": (f"Chromium refused to load {url}. For amux's own https://localhost"
                            " this is the self-signed certificate — the driver's browser has no"
                            " exception for it."),
                    "hint": "every subsequent verb runs against the error page, not your page"}
        if landed == "about:blank" and url and url != "about:blank":
            return {"nav_failed": True, "landed": landed,
                    "why": f"navigation to {url} left the page on about:blank",
                    "hint": "every subsequent verb runs against a blank page, not your page"}
    except Exception:
        pass
    return {}


def _bu_open(url: str, session: str = "amux", explicit_profile: str = "",
             fresh: bool = False, timeout_s: int = 30) -> dict:
    """Open a URL under the correct profile.

    Auto-selects a registered profile by domain when explicit_profile is empty,
    so callers/agents stay logged in without tracking cookies themselves. The
    session is (re)created with the resolved profile when the currently running
    session uses a different one — that's what makes `-b real --profile` login
    persistence actually take effect. Same-profile navigation reuses the session.
    The response carries `profile` (chosen) and `auto_profile` (was it inferred).
    """
    profile, auto = _bu_pick_profile(url, explicit_profile)
    cur = _bu_session_profile(session)
    if cur and cur == profile and not fresh:
        res = _bu_call(["open", url], session=session, timeout_s=timeout_s)
    else:
        if cur:  # existing session runs a different profile — close before reopening
            _bu_call(["close"], session=session, timeout_s=10)
        # v3 driver (AMUX-2159 increment 2): profile sessions on amux-managed
        # stores run through OUR Playwright persistent context — no CLI, no
        # daemon, no copy; reads AND writes persist (the 0.12.2 copy ceiling
        # is structural, proven at five instrumented layers). Legacy stores
        # resolve to (dir, "") — that discriminator picks the driver. CLI
        # remains for non-profile modes and as the fallback if the driver
        # cannot start.
        _udir, _pdir = _bu_profile_launch_target(profile)
        if _pdir == "" and Path(_udir).exists():
            dres = _bu_driver_call(session, profile, "open", {"url": url},
                                   timeout_s=timeout_s)
            if dres.get("ok"):
                _land = _bu_landing_check(url, session)
                return {**_land, "success": not _land, "ok": not _land, "backend": "driver",
                        "profile": profile, "auto_profile": auto,
                        "url": dres.get("url", url), "title": dres.get("title", ""),
                        "writes_persist": True,
                        # REGIME NOTE (amux-cloud, 2026-08-02): under CLI copy
                        # semantics this field was a failure detector and a
                        # useless success detector. On the driver backend it is
                        # true BY CONSTRUCTION, so a FALSE here now means "the
                        # CLI fallback fired" — same field, opposite job: a
                        # clean fallback tripwire, never a success verdict. The
                        # cookie round trip remains the only verdict.
                        "profile_verified": True,
                        "profile_verified_note": ("driver holds the store open "
                                                  "directly — no temp copy exists")}
            slog(f"[browser] v3 driver failed for {session}/{profile}: "
                 f"{dres.get('error')!r} — falling back to CLI path")
        res = _bu_call(["-b", "real", "--profile", profile, "open", url],
                       session=session, timeout_s=timeout_s)
        # Graceful fallback: if real-Chrome mode can't launch, browse anyway
        if isinstance(res, dict) and res.get("error"):
            fb = _bu_call(["open", url], session=session, timeout_s=timeout_s)
            if isinstance(fb, dict) and not fb.get("error"):
                fb["profile"] = profile
                fb["auto_profile"] = auto
                fb["profile_fallback"] = True
                return fb
    if isinstance(res, dict):
        res = dict(res)
        res["profile"] = profile
        res["auto_profile"] = auto
        # `profile` above is what we ASKED for. Say what we actually GOT: a
        # caller that trusts the request echo has no way to learn its writes are
        # landing in a temp dir, which is precisely how this stayed misdiagnosed.
        if not res.get("error"):
            chk = _bu_profile_in_use(profile)
            res["profile_verified"] = chk.get("verified")
            if chk.get("verified") is False:
                res["profile_warning"] = chk["why"]
                res["actual_user_data_dirs"] = chk.get("actual_user_data_dirs")
                slog(f"[browser] profile '{profile}' requested but Chrome is on "
                     f"{chk.get('actual_user_data_dirs')} — writes will not persist")
        # Re-install the console/network capture shim on every navigation (page
        # globals reset on load) so /api/browser/inspect can troubleshoot the page.
        if not res.get("error"):
            try: _bu_inject_capture(session)
            except Exception: pass
        # Report the LANDING, not the request. See _bu_landing_check.
        if not res.get("error"):
            _land = _bu_landing_check(url, session)
            if _land:
                res.update(_land)
                res["success"] = False
                res["ok"] = False
                res["error"] = _land["why"]
    return res

def _bu_parse_elements(raw_text: str, limit: int = 120) -> dict:
    """Parse browser-use `state` _raw_text into {viewport, elements[]}.

    _raw_text lines look like:  [1102]<button />   then an indented label line.
    Returns numbered, index-addressable elements for ref-based clicking — the
    structured (accessibility-first) perception surface, more reliable than
    pixel clicking.
    """
    vp = None
    els = []
    if not raw_text:
        return {"viewport": vp, "elements": els}
    el_re = re.compile(r"^(\s*)\*?\[(\d+)\]<([a-zA-Z0-9\-]+)([^>]*?)/?>\s*$")
    attr_label_re = re.compile(r'(?:aria-label|id|role|name|placeholder|value)=([^\s/>]+)')
    lines = raw_text.splitlines()
    for i, line in enumerate(lines):
        if vp is None and line.startswith("viewport:"):
            m = re.search(r"(\d+)\s*x\s*(\d+)", line)
            if m:
                vp = {"w": int(m.group(1)), "h": int(m.group(2))}
            continue
        m = el_re.match(line)
        if not m:
            continue
        indent, idx, tag, attrs = m.groups()
        # Label: prefer a following deeper-indented text (non-bracket) line
        label = ""
        for j in range(i + 1, min(i + 4, len(lines))):
            nxt = lines[j]
            if "[" in nxt and "]<" in nxt:
                break
            t = nxt.strip()
            if t and not t.startswith("|") and not t.startswith("<"):
                label = t
                break
        if not label:
            am = attr_label_re.search(attrs or "")
            if am:
                label = am.group(1)
        els.append({"index": int(idx), "tag": tag, "label": label[:80]})
        if len(els) >= limit:
            break
    return {"viewport": vp, "elements": els}

def _bu_screenshot(session: str = "amux", path: str = "", retries: int = 3) -> dict:
    """Take a screenshot, return {path, size}. Retries on SessionManager errors."""
    dest = path or str(CC_HOME / "browser-screenshots" / "latest.jpg")
    Path(dest).parent.mkdir(parents=True, exist_ok=True)
    for attempt in range(retries):
        result = _bu_call(["screenshot", dest], session=session)
        if result.get("success"):
            try:
                size = Path(dest).stat().st_size
            except Exception:
                size = 0
            return {"path": dest, "size": size}
        err = result.get("error", "")
        if "SessionManager" in err and attempt < retries - 1:
            import time as _t; _t.sleep(1.5)
            continue
        return result
    return result

# ── Browser troubleshooting: console / network / error capture ────────────────
# browser-use is subprocess-per-action, so we can't hold a live CDP listener.
# Instead we inject an idempotent capture shim into the page (re-injected on every
# navigation by _bu_open) that mirrors console.*, fetch, and XHR into page-global
# ring buffers, plus window error/unhandledrejection. Network is additionally
# back-filled from the Resource Timing API (performance.getEntriesByType), which
# retroactively lists EVERY request — even ones that fired before injection.
_BROWSER_CAPTURE_JS = r"""
(function(){
  if (window.__amux && window.__amux.__installed) return 'already';
  var CAP = 500;
  var S = window.__amux = window.__amux || {};
  S.console = S.console || []; S.net = S.net || []; S.errors = S.errors || [];
  S.__installed = true;
  var now = function(){ return Date.now(); };
  function push(a, x){ a.push(x); if (a.length > CAP) a.shift(); }
  function fmt(a){
    try {
      if (a instanceof Error) return a.stack || (a.name + ': ' + a.message);
      if (typeof a === 'object' && a !== null) { try { return JSON.stringify(a); } catch(e){ return String(a); } }
      return String(a);
    } catch(e){ return '[unserializable]'; }
  }
  ['log','info','warn','error','debug'].forEach(function(level){
    var orig = console[level]; if (!orig) return;
    console[level] = function(){
      try { push(S.console, { level: level, text: [].map.call(arguments, fmt).join(' '), ts: now() }); } catch(e){}
      return orig.apply(console, arguments);
    };
  });
  window.addEventListener('error', function(e){
    push(S.errors, { text: (e.message || 'error') + (e.filename ? (' @ ' + e.filename + ':' + e.lineno + ':' + e.colno) : ''),
                     stack: (e.error && e.error.stack) || '', ts: now() });
  });
  window.addEventListener('unhandledrejection', function(e){
    var r = e.reason; push(S.errors, { text: 'unhandledrejection: ' + ((r && r.message) || fmt(r)), stack: (r && r.stack) || '', ts: now() });
  });
  if (window.fetch) {
    var of = window.fetch;
    window.fetch = function(input, init){
      var url = (typeof input === 'string') ? input : (input && input.url) || '';
      var method = (init && init.method) || (input && input.method) || 'GET';
      var t0 = now();
      return of.apply(this, arguments).then(function(res){
        push(S.net, { type:'fetch', method:method, url:url, status:res.status, ok:res.ok, ms: now()-t0, ts: t0 }); return res;
      }, function(err){
        push(S.net, { type:'fetch', method:method, url:url, status:0, ok:false, error:String(err), ms: now()-t0, ts: t0 }); throw err;
      });
    };
  }
  var OX = window.XMLHttpRequest;
  if (OX) {
    var NX = function(){
      var xhr = new OX();
      var rec = { type:'xhr', method:'GET', url:'', status:0, ok:false, ms:0, ts: now() };
      var open = xhr.open;
      xhr.open = function(m, u){ rec.method = m; rec.url = u; return open.apply(xhr, arguments); };
      var send = xhr.send;
      xhr.send = function(){ var t0 = now();
        xhr.addEventListener('loadend', function(){ rec.status = xhr.status; rec.ok = (xhr.status >= 200 && xhr.status < 400); rec.ms = now()-t0; push(S.net, rec); });
        return send.apply(xhr, arguments); };
      return xhr;
    };
    NX.prototype = OX.prototype; window.XMLHttpRequest = NX;
  }
  return 'installed';
})()
"""

_BROWSER_INSPECT_JS = r"""
(function(){
  var S = window.__amux || {};
  var L = __LIMIT__;
  function tail(a){ a = a || []; return a.slice(Math.max(0, a.length - L)); }
  var res = [];
  try {
    res = performance.getEntriesByType('resource').slice(-L).map(function(e){
      return { url:e.name, type:e.initiatorType, ms:Math.round(e.duration), size:e.transferSize||0, start:Math.round(e.startTime) };
    });
  } catch(e){}
  var out = { url: location.href, title: document.title, installed: !!S.__installed,
    console: tail(S.console), network: tail(S.net), errors: tail(S.errors), resources: res,
    counts: { console:(S.console||[]).length, network:(S.net||[]).length, errors:(S.errors||[]).length, resources:res.length } };
  if (__CLEAR__) { if (S.console) S.console.length = 0; if (S.net) S.net.length = 0; if (S.errors) S.errors.length = 0; }
  return out;
})()
"""

def _bu_inject_capture(session: str = "amux") -> dict:
    """Inject the console/network/error capture shim (idempotent per page)."""
    return _bu_call(["eval", _BROWSER_CAPTURE_JS], session=session, timeout_s=15)

def _bu_inspect(session: str = "amux", clear: bool = False, limit: int = 200) -> dict:
    """Read captured console/network/errors (+ Resource Timing) from the page."""
    js = (_BROWSER_INSPECT_JS
          .replace("__LIMIT__", str(int(limit)))
          .replace("__CLEAR__", "true" if clear else "false"))
    res = _bu_call(["eval", js], session=session, timeout_s=15)
    if not isinstance(res, dict) or res.get("error"):
        return res if isinstance(res, dict) else {"error": "inspect failed"}
    data = (res.get("data") or {}).get("result")
    if isinstance(data, str):
        try: data = json.loads(data)
        except Exception: pass
    if isinstance(data, dict):
        # If the shim isn't installed (e.g. page navigated), still return Resource Timing.
        return data
    return {"error": "no capture data", "raw": data}


def _resolve_claude_bin() -> str:
    """Locate the claude CLI binary (PATH first, then common install locations)."""
    found = shutil.which("claude")
    if found:
        return found
    for p in (Path.home() / ".local" / "bin" / "claude",
              Path.home() / ".claude" / "local" / "claude",
              Path("/usr/local/bin/claude"),
              Path("/opt/homebrew/bin/claude")):
        if p.exists():
            return str(p)
    return ""


def _on_claude_plan() -> bool:
    """True when logged in via OAuth (a Claude Plan), independent of any API key."""
    try:
        cj = Path.home() / ".claude.json"
        if cj.exists():
            return bool(json.loads(cj.read_text()).get("oauthAccount"))
    except Exception:
        pass
    return False


_usage_cache = {"data": None, "time": 0.0}
_USAGE_TTL = 30  # seconds — the modal can be reopened without hammering Anthropic


def _claude_oauth_token():
    """Best-effort read of the Claude Code subscription OAuth token — macOS
    keychain first, then ~/.claude/.credentials.json. Returns (token, expires_ms)
    or (None, 0). Cloud hosts have neither, so usage simply reports unavailable —
    no IS_CLOUD branch, just presence/absence of the credential."""
    try:
        r = subprocess.run(
            ["security", "find-generic-password", "-s", "Claude Code-credentials", "-w"],
            capture_output=True, text=True, timeout=5)
        if r.returncode == 0 and r.stdout.strip():
            d = json.loads(r.stdout).get("claudeAiOauth", {})
            if d.get("accessToken"):
                return d["accessToken"], int(d.get("expiresAt") or 0)
    except Exception:
        pass
    try:
        p = Path.home() / ".claude" / ".credentials.json"
        if p.exists():
            d = json.loads(p.read_text()).get("claudeAiOauth", {})
            if d.get("accessToken"):
                return d["accessToken"], int(d.get("expiresAt") or 0)
    except Exception:
        pass
    return None, 0


def _fetch_claude_usage() -> dict:
    """Fetch subscription usage from Claude Code's OAuth usage endpoint. The
    `limits` array is model-agnostic — session (5h) + weekly, plus per-model
    `weekly_scoped` entries carrying scope.model.display_name — so the UI reads
    it the same regardless of which of the models is in use."""
    token, exp = _claude_oauth_token()
    if not token:
        return {"available": False, "reason": "No Claude subscription token on this host"}
    if exp and int(time.time() * 1000) > exp:
        return {"available": False, "reason": "Token expired — run any Claude command to refresh it"}
    try:
        req = urllib.request.Request(
            "https://api.anthropic.com/api/oauth/usage",
            headers={"Authorization": f"Bearer {token}",
                     "anthropic-beta": "oauth-2025-04-20",
                     "anthropic-version": "2023-06-01"})
        with urllib.request.urlopen(req, timeout=10, context=_push_ssl_context()) as resp:
            data = json.loads(resp.read().decode())
        data["available"] = True
        return data
    except urllib.error.HTTPError as e:
        if e.code == 401:
            return {"available": False, "reason": "Token rejected (401) — run any Claude command to refresh it"}
        return {"available": False, "reason": f"Usage fetch failed (HTTP {e.code})"}
    except Exception as e:
        return {"available": False, "reason": f"Usage fetch failed: {e}"}


# One knob for every helper one-shot (ethos dev-3). Pinning a named weak model
# in 5 separate call sites was a bet that could not improve as models improve —
# and the throttle its cost forced is why most commands never reached the board.
# Set AMUX_HELPER_MODEL (CLI alias) / AMUX_HELPER_MODEL_API (full API id) in
# ~/.amux/server.env to move the whole fleet's helper tier in one line.
_HELPER_MODEL = os.environ.get("AMUX_HELPER_MODEL", "haiku")
_HELPER_MODEL_API = os.environ.get("AMUX_HELPER_MODEL_API", "claude-haiku-4-5-20251001")

def _claude_oneshot(prompt: str, model: str = None, timeout: int = 35) -> tuple:
    """Run a one-shot headless `claude -p` query using the active Claude Code
    session's auth — Plan OAuth or API key, whichever the CLI is configured with.

    Returns (text, error). Mirrors amux's session launch: when on a Plan, the
    ANTHROPIC_API_KEY is unset so the subscription is used rather than a key.
    """
    model = model or _HELPER_MODEL
    claude_bin = _resolve_claude_bin()
    if not claude_bin:
        return ("", "claude CLI not found")
    env = dict(os.environ)
    env.pop("CLAUDECODE", None)
    env.pop("CLAUDE_CODE_ENTRYPOINT", None)
    if _on_claude_plan():
        env.pop("ANTHROPIC_API_KEY", None)
    try:
        r = subprocess.run(
            [claude_bin, "-p", prompt, "--model", model],
            capture_output=True, text=True, timeout=timeout,
            cwd=str(CC_HOME), env=env)
        if r.returncode != 0:
            return ("", (r.stderr or r.stdout or "claude exited non-zero").strip()[:500])
        return (r.stdout.strip(), "")
    except subprocess.TimeoutExpired:
        return ("", "lookup timed out")
    except Exception as e:
        return ("", str(e))


# Peek "Look up" should ride whatever provider the peeked session already uses,
# on that provider's fastest/lightest model — so a Gemini- or Ollama-only setup
# doesn't need an Anthropic key just to explain a snippet. Not the session's own
# (possibly heavy) model: the point is a cheap, snappy answer.
_PROVIDER_LOOKUP_MODEL = {
    "claude": _HELPER_MODEL,
    "gemini": "gemini-2.5-flash-lite",
    "codex":  "gpt-5-mini",
}


def _session_provider(name: str) -> str:
    if not name:
        return "claude"
    try:
        cfg = parse_env_file(CC_SESSIONS / f"{name}.env")
        return (cfg.get("CC_PROVIDER") or "claude").strip().lower() or "claude"
    except Exception:
        return "claude"


def _session_model_flag(name: str) -> str:
    try:
        cfg = parse_env_file(CC_SESSIONS / f"{name}.env")
        m = re.search(r'(?:--model|-m)\s+(\S+)', cfg.get("CC_FLAGS", "") or "")
        return m.group(1) if m else ""
    except Exception:
        return ""


def _ollama_first_model() -> str:
    """Smallest sensible default: the first model `ollama list` reports."""
    try:
        ob = shutil.which("ollama")
        if not ob:
            return ""
        r = subprocess.run([ob, "list"], capture_output=True, text=True, timeout=5)
        for line in r.stdout.splitlines()[1:]:
            parts = line.split()
            if parts:
                return parts[0]
    except Exception:
        pass
    return ""


def _lookup_via_claude(prompt: str, timeout: int = 35) -> tuple:
    """Claude haiku one-shot — SDK when an API key is present and not on a Plan,
    else the claude CLI (OAuth subscription). This is the universal fallback."""
    api_key = os.environ.get("ANTHROPIC_API_KEY", "")
    if api_key and not _on_claude_plan():
        try:
            import anthropic as _anthropic
            client = _anthropic.Anthropic(api_key=api_key)
            msg = client.messages.create(
                model=_HELPER_MODEL_API, max_tokens=400,
                messages=[{"role": "user", "content": prompt}],
            )
            return (msg.content[0].text.strip(), "")
        except Exception as e:
            return ("", str(e))
    return _claude_oneshot(prompt, timeout=timeout)


def _lookup_via_provider(provider: str, prompt: str, name: str = "", timeout: int = 35) -> tuple:
    """Try the session provider's fastest model via its CLI. Returns (text, err);
    empty text means the caller should fall back to _lookup_via_claude. codex and
    unknown providers fall straight through (codex exec is agentic/verbose — no
    clean one-shot completion, so we don't parse it here)."""
    try:
        if provider == "gemini":
            gem = shutil.which("gemini")
            if gem:
                env = dict(os.environ)
                env["GEMINI_CLI_TRUST_WORKSPACE"] = "true"
                env.pop("CLAUDECODE", None)
                env.pop("CLAUDE_CODE_ENTRYPOINT", None)
                r = subprocess.run(
                    [gem, "-p", prompt, "-m", _PROVIDER_LOOKUP_MODEL["gemini"]],
                    capture_output=True, text=True, timeout=timeout, cwd=str(CC_HOME), env=env)
                if r.returncode == 0 and r.stdout.strip():
                    return (r.stdout.strip(), "")
        elif provider == "ollama":
            ob = shutil.which("ollama")
            model = _session_model_flag(name) or _ollama_first_model()
            if ob and model:
                r = subprocess.run(
                    [ob, "run", model, prompt],
                    capture_output=True, text=True, timeout=timeout, cwd=str(CC_HOME))
                if r.returncode == 0 and r.stdout.strip():
                    return (r.stdout.strip(), "")
    except Exception:
        pass
    return ("", "")   # fall back to claude


def _bu_agent_run(task: str, session: str = "amux-agent", profile: str = "default",
                  start_url: str = "", max_iterations: int = 25,
                  model: str = "claude-sonnet-4-5") -> dict:
    """Run an Anthropic Computer Use agent loop driving the browser-use Playwright session.

    The model takes screenshots, decides actions, and we execute them via _bu_call.
    Default model is Sonnet 4.5 because computer use is canonically a Sonnet feature;
    pass model='claude-opus-4-6' or similar to override.
    """
    try:
        import anthropic
    except ImportError:
        return {"error": "anthropic package not installed (pip install anthropic)"}
    import base64

    # Ensure session is open
    if profile and start_url:
        _bu_call(["-b", "real", "--profile", profile, "open", start_url], session=session, timeout_s=30)
    elif profile:
        _bu_call(["-b", "real", "--profile", profile, "open", "about:blank"], session=session, timeout_s=30)
    elif start_url:
        _bu_call(["open", start_url], session=session, timeout_s=30)
    else:
        _bu_call(["open", "about:blank"], session=session, timeout_s=30)

    DISPLAY_W, DISPLAY_H = 1280, 800

    # Computer Use requires a real Anthropic API key — there is NO Plan/OAuth path
    # for it (unlike the lookup/task-label CLI shots, which ride the subscription).
    # This machine runs the claude CLI on OAuth with ANTHROPIC_API_KEY unset, so a
    # bare anthropic.Anthropic() 401s at call time with an opaque error (gtm-videos
    # hit this on /record, 2026-07-14). Read a DEDICATED key so the browser agent
    # can be enabled without setting the global ANTHROPIC_API_KEY — which would
    # switch every claude session, the lookup, and task-labels to per-token API
    # billing instead of the Plan subscription. Fail loud and actionable otherwise.
    _bu_key = os.environ.get("AMUX_ANTHROPIC_API_KEY") or os.environ.get("ANTHROPIC_API_KEY")
    if not _bu_key:
        return {"error": "browser agent needs an Anthropic API key",
                "detail": "Computer Use has no Plan/OAuth path. Set AMUX_ANTHROPIC_API_KEY "
                          "in ~/.amux/server.env (a key scoped to the browser agent only — this "
                          "does NOT switch your claude sessions to API-key billing), then "
                          "`touch amux-server.py`. Until then, drive the browser with the "
                          "raw browser API / Playwright (/api/browser/*), which uses your saved "
                          "auth profiles and needs no model key."}
    try:
        client = anthropic.Anthropic(api_key=_bu_key)
    except Exception as e:
        return {"error": f"failed to init Anthropic client: {e}"}

    def _shot_b64():
        s = _bu_screenshot(session=session)
        p = s.get("path", "")
        if not p or not Path(p).exists():
            return None, None, f"screenshot failed: {s}"
        try:
            data = Path(p).read_bytes()
            # Detect media type from magic bytes (browser-use may write PNG to .jpg path)
            if data[:8] == b"\x89PNG\r\n\x1a\n":
                media = "image/png"
            elif data[:3] == b"\xff\xd8\xff":
                media = "image/jpeg"
            elif data[:6] in (b"GIF87a", b"GIF89a"):
                media = "image/gif"
            elif data[:4] == b"RIFF" and data[8:12] == b"WEBP":
                media = "image/webp"
            else:
                media = "image/png"
            return base64.standard_b64encode(data).decode(), media, None
        except Exception as e:
            return None, None, str(e)

    def _exec_action(inp):
        a = inp.get("action", "")
        coord = inp.get("coordinate") or [0, 0]
        x, y = (coord + [0, 0])[:2]
        text = inp.get("text", "")
        try:
            if a == "screenshot":
                pass
            elif a == "left_click":
                _bu_call(["click", str(int(x)), str(int(y))], session=session)
            elif a == "double_click":
                _bu_call(["click", str(int(x)), str(int(y))], session=session)
                time.sleep(0.1)
                _bu_call(["click", str(int(x)), str(int(y))], session=session)
            elif a == "triple_click":
                for _ in range(3):
                    _bu_call(["click", str(int(x)), str(int(y))], session=session)
                    time.sleep(0.05)
            elif a == "right_click":
                _bu_call(["eval",
                    f"(()=>{{const el=document.elementFromPoint({int(x)},{int(y)});"
                    f"if(el)el.dispatchEvent(new MouseEvent('contextmenu',{{bubbles:true,clientX:{int(x)},clientY:{int(y)}}}));}})()"
                ], session=session)
            elif a == "middle_click":
                _bu_call(["click", str(int(x)), str(int(y))], session=session)
            elif a == "type":
                _bu_call(["type", text], session=session)
            elif a == "key":
                _bu_call(["keys", text], session=session)
            elif a == "scroll":
                direction = inp.get("scroll_direction", "down")
                amount = max(1, int(inp.get("scroll_amount", 3))) * 100
                _bu_call(["scroll", direction, "--amount", str(amount)], session=session)
            elif a == "wait":
                time.sleep(min(float(inp.get("duration", 1)), 10))
            elif a in ("mouse_move", "left_mouse_down", "left_mouse_up", "cursor_position", "hold_key"):
                pass  # no-op (browser-use doesn't expose hover/drag)
            else:
                return {"is_error": True, "text": f"unsupported action: {a}"}
        except Exception as e:
            return {"is_error": True, "text": f"action {a} failed: {e}"}
        b64, media, err = _shot_b64()
        if err:
            return {"is_error": True, "text": err}
        return {"image_b64": b64, "media": media}

    tools = [{
        "type": "computer_20250124",
        "name": "computer",
        "display_width_px": DISPLAY_W,
        "display_height_px": DISPLAY_H,
    }]
    messages = [{"role": "user", "content": task}]
    action_log = []
    final_text = ""
    iterations = 0

    for it in range(max_iterations):
        iterations = it + 1
        try:
            resp = client.beta.messages.create(
                model=model,
                max_tokens=4096,
                tools=tools,
                messages=messages,
                betas=["computer-use-2025-01-24"],
            )
        except Exception as e:
            return {"error": f"anthropic call failed: {e}", "iterations": iterations, "log": action_log}

        # Re-serialize content blocks to plain dicts so we can append
        assistant_content = []
        tool_uses = []
        for block in resp.content:
            try:
                d = block.model_dump(exclude_none=True)
            except Exception:
                d = {"type": getattr(block, "type", "unknown")}
            assistant_content.append(d)
            if block.type == "text":
                final_text = block.text
                action_log.append({"type": "text", "text": block.text[:500]})
            elif block.type == "tool_use":
                tool_uses.append(block)
                action_log.append({"type": "tool_use", "name": block.name, "input": block.input})
        messages.append({"role": "assistant", "content": assistant_content})

        if resp.stop_reason == "end_turn" or not tool_uses:
            break

        results = []
        for tu in tool_uses:
            r = _exec_action(tu.input)
            content = []
            if r.get("image_b64"):
                content.append({
                    "type": "image",
                    "source": {"type": "base64", "media_type": r.get("media", "image/png"), "data": r["image_b64"]},
                })
            if r.get("text"):
                content.append({"type": "text", "text": r["text"]})
            tr = {"type": "tool_result", "tool_use_id": tu.id, "content": content}
            if r.get("is_error"):
                tr["is_error"] = True
            results.append(tr)
        messages.append({"role": "user", "content": results})

    return {
        "success": True,
        "result": final_text,
        "iterations": iterations,
        "stop_reason": getattr(resp, "stop_reason", None),
        "log": action_log,
    }

# ── Terminal (PTY) session management ─────────────────────────────────────────
import pty
import fcntl
import struct
import select
import signal

_terminals: dict[str, dict] = {}  # id -> {pid, fd, created, host, cols, rows}
_term_lock = threading.Lock()

def _term_create(host: str = "", cols: int = 120, rows: int = 40) -> dict:
    """Spawn a PTY shell (local or SSH)."""
    env = os.environ.copy()
    env["TERM"] = "xterm-256color"
    env["COLORTERM"] = "truecolor"
    env["LANG"] = env.get("LANG", "en_US.UTF-8")

    if host and host != "local":
        # SSH to remote host
        cmd = ["ssh", "-o", "StrictHostKeyChecking=accept-new",
               "-o", "ServerAliveInterval=30", "-t", host]
    else:
        # Local shell
        shell = os.environ.get("SHELL", "/bin/bash")
        cmd = [shell, "-l"]

    pid, fd = pty.fork()
    if pid == 0:
        # Child — exec the command
        os.execvpe(cmd[0], cmd, env)
    else:
        # Parent — set terminal size
        fcntl.ioctl(fd, termios_TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        # Make fd non-blocking
        flags = fcntl.fcntl(fd, fcntl.F_GETFL)
        fcntl.fcntl(fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)

        tid = f"term-{uuid.uuid4().hex[:8]}"
        with _term_lock:
            _terminals[tid] = {
                "pid": pid, "fd": fd, "created": int(time.time()),
                "host": host or "local", "cols": cols, "rows": rows,
            }
        return {"id": tid, "host": host or "local", "cols": cols, "rows": rows}

# TIOCSWINSZ constant
try:
    import termios
    termios_TIOCSWINSZ = termios.TIOCSWINSZ
except (ImportError, AttributeError):
    termios_TIOCSWINSZ = 0x5414  # Linux default

def _term_read(tid: str, max_bytes: int = 65536) -> bytes:
    """Read available output from terminal."""
    with _term_lock:
        t = _terminals.get(tid)
    if not t:
        return b""
    fd = t["fd"]
    try:
        ready, _, _ = select.select([fd], [], [], 0.05)
        if ready:
            return os.read(fd, max_bytes)
    except (OSError, IOError):
        pass
    return b""

def _term_read_wait(tid: str, timeout: float, max_bytes: int = 262144) -> bytes:
    """Long-poll read: block up to `timeout`s for the FIRST output byte, then
    briefly coalesce a burst (e.g. a screen redraw) into one response. Returns
    the instant the PTY produces data, so the client gets near-real-time output
    instead of waiting out a fixed polling interval. Empty bytes on timeout.
    """
    with _term_lock:
        t = _terminals.get(tid)
    if not t:
        return b""
    fd = t["fd"]
    try:
        ready, _, _ = select.select([fd], [], [], max(0.0, timeout))
        if not ready:
            return b""
        chunks: list[bytes] = []
        total = 0
        # Drain what's available, coalescing a short burst to cut round-trips.
        while total < max_bytes:
            try:
                buf = os.read(fd, 65536)
            except (OSError, IOError):
                break
            if not buf:
                break
            chunks.append(buf)
            total += len(buf)
            more, _, _ = select.select([fd], [], [], 0.015)
            if not more:
                break
        return b"".join(chunks)
    except (OSError, IOError):
        return b""


def _term_write(tid: str, data: bytes):
    """Write input to terminal."""
    with _term_lock:
        t = _terminals.get(tid)
    if not t:
        return
    try:
        os.write(t["fd"], data)
    except (OSError, IOError):
        pass

def _term_resize(tid: str, cols: int, rows: int):
    """Resize terminal."""
    with _term_lock:
        t = _terminals.get(tid)
    if not t:
        return
    try:
        fcntl.ioctl(t["fd"], termios_TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        t["cols"] = cols
        t["rows"] = rows
        # Send SIGWINCH to the process group
        os.kill(t["pid"], signal.SIGWINCH)
    except (OSError, IOError):
        pass

def _term_destroy(tid: str):
    """Kill terminal session."""
    with _term_lock:
        t = _terminals.pop(tid, None)
    if not t:
        return
    try:
        os.kill(t["pid"], signal.SIGHUP)
    except (OSError, ProcessLookupError):
        pass
    try:
        os.close(t["fd"])
    except OSError:
        pass
    try:
        os.waitpid(t["pid"], os.WNOHANG)
    except (ChildProcessError, OSError):
        pass

def _term_alive(tid: str) -> bool:
    """Check if terminal process is still running."""
    with _term_lock:
        t = _terminals.get(tid)
    if not t:
        return False
    try:
        pid, status = os.waitpid(t["pid"], os.WNOHANG)
        return pid == 0  # 0 means still running
    except (ChildProcessError, OSError):
        return False


# SSE shared cache — avoids redundant subprocess calls when multiple tabs connect
_sse_cache = {
    "sessions": {"data": None, "json": "", "time": 0},
    "board": {"data": None, "json": "", "time": 0},
}
_sse_cache_lock = threading.Lock()  # prevents thundering herd on cache refresh
_SSE_CACHE_TTL = 2  # seconds


def _cache_etag(c: dict) -> str:
    """Content-hash ETag for a shared cache entry, memoized per generation —
    a polling client whose view is current gets a bodyless 304 instead of the
    full 2.4MB board / 104KB sessions payload every few seconds (AMUX-1859)."""
    j = c.get("json") or ""
    if not j:
        return ""
    if c.get("_etag_src") is not j:
        import hashlib as _hl
        c["_etag"] = '"' + _hl.md5(j.encode()).hexdigest()[:16] + '"'
        c["_etag_src"] = j
    return c["_etag"]

# ── Structured event log (in-memory ring buffer, 2 000 events) ─────────────────
import collections
_event_log: "collections.deque[dict]" = collections.deque(maxlen=2000)
_event_log_lock = threading.Lock()
_req_tl = threading.local()  # per-request enrichment (set by handlers, read by _route)

# Request/response payload capture for the Activity log (Ethan, AMUX-2281:
# "add response to the logs, it should be request/response so I can see the
# payloads via accordion, I should also be able to search it").
_PAYLOAD_CAP = int(os.environ.get("AMUX_LOG_PAYLOAD_BYTES", "4096"))
_PAYLOAD_LOG = os.environ.get("AMUX_LOG_PAYLOADS", "1") not in ("0", "false", "no")
# Redacted by KEY NAME. Bodies carry credentials — the board API alone moves
# session headers, and /api/prefs and the browser endpoints move tokens. Storing
# payloads without this would turn the activity log into a credential store that
# nobody thinks of as one. Key-name redaction is not complete (a secret pasted
# into a `desc` is still a secret), which is why capture is switchable off with
# AMUX_LOG_PAYLOADS=0 and capped rather than unbounded.
_SECRET_KEY_RE = re.compile(
    r"(pass|passwd|password|secret|token|api[_-]?key|apikey|auth|cookie|credential|"
    r"private[_-]?key|session[_-]?id|bearer)", re.I)


def _redact_payload(val):
    """Recursively blank secret-looking values. Returns the same shape."""
    if isinstance(val, dict):
        out = {}
        for k, v in val.items():
            out[k] = "<redacted>" if _SECRET_KEY_RE.search(str(k)) else _redact_payload(v)
        return out
    if isinstance(val, list):
        return [_redact_payload(v) for v in val[:50]]
    return val


def _capture_payload(raw, content_type: str = "") -> str:
    """Cap + redact a body for the activity log. Never raises.

    Non-JSON (HTML, images, the dashboard itself) is recorded as a shape marker
    rather than content: a 3MB HTML blob in the log is noise that pushes the
    payload you wanted out of the buffer."""
    if not _PAYLOAD_LOG or raw is None:
        return ""
    try:
        if isinstance(raw, bytes):
            if len(raw) > _PAYLOAD_CAP * 8 and "json" not in (content_type or "").lower():
                return f"<{content_type or 'binary'} {len(raw)/1024:.1f}KB — not captured>"
            try:
                raw = raw.decode("utf-8", errors="replace")
            except Exception:
                return f"<binary {len(raw)} bytes>"
        txt = str(raw)
        if txt[:1] in ("{", "["):
            try:
                obj = _redact_payload(json.loads(txt))
                txt = json.dumps(obj, ensure_ascii=False)
            except Exception:
                pass
        elif txt[:1] == "<":
            return f"<html/text {len(txt)/1024:.1f}KB — not captured>"
        if len(txt) > _PAYLOAD_CAP:
            return txt[:_PAYLOAD_CAP] + f"\n… [truncated, {len(txt)} bytes total]"
        return txt
    except Exception:
        return ""


def _emit_http_event(etype: str, action: str, target: str = "", session: str = "",
                     detail: str = "", status: int = 200, ip: str = "",
                     actor: str = "", req: str = "", resp: str = "",
                     method: str = "", ms: int = 0) -> None:
    # Don't emit semantic events (e.g. message-sent, started) for failed requests.
    # Downgrade to a plain http event so they don't spam the event log as false positives.
    if status >= 400 and etype != "http":
        etype = "http"
        action = action  # keep as-is for http type
    with _event_log_lock:
        _event_log.append({
            "ts": time.time(),
            "type": etype,
            "action": action,
            "target": target,
            "session": session,
            "detail": detail,
            "status": status,
            "ip": ip,
            "actor": actor,
            "req": req,
            "resp": resp,
            "method": method,
            "ms": ms,
        })

def _classify_request(method: str, path: str) -> tuple:
    """Returns (type, action, target, session) from method+path."""
    # Board
    if path == "/api/board" and method == "POST":
        return ("board", "created", "", "")
    m = re.match(r"^/api/board/([A-Za-z0-9-]+)$", path)
    if m:
        iid = m.group(1)
        if method == "PATCH":   return ("board", "updated",  iid, "")
        if method == "DELETE":  return ("board", "deleted",  iid, "")
    m = re.match(r"^/api/board/([A-Za-z0-9-]+)/claim$", path)
    if m and method == "POST":
        return ("board", "claimed", m.group(1), "")
    if path == "/api/board/clear-done" and method == "POST":
        return ("board", "cleared", "done", "")
    if path == "/api/board/statuses" and method == "POST":
        return ("board", "status-added", "", "")
    m = re.match(r"^/api/board/statuses/([a-z0-9-]+)$", path)
    if m:
        sid = m.group(1)
        if method == "DELETE": return ("board", "status-removed", sid, "")
        if method == "PATCH":  return ("board", "status-renamed", sid, "")
    # Sessions
    if path == "/api/sessions" and method == "POST":
        return ("session", "created", "", "")
    m = re.match(r"^/api/sessions/([^/]+)/([^/]+)$", path)
    if m:
        sname, sub = m.group(1), m.group(2)
        if method == "POST"  and sub == "start":   return ("session", "started",      sname, sname)
        if method == "POST"  and sub == "stop":    return ("session", "stopped",      sname, sname)
        if method == "POST"  and sub == "send":    return ("session", "message-sent", sname, sname)
        if method == "POST"  and sub == "steer":   return ("session", "steered",      sname, sname)
        if method == "DELETE"and sub == "steer":   return ("session", "steer-cleared",sname, sname)
        if method == "POST"  and sub == "archive": return ("session", "archived",     sname, sname)
        if method == "POST"  and sub == "wake":    return ("session", "woken",        sname, sname)
        if method == "POST"  and sub == "reset":   return ("session", "reset",       sname, sname)
        if method == "PATCH" and sub == "config":  return ("session", "configured",   sname, sname)
        if method == "DELETE":                     return ("session", "deleted",       sname, sname)
        if method == "POST"  and sub == "memory":  return ("memory",  "updated",      sname, sname)
        if method == "POST"  and sub == "peek":    return ("session", "peeked",       sname, sname)
    m = re.match(r"^/api/sessions/([^/]+)$", path)
    if m:
        sname = m.group(1)
        if method == "DELETE": return ("session", "deleted", sname, sname)
        if method == "PATCH":  return ("session", "updated", sname, sname)
    # Memory
    if path == "/api/memory/global" and method == "POST":
        return ("memory", "updated", "global", "")
    # Uploads
    if path.startswith("/api/uploads") and method == "POST":
        return ("file", "uploaded", "", "")
    if path == "/api/fs/upload" and method == "POST":
        return ("file", "uploaded", "", "")
    if path == "/api/fs/delete" and method == "DELETE":
        return ("file", "deleted", "", "")
    # System
    if path == "/api/pull" and method == "POST":
        return ("system", "pull", "repo", "")
    # Generic reads (low-priority)
    if method == "GET":
        return ("http", "get", path, "")
    action_map = {"POST": "post", "PATCH": "patch", "DELETE": "delete"}
    return ("http", action_map.get(method, method.lower()), path, "")

# Auto-recovery state
_sse_alerts: list = []           # ring buffer of alert dicts pushed to all SSE clients
_crm_version: int = 0               # bumped on any CRM write; triggers SSE invalidation
_journal_version: int = 0           # bumped on any journal write; triggers SSE invalidation
_sse_alert_lock = threading.Lock()
_send_locks: dict = {}          # per-session locks for serializing send_text/send_keys
_send_locks_lock = threading.Lock()  # protects _send_locks dict itself
_session_locks: dict = {}           # per-session RLocks for stop/start serialization
_session_locks_init = threading.Lock()  # protects _session_locks dict itself

_VALID_CC_SESSION_NAME = re.compile(r'^[a-zA-Z0-9][a-zA-Z0-9_.\-]*$')
_stop_pool = __import__("concurrent.futures", fromlist=["ThreadPoolExecutor"]).ThreadPoolExecutor(max_workers=4)
_USER_SHELL = os.environ.get("SHELL", "/bin/bash")
_session_auto_actions: dict = {} # {name: {"last_compact": ts, "last_restart": ts}}
# Harness SELF-REPORTED state (ethos dev-1). Written by POST /api/sessions/<n>/report
# — fired by Claude Code's own Stop / UserPromptSubmit hooks — so state flows FROM
# the harness instead of being inferred by regex over a rendered terminal. A fresh
# report outranks the pane scrape; a stale one falls through to it. The scrapers
# stay as the fallback for crashes, subagents, and providers without hooks.
_session_reported: dict = {}   # name -> {"state": ..., "detail": ..., "ts": epoch}
_scrape_vs_report: dict = {}   # name -> last scrape/hook disagreement (ethos #4)


def _persist_session_reports() -> None:
    """Mirror the self-report table into prefs so it survives a restart.

    This process re-execs itself on every save of this file, so anything held
    only in memory is fiction across a restart. That was tolerable while
    reports were a status-loop nicety with a 25s freshness window. It is not
    tolerable now that reports gate scan demotion on a 30-minute window: a
    restart would drop every lane back to full-rate pane capture until each
    one happened to take a turn, which is exactly the load the demotion
    exists to remove."""
    try:
        db = get_db()
        db.execute("INSERT INTO prefs (key, value) VALUES ('session_reports', ?) "
                   "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                   (json.dumps(_session_reported),))
        db.commit()
    except Exception as e:
        try: slog(f"[report] persist failed: {e}")
        except Exception: pass


def _hydrate_session_reports() -> None:
    """Restore self-reports at boot, dropping any older than the hooks-live
    window (a report that stale licenses nothing anyway)."""
    try:
        row = get_db().execute("SELECT value FROM prefs WHERE key='session_reports'").fetchone()
        if not row:
            return
        now = time.time()
        for k, v in (json.loads(row["value"]) or {}).items():
            if isinstance(v, dict) and _hooks_live(v, now):
                _session_reported[k] = v
        slog(f"[report] hydrated {len(_session_reported)} self-report(s) across restart")
    except Exception as e:
        try: slog(f"[report] hydrate failed: {e}")
        except Exception: pass
_SELF_REPORT_FRESH_S = 25      # Stop fires per turn; anything older is inference territory
_steering_queue: dict = {}      # {session_name: [{"text": str, "queued_at": float, "id": str}]}
_steering_lock = threading.Lock()


def _get_session_lock(name: str) -> threading.RLock:
    with _session_locks_init:
        if name not in _session_locks:
            _session_locks[name] = threading.RLock()
        return _session_locks[name]


def _find_claude_pid(name: str) -> int:
    """Find Claude's PID as a child of the tmux pane's shell process."""
    try:
        r = subprocess.run(["tmux", "list-panes", "-t", tmux_target(name), "-F", "#{pane_pid}"],
                           capture_output=True, text=True, timeout=5)
        if r.returncode != 0 or not r.stdout.strip():
            return 0
        shell_pid = r.stdout.strip().split("\n")[0]
        r2 = subprocess.run(["pgrep", "-P", shell_pid, "-x", "claude"],
                            capture_output=True, text=True, timeout=5)
        if r2.stdout.strip():
            pid = int(r2.stdout.strip().split("\n")[0])
            return pid if pid > 1 else 0
        # Fallback: check any child (claude might be named differently)
        r3 = subprocess.run(["pgrep", "-P", shell_pid],
                            capture_output=True, text=True, timeout=5)
        for line in r3.stdout.strip().split("\n"):
            if not line.strip():
                continue
            cpid = int(line.strip())
            sf = Path.home() / ".claude" / "sessions" / f"{cpid}.json"
            if sf.exists():
                return cpid
        return 0
    except Exception:
        return 0


def _read_claude_session_name(claude_pid: int) -> str:
    """Read the session name from Claude's PID-keyed session file."""
    if claude_pid <= 1:
        return ""
    sf = Path.home() / ".claude" / "sessions" / f"{claude_pid}.json"
    try:
        if not sf.is_file() or sf.stat().st_size > 1_000_000:
            return ""
        data = json.loads(sf.read_text(errors="replace"))
        return data.get("name", "")
    except Exception:
        return ""


def _validate_cc_session_name(name: str) -> bool:
    return bool(name and len(name) <= 64 and _VALID_CC_SESSION_NAME.match(name))


def _cc_session_exists_in_project(session_name: str, work_dir: str) -> bool:
    """Check if a Claude Code session with this name exists in the project directory."""
    proj_dir = CLAUDE_HOME / "projects" / _project_name(work_dir)
    if not proj_dir.is_dir():
        return False
    try:
        for jf in proj_dir.glob("*.jsonl"):
            try:
                first_line = jf.open().readline()
                if not first_line:
                    continue
                rec = json.loads(first_line)
                if rec.get("customTitle") == session_name or rec.get("sessionName") == session_name:
                    return True
            except Exception:
                continue
    except Exception:
        pass
    return False


def _cc_session_id_for_name(session_name: str, work_dir: str) -> str:
    """Return the UUID of a uniquely-named Claude Code session, or '' if ambiguous/missing.

    When exactly one session matches, return its UUID so we can --resume <uuid>
    (which bypasses the interactive picker). When multiple match, return '' to
    force a fresh --name start instead of opening the picker."""
    proj_dir = CLAUDE_HOME / "projects" / _project_name(work_dir)
    if not proj_dir.is_dir():
        return ""
    matches = []
    try:
        for jf in proj_dir.glob("*.jsonl"):
            try:
                first_line = jf.open().readline()
                if not first_line:
                    continue
                rec = json.loads(first_line)
                if rec.get("customTitle") == session_name or rec.get("sessionName") == session_name:
                    sid = rec.get("sessionId", jf.stem)
                    matches.append(sid)
            except Exception:
                continue
    except Exception:
        pass
    return matches[0] if len(matches) == 1 else ""


# Per-session token cache — refreshed every 30s, keyed by resolved dir
_token_cache = {"data": {}, "timestamps": {}, "time": 0}
_TOKEN_CACHE_TTL = 120

def _refresh_token_cache():
    """Rebuild per-directory token counts and last-activity timestamps from Claude JSONL files."""
    now = time.time()
    if now - _token_cache["time"] < _TOKEN_CACHE_TTL:
        return
    from datetime import datetime
    result = {}
    ts_result = {}
    projects_dir = Path.home() / ".claude" / "projects"
    if not projects_dir.is_dir():
        _token_cache["data"] = result
        _token_cache["timestamps"] = ts_result
        _token_cache["time"] = now
        return
    # Only scan project dirs that registered sessions actually use
    needed_proj_keys = set()
    if CC_SESSIONS.is_dir():
        for f in CC_SESSIONS.glob("*.env"):
            cfg = parse_env_file(f)
            raw_dir = cfg.get("CC_DIR", "")
            if raw_dir:
                needed_proj_keys.add(_project_name(raw_dir))
    for proj_dir in projects_dir.iterdir():
        if not proj_dir.is_dir():
            continue
        if needed_proj_keys and proj_dir.name not in needed_proj_keys:
            continue
        # Find most recent JSONL
        jsonl_files = sorted(proj_dir.glob("*.jsonl"), key=lambda f: f.stat().st_mtime, reverse=True)
        if not jsonl_files:
            continue
        dir_total = 0
        last_ts = 0
        # Read tail of top 5 most recent JSONL files to cover multiple conversations
        for jf in jsonl_files[:5]:
            file_total = 0
            file_last_ts = 0
            try:
                size = jf.stat().st_size
                with jf.open("rb") as fh:
                    offset = max(0, size - 200_000)
                    if offset > 0:
                        fh.seek(offset)
                        fh.readline()  # skip partial line
                    prev_sig = None
                    for raw_line in fh:
                        try:
                            entry = json.loads(raw_line)
                            # Track last Claude API call timestamp
                            ts_str = entry.get("timestamp", "")
                            if ts_str:
                                try:
                                    ts_unix = int(datetime.fromisoformat(
                                        ts_str.replace("Z", "+00:00")
                                    ).timestamp())
                                    if ts_unix > last_ts:
                                        last_ts = ts_unix
                                    if ts_unix > file_last_ts:
                                        file_last_ts = ts_unix
                                except Exception:
                                    pass
                            usage = entry.get("message", {}).get("usage", {})
                            if usage:
                                sig = (usage.get("input_tokens", 0),
                                       usage.get("cache_read_input_tokens", 0),
                                       usage.get("output_tokens", 0))
                                if sig == prev_sig:
                                    continue
                                prev_sig = sig
                                t = (usage.get("input_tokens", 0)
                                     + usage.get("cache_read_input_tokens", 0)
                                     + usage.get("cache_creation_input_tokens", 0)
                                     + usage.get("output_tokens", 0))
                                file_total += t
                                dir_total += t
                            else:
                                prev_sig = None
                        except (json.JSONDecodeError, AttributeError):
                            continue
            except Exception:
                continue
            # Store per-conversation-ID totals so sessions with cc_conversation_id
            # can look up their own JSONL directly (avoids sharing counts when
            # multiple sessions share the same CC_DIR).
            conv_id = jf.stem  # JSONL filename = Claude session UUID
            result[(proj_dir.name, conv_id)] = file_total
            if file_last_ts:
                ts_result[(proj_dir.name, conv_id)] = file_last_ts
        if dir_total > 0:
            result[proj_dir.name] = dir_total
        if last_ts > 0:
            ts_result[proj_dir.name] = last_ts
    _token_cache["data"] = result
    _token_cache["timestamps"] = ts_result
    _token_cache["time"] = now

# ═══════════════════════════════════════════
# SESSION FILE HELPERS
# ═══════════════════════════════════════════

def parse_env_file(path: Path) -> dict:
    """Parse a amux session .env file into a dict."""
    data = {}
    for line in path.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        m = re.match(r'^(\w+)="(.*)"$', line)
        if m:
            data[m.group(1)] = m.group(2)
            continue
        m = re.match(r"^(\w+)='(.*)'$", line)
        if m:
            data[m.group(1)] = m.group(2)
            continue
        m = re.match(r"^(\w+)=(.*)$", line)
        if m:
            data[m.group(1)] = m.group(2)
    return data


def _atomic_write_secure(path: Path, content: str) -> None:
    """Atomically and durably write content to path with mode 0o600.

    Uses NamedTemporaryFile (which calls mkstemp under the hood, defaulting
    to mode 0o600) plus flush + fsync + os.replace for a crash-safe atomic
    write. The result file at `path` never exists with permissions other
    than 0o600 — even briefly. After this function returns successfully,
    the data is durably persisted to disk: a system crash cannot leave
    `path` empty or partially-written.

    Use this for any .env file that may contain secrets or per-user config.
    """
    import tempfile
    dir_path = str(path.parent)
    with tempfile.NamedTemporaryFile(
        mode="w",
        encoding="utf-8",
        dir=dir_path,
        prefix=f".{path.name}.",
        suffix=".tmp",
        delete=False,
    ) as tmp:
        tmp.write(content)
        # Flush Python's userspace buffer to the OS kernel buffer, then
        # flush the kernel buffer to disk. Without this, a system crash
        # after os.replace() could leave the file at `path` with empty
        # or stale contents — the rename succeeded but the data wasn't
        # yet persisted. fsync is the canonical durability barrier.
        tmp.flush()
        os.fsync(tmp.fileno())
        tmp_path = tmp.name
    try:
        os.replace(tmp_path, str(path))
    except Exception:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise


def _write_env(path: Path, cfg: dict):
    """Write a cfg dict back to a amux .env file with secure permissions.

    Uses _atomic_write_secure to ensure the file is created with mode 0o600,
    preventing world-readable .env files that may contain secrets like
    ANTHROPIC_API_KEY or per-session credentials.
    """
    # AUDIT every env mutation at the ONE choke point (AMUX-2314). Ethan's
    # reasoning is the right one: env vars are the mechanism by which a session
    # acts on the world, so an unaudited env is an unaudited blast radius.
    # Recorded per KEY — added / removed / changed — and NEVER the values: an
    # audit log that captures secrets is a second copy of the credential in a
    # place nobody is guarding. `changed` names the key whose value moved, which
    # is what forensics needs; the value itself is in the file, under 0600.
    try:
        _prior = parse_env_file(path) if path.exists() else {}
        _added = sorted(set(cfg) - set(_prior))
        _removed = sorted(set(_prior) - set(cfg))
        _changed = sorted(k for k in set(cfg) & set(_prior) if _prior[k] != cfg[k])
        if _added or _removed or _changed:
            _ilog("env", "write", target=str(path), ok=True,
                  detail={"added": _added, "removed": _removed, "changed": _changed})
    except Exception as _ae:
        slog(f"[env-audit] failed for {path}: {_ae!r}")
    lines = [f'# updated: {__import__("datetime").datetime.now().isoformat()}']
    for k, v in cfg.items():
        lines.append(f'{k}="{v}"')
    _atomic_write_secure(path, "\n".join(lines) + "\n")


def _blocked_session_names() -> set[str]:
    """Return session names quarantined from create/start/wake/auto-resume."""
    try:
        names = set()
        for line in CC_BLOCKED_SESSIONS.read_text().splitlines():
            line = line.strip()
            if line and not line.startswith("#"):
                names.add(line)
        return names
    except FileNotFoundError:
        return set()
    except Exception:
        return set()


def _is_session_blocked(name: str) -> bool:
    return name in _blocked_session_names()


# ═══════════════════════════════════════════
# TMUX HELPERS
# ═══════════════════════════════════════════

_tmux_name_migrated = set()  # Sessions already checked for legacy name migration

def tmux_name(session: str) -> str:
    new = f"amux-{session}"
    # Only check for legacy cmux-*/cc-* names once per session per process lifetime
    if session not in _tmux_name_migrated:
        _tmux_name_migrated.add(session)
        for old in [f"cmux-{session}", f"cc-{session}"]:
            try:
                r = subprocess.run(["tmux", "has-session", "-t", old], capture_output=True, timeout=3)
                if r.returncode == 0:
                    subprocess.run(["tmux", "rename-session", "-t", old, new], capture_output=True, timeout=5)
                    break
            except Exception:
                pass
    return new


def tmux_target(session: str) -> str:
    """Return the tmux target for -t flags."""
    return tmux_name(session)


def is_running(session: str) -> bool:
    """Check if Claude is running in this session's tmux pane."""
    iterm2_id = _session_iterm2_id(session)
    if iterm2_id:
        return _iterm2_session_exists(iterm2_id)
    if _session_backend(session) == "herdr":
        return _herdr_agent_get(session) is not None
    try:
        r = subprocess.run(
            ["tmux", "list-sessions", "-F", "#{session_name}"],
            capture_output=True, text=True, timeout=5,
        )
        tmux_sess = tmux_name(session)
        if tmux_sess not in r.stdout.splitlines():
            return False
        # Tmux exists -- check if Claude is actually running (not at shell prompt)
        output = tmux_capture(session, 10)
        if not output:
            return True  # empty output but tmux exists -- assume running (startup)
        if _at_shell_prompt(output):
            return False
        # Terminal-based check can false-positive when Claude's status bar text
        # leaks into scrollback after a SIGKILL. Cross-check by verifying the
        # shell actually has a child process (Claude).
        try:
            r_pp = subprocess.run(
                ["tmux", "list-panes", "-t", tmux_sess, "-F", "#{pane_pid}"],
                capture_output=True, text=True, timeout=5)
            if r_pp.returncode == 0 and r_pp.stdout.strip():
                shell_pid = r_pp.stdout.strip().split("\n")[0]
                r_ch = subprocess.run(
                    ["pgrep", "-P", shell_pid],
                    capture_output=True, text=True, timeout=5)
                if not r_ch.stdout.strip():
                    return False
        except Exception:
            pass
        return True
    except FileNotFoundError:
        return False


def tmux_capture(session: str, lines: int = 500) -> str:
    iterm2_id = _session_iterm2_id(session)
    if iterm2_id:
        return _iterm2_capture(iterm2_id)
    if _session_backend(session) == "herdr":
        return _herdr_capture(session, lines)
    try:
        r = subprocess.run(
            ["tmux", "capture-pane", "-t", tmux_target(session), "-p", "-e",
             # lines<=0 → VISIBLE SCREEN ONLY. An in-place-repainting TUI
             # (Gemini) leaves every stale frame in scrollback; capturing any
             # of it stacks repaints into garbage (Ethan 12:03).
             *([] if lines <= 0 else ["-S", f"-{lines}"])],
            capture_output=True, text=True, timeout=5,
        )
        # Strip leading/trailing blank lines so content isn't cut off
        return r.stdout.strip()
    except Exception:
        return ""


# Canonical tmux window size for amux sessions. tmux's default `window-size
# latest` resizes a window to whatever client attached to it most recently —
# and a headless/scripted attach defaults to 80x24. Every width change makes
# Claude Code redraw its whole transcript reflowed and tmux rewrap scrollback,
# so the peek shows content "reformatted" at whatever width touched the
# session last (tables mangled at 80 cols, prose rewrapped mid-history).
try:
    _TMUX_COLS = int(os.environ.get("AMUX_TMUX_COLS", "220"))
except ValueError:
    _TMUX_COLS = 220
try:
    _TMUX_ROWS = int(os.environ.get("AMUX_TMUX_ROWS", "50"))
except ValueError:
    _TMUX_ROWS = 50


def _tmux_size_watchdog():
    """Restore DETACHED amux sessions to the canonical window size.

    A live human terminal always owns the size while attached (window-size
    latest); once every client detaches, drift is restored so all future
    turns render at a stable, wide width for the peek. resize-window flips
    the window to manual sizing, so 'latest' is reset right after to keep
    the next human attach working normally.
    """
    try:
        r = subprocess.run(
            ["tmux", "list-windows", "-a", "-F",
             "#{session_name}\t#{session_attached}\t#{window_width}\t#{window_height}"],
            capture_output=True, text=True, timeout=5,
        )
        if r.returncode != 0:
            return
        for line in r.stdout.splitlines():
            try:
                name, attached, w, h = line.split("\t")
            except ValueError:
                continue
            if not name.startswith("amux-") or attached != "0":
                continue
            if w == str(_TMUX_COLS) and h == str(_TMUX_ROWS):
                continue
            subprocess.run(["tmux", "resize-window", "-t", name,
                            "-x", str(_TMUX_COLS), "-y", str(_TMUX_ROWS)],
                           capture_output=True, timeout=5)
            subprocess.run(["tmux", "set-option", "-w", "-t", name,
                            "window-size", "latest"],
                           capture_output=True, timeout=5)
            slog(f"[tmux-size] {name}: {w}x{h} -> {_TMUX_COLS}x{_TMUX_ROWS} (detached drift restored)")
    except Exception:
        pass


def _tmux_alt_screen(session: str) -> bool:
    """True if the pane is in the alternate screen buffer (TUI mode, e.g. Claude
    Code). The alt buffer has NO scrollback, so capture-pane only ever returns
    the visible window — peek must fall back to the saved log for history."""
    iterm2_id = _session_iterm2_id(session)
    if iterm2_id:
        return False
    if _session_backend(session) == "herdr":
        return False  # herdr keeps scrollback even under the alternate screen
    try:
        r = subprocess.run(
            ["tmux", "display-message", "-t", tmux_target(session), "-p", "#{alternate_on}"],
            capture_output=True, text=True, timeout=5,
        )
        return r.stdout.strip() == "1"
    except Exception:
        return False


_capture_cache: dict[str, tuple[int, str]] = {}  # session -> (activity_ts, output)


def _tmux_capture_batch(sessions: list, lines: int = 30,
                        activity: dict | None = None) -> dict:
    """Capture pane output for multiple sessions in parallel using threads.
    Returns {session_name: output_str}.

    When *activity* is provided (from _tmux_info_map()), sessions whose
    tmux activity timestamp hasn't changed since the last capture are served
    from _capture_cache, avoiding a subprocess fork per unchanged session.
    """
    if not sessions:
        return {}
    result = {}
    need_capture = []
    for name in sessions:
        if activity:
            act_ts = activity.get(tmux_name(name), {}).get("activity", 0)
            cached = _capture_cache.get(name)
            if cached and cached[0] == act_ts:
                result[name] = cached[1]
                continue
        need_capture.append(name)
    if need_capture:
        from concurrent.futures import ThreadPoolExecutor
        def _cap(name):
            return name, tmux_capture(name, lines)
        with ThreadPoolExecutor(max_workers=min(len(need_capture), 16)) as pool:
            for name, output in pool.map(_cap, need_capture):
                act_ts = activity.get(tmux_name(name), {}).get("activity", 0) if activity else 0
                _capture_cache[name] = (act_ts, output)
                result[name] = output
    return result


# ── iTerm2 integration (AppleScript via osascript) ────────────────────────────

def _iterm2_applescript(script: str, timeout: int = 8) -> str:
    """Run an AppleScript and return stdout, or '' on error."""
    try:
        r = subprocess.run(["osascript", "-e", script],
                           capture_output=True, text=True, timeout=timeout)
        return r.stdout.strip()
    except Exception:
        return ""


def _iterm2_list_panes() -> list:
    """Return list of dicts describing every open iTerm2 pane.
    Each dict: {id, name, tty, window, tab}"""
    script = """
tell application "iTerm2"
    set out to ""
    set wi to 0
    repeat with w in windows
        set ti to 0
        repeat with t in tabs of w
            repeat with s in sessions of t
                set out to out & (id of s) & "|" & (name of s) & "|" & (tty of s) & "|" & wi & "|" & ti & "\n"
            end repeat
            set ti to ti + 1
        end repeat
        set wi to wi + 1
    end repeat
    return out
end tell"""
    raw = _iterm2_applescript(script)
    panes = []
    for line in raw.splitlines():
        parts = line.split("|")
        if len(parts) >= 5:
            panes.append({"id": parts[0], "name": parts[1], "tty": parts[2],
                          "window": int(parts[3]), "tab": int(parts[4])})
    return panes


def _iterm2_capture(session_id: str) -> str:
    """Return the visible screen content of an iTerm2 pane by its session ID."""
    sid = session_id.replace('"', '')
    script = f"""
tell application "iTerm2"
    repeat with w in windows
        repeat with t in tabs of w
            repeat with s in sessions of t
                if (id of s) = "{sid}" then
                    return contents of s
                end if
            end repeat
        end repeat
    end repeat
    return ""
end tell"""
    return _iterm2_applescript(script, timeout=10)


def _iterm2_session_exists(session_id: str) -> bool:
    """Return True if the iTerm2 pane with this ID is still open."""
    return bool(_iterm2_capture(session_id))


def _iterm2_send(session_id: str, text: str) -> tuple[bool, str]:
    """Send text (followed by newline) to an iTerm2 pane."""
    sid = session_id.replace('"', '')
    # Write text to a temp file to avoid AppleScript quoting issues
    import tempfile as _tmp
    with _tmp.NamedTemporaryFile(mode='w', delete=False, suffix='.txt', encoding='utf-8') as f:
        f.write(text)
        tmp_path = f.name
    try:
        script = f"""
tell application "iTerm2"
    repeat with w in windows
        repeat with t in tabs of w
            repeat with s in sessions of t
                if (id of s) = "{sid}" then
                    set fileRef to open for access POSIX file "{tmp_path}"
                    set txt to read fileRef as «class utf8»
                    close access fileRef
                    tell s to write text txt
                    return "ok"
                end if
            end repeat
        end repeat
    end repeat
    return "not found"
end tell"""
        result = _iterm2_applescript(script, timeout=15)
        if result == "ok":
            return True, "sent"
        return False, result or "not found"
    finally:
        try:
            os.unlink(tmp_path)
        except Exception:
            pass


def _session_iterm2_id(name: str) -> str:
    """Return the stored iTerm2 session ID for an amux session, or ''."""
    env_file = CC_SESSIONS / f"{name}.env"
    if not env_file.exists():
        return ""
    return parse_env_file(env_file).get("CC_ITERM2_SESSION_ID", "").strip()


# ── herdr backend ────────────────────────────────────────────────────────────
# Alternative terminal backend alongside tmux (mixpeek/amux#79). Where tmux
# hosts a session in its own tmux session, herdr hosts it as a RECOGNIZED
# AGENT inside a pane of one headless named herdr session (default: "amux",
# AMUX_HERDR_SESSION). Selection: per-session CC_BACKEND wins, then the
# AMUX_BACKEND server env, default tmux. All herdr logic lives in this
# section; the rest of the file reaches it through the same early-return
# branch pattern the iTerm2 integration uses, so tmux paths stay untouched.
#
# Spiked against herdr 0.7.5 (2026-08-03): headless named session driven from
# a non-pane daemon context, agent start/read/prompt/wait/stop, graceful
# /exit stop with name release. Two findings shaped this code: (1) leftover
# input-buffer text gets concatenated into the next `agent prompt`, so sends
# clear with ctrl+u first (same shape as the tmux path's C-u); (2) after a
# FAILED agent start, the same name cannot restart in the same terminal, so
# every start gets a fresh workspace+pane — which matches how tmux starts get
# a fresh tmux session anyway.

_HERDR_BACKENDS = ("tmux", "herdr")
_AMUX_BACKEND = os.environ.get("AMUX_BACKEND", "tmux").strip().lower()
if _AMUX_BACKEND not in _HERDR_BACKENDS:
    _AMUX_BACKEND = "tmux"
# Name of the herdr session amux owns. Herdr gives each named session its own
# server + socket (~/.config/herdr/sessions/<name>/), so amux never touches
# the user's own herdr sessions.
_HERDR_SESSION = os.environ.get("AMUX_HERDR_SESSION", "amux").strip() or "amux"


def _backend_of_cfg(cfg: dict) -> str:
    """Terminal backend for a session: CC_BACKEND wins, then AMUX_BACKEND."""
    b = (cfg.get("CC_BACKEND", "") or "").strip().lower()
    return b if b in _HERDR_BACKENDS else _AMUX_BACKEND


def _session_backend(name: str) -> str:
    env_file = CC_SESSIONS / f"{name}.env"
    if not env_file.exists():
        return _AMUX_BACKEND
    try:
        return _backend_of_cfg(parse_env_file(env_file))
    except Exception:
        return _AMUX_BACKEND


def _herdr_available() -> bool:
    return shutil.which("herdr") is not None


def _herdr(args: list, timeout: float = 10) -> subprocess.CompletedProcess | None:
    """Run `herdr --session <amux-session> <args>`. None on any failure."""
    try:
        return subprocess.run(["herdr", "--session", _HERDR_SESSION] + args,
                              capture_output=True, text=True, timeout=timeout)
    except Exception:
        return None


def _herdr_json(args: list, timeout: float = 10) -> dict | None:
    """Run a herdr CLI command and parse its JSON reply.

    None on process failure, bad JSON, or an error payload — callers treat
    all three as "did not work"."""
    r = _herdr(args, timeout=timeout)
    if r is None or r.returncode != 0 or not r.stdout.strip():
        return None
    try:
        d = json.loads(r.stdout)
    except Exception:
        return None
    if not isinstance(d, dict) or d.get("error"):
        return None
    return d


def _herdr_session_running() -> bool:
    """True if the amux herdr session's server is up (session list is global)."""
    try:
        r = subprocess.run(["herdr", "session", "list", "--json"],
                           capture_output=True, text=True, timeout=5)
        if r.returncode != 0:
            return False
        for s in json.loads(r.stdout).get("sessions", []):
            if s.get("name") == _HERDR_SESSION and s.get("running"):
                return True
    except Exception:
        pass
    return False


_herdr_server_lock = threading.Lock()
_herdr_server_proc: subprocess.Popen | None = None


def _herdr_ensure_server() -> bool:
    """Make sure the headless server for the amux herdr session is running."""
    global _herdr_server_proc
    if _herdr_session_running():
        return True
    with _herdr_server_lock:
        if _herdr_session_running():
            return True
        try:
            _herdr_server_proc = subprocess.Popen(
                ["herdr", "--session", _HERDR_SESSION, "server"],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                start_new_session=True,
            )
        except Exception as e:
            slog(f"[herdr] failed to launch server: {e}")
            return False
    for _ in range(20):
        time.sleep(0.25)
        if _herdr_session_running():
            return True
    slog("[herdr] session server did not come up within 5s")
    return False


def _herdr_agent_name(name: str) -> str:
    """Map an amux session name to a herdr agent name.

    Herdr agent names must match [a-z][a-z0-9_-]{0,31}; amux names allow
    upper case and dots. The mapping is persisted in CC_HERDR_AGENT so it is
    stable across restarts and the CLI can resolve it without recomputing."""
    env_file = CC_SESSIONS / f"{name}.env"
    cfg: dict = {}
    if env_file.exists():
        try:
            cfg = parse_env_file(env_file)
        except Exception:
            cfg = {}
        existing = (cfg.get("CC_HERDR_AGENT", "") or "").strip()
        if existing:
            return existing
    mapped = re.sub(r"[^a-z0-9_-]", "-", name.lower())
    mapped = re.sub(r"-{2,}", "-", mapped).strip("-")[:32].strip("-")
    if not mapped or not re.match(r"^[a-z]", mapped):
        mapped = ("a-" + mapped)[:32].rstrip("-")
    if env_file.exists():
        try:
            cfg["CC_HERDR_AGENT"] = mapped
            _write_env(env_file, cfg)
        except Exception:
            pass
    return mapped


def _herdr_agent_get(name: str) -> dict | None:
    """Live herdr agent info for this amux session, or None if not running."""
    d = _herdr_json(["agent", "get", _herdr_agent_name(name)], timeout=5)
    if not d:
        return None
    return (d.get("result") or {}).get("agent") or None


def _herdr_capture(name: str, lines: int = 500) -> str:
    """Pane transcript for peek. recent-unwrapped keeps history even under
    Claude Code's alternate screen (spiked 2026-08-03)."""
    r = _herdr(["agent", "read", _herdr_agent_name(name),
                "--source", "recent-unwrapped",
                "--lines", str(max(int(lines), 1)), "--format", "text"],
               timeout=8)
    if r is None or r.returncode != 0:
        return ""
    return r.stdout.strip()


def _herdr_env_pairs(cfg: dict) -> list:
    """Env forwarding parity with the tmux path's -e flags: provider
    credentials plus the global agent credentials file (MCP registry
    variables resolve from these)."""
    pairs = []
    _has_oauth = False
    try:
        _cj = Path.home() / ".claude.json"
        if _cj.exists():
            _has_oauth = bool(json.loads(_cj.read_text()).get("oauthAccount"))
    except Exception:
        pass
    if _has_oauth:
        pairs.append("ANTHROPIC_API_KEY=")
    else:
        _v = os.environ.get("ANTHROPIC_API_KEY", "")
        if _v:
            pairs.append(f"ANTHROPIC_API_KEY={_v}")
    # Superset of the tmux path's explicit -e list: herdr panes don't source
    # amux's shell_rc, so token/base-URL auth (custom endpoints) must be
    # forwarded explicitly rather than relying on profile sourcing.
    for _k in ("ANTHROPIC_API_BASE", "ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_BASE_URL",
               "OPENAI_API_KEY", "GEMINI_API_KEY",
               "GOOGLE_API_KEY", "GOOGLE_GENAI_USE_VERTEXAI",
               "GOOGLE_CLOUD_PROJECT", "GOOGLE_CLOUD_LOCATION"):
        _v = os.environ.get(_k, "")
        if _v:
            pairs.append(f"{_k}={_v}")
    # tmux sources CC_AMUX_ENV into the pane shell; herdr panes get it as
    # explicit env instead. Values may reference other vars — expand
    # best-effort against the process env.
    if CC_AMUX_ENV.exists():
        try:
            for _k, _v in parse_env_file(CC_AMUX_ENV).items():
                if _v and not any(p.startswith(_k + "=") for p in pairs):
                    pairs.append(f"{_k}={os.path.expandvars(_v)}")
        except Exception:
            pass
    return pairs


def _herdr_capture_session_uuid(name: str, agent_name: str) -> None:
    """herdr captures the Claude session UUID lazily after startup
    (agent_session.value); store it where the resume/token paths expect it."""
    for _ in range(15):
        time.sleep(1)
        try:
            d = _herdr_json(["agent", "get", agent_name], timeout=5)
            uuid_val = ((((d or {}).get("result") or {}).get("agent") or {})
                        .get("agent_session") or {}).get("value", "")
            if uuid_val:
                meta = _load_meta(name)
                if not meta.get("cc_conversation_id"):
                    meta["cc_conversation_id"] = uuid_val
                    _save_meta(name, meta)
                return
        except Exception:
            pass


def _herdr_create_and_start(name: str, kind: str, args: list, work_dir: str,
                            env_pairs: list) -> tuple[bool, str]:
    """Create a fresh workspace+pane in the amux herdr session and start the
    agent in it. A fresh pane per start also sidesteps herdr's stale
    name-on-terminal state left by a failed start (see section header)."""
    if not _herdr_available():
        return False, "herdr binary not found (install herdr or set AMUX_BACKEND=tmux)"
    if not _herdr_ensure_server():
        return False, "herdr session server did not start"
    agent_name = _herdr_agent_name(name)
    # Reuse the pane a previous graceful stop left behind — same semantics as
    # tmux, where stop keeps the session alive for the next start. Without
    # this, every stop/start cycle would pile up a dead workspace. After a
    # FAILED start the pane was closed, so pane get fails and a fresh
    # workspace is created instead.
    pane_id = ""
    try:
        _prev_pane = (parse_env_file(CC_SESSIONS / f"{name}.env")
                      .get("CC_HERDR_PANE_ID", "") or "").strip()
    except Exception:
        _prev_pane = ""
    if _prev_pane:
        d_prev = _herdr_json(["pane", "get", _prev_pane], timeout=5)
        if d_prev and ((d_prev.get("result") or {}).get("pane")):
            pane_id = _prev_pane
            # The shell kept its env; only the (possibly changed) work dir
            # needs re-applying before the agent launches in it.
            _herdr(["pane", "run", pane_id, f"cd {shlex.quote(work_dir)}"],
                   timeout=5)
            time.sleep(0.2)
    if not pane_id:
        ws_args = ["workspace", "create", "--cwd", work_dir,
                   "--label", f"amux-{name}", "--no-focus"]
        for pair in env_pairs:
            ws_args += ["--env", pair]
        d = _herdr_json(ws_args, timeout=15)
        pane_id = (((d or {}).get("result") or {}).get("root_pane") or {}).get("pane_id", "")
        if not pane_id:
            return False, "herdr workspace create failed"
    start_args = ["agent", "start", agent_name, "--kind", kind,
                  "--pane", pane_id, "--timeout", "60000"]
    if args:
        start_args += ["--"] + args
    d2 = _herdr_json(start_args, timeout=90)
    if not d2 or not ((d2.get("result") or {}).get("agent")):
        # Don't leave a half-started pane behind.
        _herdr_json(["pane", "close", pane_id], timeout=10)
        return False, "herdr agent start failed"
    try:
        env_file = CC_SESSIONS / f"{name}.env"
        cfg = parse_env_file(env_file)
        cfg["CC_HERDR_PANE_ID"] = pane_id
        _write_env(env_file, cfg)
    except Exception:
        pass
    threading.Thread(target=_herdr_capture_session_uuid,
                     args=(name, agent_name), daemon=True).start()
    return True, "started"


def _herdr_start_claude(name: str, work_dir: str, flags: str, default_flags: str,
                        session_flag: str, extra_flags: str, cfg: dict) -> tuple[bool, str]:
    """Start a claude agent via `herdr agent start ... -- <args>`.

    Mirrors the claude branch of start_session minus the shell-only pieces
    (herdr panes start login shells on their own, so no shell_rc/profile
    sourcing is needed here)."""
    def _split(f: str) -> list:
        try:
            return shlex.split(f)
        except ValueError:
            return [f]

    args: list = []
    if default_flags:
        args += _split(default_flags)
    if flags:
        args += _split(flags)
    if session_flag:
        args += _split(session_flag)
    if extra_flags:
        args += _split(extra_flags)
    # Same MCP opt-OUT as the tmux claude branch.
    mcp_val = cfg.get("CC_MCP", "").strip().lower()
    if mcp_val not in ("off", "none", "0"):
        _reg = _mcp_registry_path()
        if _reg:
            args += ["--mcp-config", str(_reg)]
    if "--model" not in args:
        args += ["--model", "sonnet"]
    env_pairs = _herdr_env_pairs(cfg)
    ok, msg = _herdr_create_and_start(name, "claude", args, work_dir, env_pairs)
    if not ok and any(a == "--resume" for a in args):
        # Parity with the tmux path's resume-failure fallback: drop the stale
        # resume ids and start fresh under the amux session name.
        meta = _load_meta(name)
        meta.pop("cc_session_name", None)
        meta.pop("cc_conversation_id", None)
        _save_meta(name, meta)
        # Rebuild the arg list without the --resume <uuid> pair.
        _cleaned = []
        _skip = False
        for a in args:
            if a == "--resume":
                _skip = True
                continue
            if _skip:
                _skip = False
                continue
            _cleaned.append(a)
        _cleaned += ["--name", name]
        print(f"[start] {name}: herdr --resume failed, starting fresh")
        ok, msg = _herdr_create_and_start(name, "claude", _cleaned, work_dir, env_pairs)
    return ok, msg


def _herdr_send(name: str, text: str) -> tuple[bool, str]:
    agent_name = _herdr_agent_name(name)
    if _herdr_agent_get(name) is None:
        # Auto-wake parity with the tmux path: start, then deliver once ready.
        if name in _auto_waking:
            return False, "not running"
        _auto_waking.add(name)
        try:
            ok, msg = start_session(name)
            if not ok:
                return False, f"auto-wake failed: {msg}"
            for _ in range(60):
                time.sleep(0.5)
                if _herdr_agent_get(name) is not None:
                    break
            else:
                return False, "auto-woke but agent did not become ready"
        finally:
            _auto_waking.discard(name)
    # Same resume-picker guard as the tmux path (text-based, works on the
    # herdr capture too).
    cap = _herdr_capture(name, 15)
    if cap and _at_resume_picker(cap):
        return False, "session is in resume picker"
    with _get_send_lock(name):
        # Clear input-buffer residue first: leftover text would be
        # concatenated with this prompt and submitted as one message.
        _herdr_json(["agent", "send-keys", agent_name, "ctrl+u"], timeout=5)
        time.sleep(0.1)
        r = _herdr_json(["agent", "prompt", agent_name, text], timeout=15)
    if r is None:
        return False, "herdr prompt failed"
    return True, "sent"


def _herdr_stop(name: str) -> tuple[bool, str]:
    """Graceful stop (clear input → /exit), pane close as the hard kill.

    The tmux equivalent keeps the tmux session alive with a shell inside;
    the herdr equivalent closes the pane, which also removes the workspace
    when it was the only pane."""
    info = _herdr_agent_get(name)
    if not info:
        return True, "not running"
    agent_name = _herdr_agent_name(name)
    pane_id = info.get("pane_id", "")
    # Snapshot the transcript to the session log before stopping — the
    # pipe-pane equivalent, since the pane (and herdr's scrollback with it)
    # goes away on close.
    try:
        _cap = _herdr_capture(name, 5000)
        if _cap:
            CC_LOGS.mkdir(parents=True, exist_ok=True)
            with _log_path(name).open("ab") as _lf:
                _lf.write(("\n" + _cap + "\n").encode("utf-8", errors="replace"))
    except Exception:
        pass
    meta = _load_meta(name)
    if not meta.get("cc_session_name"):
        meta["cc_session_name"] = name
        _save_meta(name, meta)
    _herdr_json(["agent", "send-keys", agent_name, "ctrl+u"], timeout=5)
    time.sleep(0.1)
    _herdr_json(["agent", "prompt", agent_name, "/exit"], timeout=10)
    for _ in range(30):
        time.sleep(0.5)
        if _herdr_agent_get(name) is None:
            return True, "stopped"
    print(f"[herdr-stop] {name}: timeout after 15s, closing pane")
    if pane_id:
        _herdr_json(["pane", "close", pane_id], timeout=10)
    return True, "stopped (hard-kill)"


def _herdr_kill(name: str) -> None:
    """Best-effort removal of the pane backing an archived herdr session."""
    try:
        cfg = parse_env_file(CC_SESSIONS / f"{name}.env")
        pane_id = (cfg.get("CC_HERDR_PANE_ID", "") or "").strip()
        if pane_id:
            _herdr_json(["pane", "close", pane_id], timeout=10)
    except Exception:
        pass


def _log_path(session: str) -> Path:
    return CC_LOGS / f"{session}.log"


_last_log_save: dict[str, float] = {}  # session -> monotonic time of last save
_LOG_SAVE_INTERVAL = 30  # seconds between saves per session

_peek_cache: dict[str, tuple[float, int, dict]] = {}  # session -> (monotonic_time, lines, response_dict)
_PEEK_CACHE_TTL = 2.5  # seconds — long enough that multiple clients share one cached result
_peek_live_cache: dict[str, tuple[float, dict]] = {}  # session -> (monotonic_time, response_dict)
_PEEK_LIVE_CACHE_TTL = 0.35  # seconds — matches the fastest adaptive poll cadence
# session -> the transcript string the last FULL peek response's history was built
# from. A live=1 poll trims its frame against this exact text, so the seam stays
# duplicate-free against the history the client is actually displaying — without
# re-rendering the 120KB transcript on every poll. Written only for peeked sessions.
_peek_transcript_cache: dict[str, str] = {}

_transcript_render_cache: dict[tuple, tuple[float, int, str]] = {}  # (path, max_chars) -> (mtime, size, rendered)
_jsonl_path_cache: dict[str, tuple[float, "Path | None"]] = {}  # session -> (monotonic, path)


def save_session_log(session: str, content: str, force: bool = False):
    """Append content to session log, trimming from the front when > MAX_LOG_BYTES.

    Throttled to once per _LOG_SAVE_INTERVAL seconds per session to avoid
    continuous 10MB read/write cycles when clients poll peek frequently.
    Pass force=True to bypass the throttle (e.g. on session stop).
    """
    if not content.strip():
        return
    now = time.monotonic()
    if not force:
        last = _last_log_save.get(session, 0)
        if now - last < _LOG_SAVE_INTERVAL:
            return
    _last_log_save[session] = now
    lp = _log_path(session)
    CC_LOGS.mkdir(parents=True, exist_ok=True)
    try:
        data = content.encode("utf-8", errors="replace")
        # Trim from front if combined size would exceed limit
        existing_size = lp.stat().st_size if lp.exists() else 0
        if existing_size + len(data) > MAX_LOG_BYTES:
            # Read existing, trim oldest bytes, append new
            existing = lp.read_bytes() if lp.exists() else b""
            combined = existing + data
            combined = combined[-MAX_LOG_BYTES:]
            lp.write_bytes(combined)
        else:
            with lp.open("ab") as f:
                f.write(data)
    except Exception:
        pass


def _alt_conv_lines(capture: str) -> tuple[list[str], list[str]]:
    """Split a Claude Code alt-screen capture into the conversation portion,
    trimming the trailing TUI chrome (spinner + task list, separator bars, the
    prompt box and the status bar, plus trailing blanks). Returns
    (orig_lines, plain_lines) for just the conversation — the chrome is volatile
    and re-drawn every capture, so it must not be accumulated into history."""
    orig = capture.splitlines()
    plain = [_STRIP_ANSI.sub("", l) for l in orig]
    n = len(orig)
    lo = max(0, n - 22)
    cut = n
    # If a spinner line (… ellipsis) sits in the bottom region, chrome begins at
    # the run of blank lines just above it (spinner + task list + footer below).
    for i in range(n - 1, lo - 1, -1):
        if "…" in plain[i]:
            j = i
            while j - 1 >= 0 and plain[j - 1].strip() == "":
                j -= 1
            cut = j
            break
    else:
        # Idle (no spinner): trim trailing separator bars / prompt / status / blanks.
        for i in range(n - 1, lo - 1, -1):
            p = plain[i].strip()
            bar_ct = sum(1 for c in p if c in "─━—-=")
            is_bar = len(p) >= 8 and (all(c in "─━—-=· " for c in p)
                                      or bar_ct >= len(p) * 0.5)
            if (p == "" or is_bar or "bypass permissions on" in p
                    or "for shortcuts" in p or p.startswith("❯")):
                cut = i
            else:
                break
    while cut > 0 and plain[cut - 1].strip() == "":
        cut -= 1
    return orig[:cut], plain[:cut]


def save_alt_capture(name: str, capture: str):
    """Append only the genuinely-new conversation lines from an alt-screen
    capture to the session log. Claude Code's alt buffer redraws the same
    viewport in place, so naively appending each capture stacks ~30 near-
    identical snapshots (repeated status bars, boot messages, 77% dupes). This
    trims the TUI chrome and de-duplicates the overlap with what's already
    saved, keeping the log a clean linear transcript. Throttled like
    save_session_log."""
    if not capture.strip():
        return
    now = time.monotonic()
    last = _last_log_save.get(name, 0)
    if now - last < _LOG_SAVE_INTERVAL:
        return
    # Only persist a STABLE frame. Capturing a redrawing alt-screen mid-stream
    # yields torn text (dropped chars/spaces) that can't be de-duplicated. Take
    # a couple of fresh captures a beat apart; if the pane is still changing,
    # bail WITHOUT bumping the throttle so the next poll retries once it settles.
    f1 = tmux_capture(name, 300)
    if not f1:
        return
    time.sleep(0.18)
    f2 = tmux_capture(name, 300)
    if not f2 or _STRIP_ANSI.sub("", f1) != _STRIP_ANSI.sub("", f2):
        return  # still rendering — wait for a quiet frame
    capture = f2
    conv_orig, conv_plain = _alt_conv_lines(capture)
    cnp = [p.rstrip() for p in conv_plain]
    if not any(p.strip() for p in cnp):
        return
    lp = _log_path(name)
    existing_tail = ""
    if lp.exists():
        try:
            size = lp.stat().st_size
            with lp.open("rb") as f:
                if size > 32_768:
                    f.seek(size - 32_768)
                existing_tail = f.read().decode("utf-8", errors="replace")
        except Exception:
            existing_tail = ""
    # Collapse blank runs in both sides before comparing — the log has already
    # been collapsed, but the alt-screen capture hasn't, so line counts diverge.
    def _collapse_lines(lines, orig_lines=None):
        out, out_orig = [], []
        blank = 0
        for i, l in enumerate(lines):
            if l.strip() == "":
                blank += 1
                if blank <= 1:
                    out.append(l)
                    if orig_lines is not None:
                        out_orig.append(orig_lines[i])
            else:
                blank = 0
                out.append(l)
                if orig_lines is not None:
                    out_orig.append(orig_lines[i])
        return (out, out_orig) if orig_lines is not None else (out, None)
    cnp, conv_orig_c = _collapse_lines(cnp, conv_orig)
    tailp_raw = [_STRIP_ANSI.sub("", l).rstrip() for l in existing_tail.splitlines()]
    tailp, _ = _collapse_lines(tailp_raw)
    # Longest prefix of the new conversation that already exists as a contiguous
    # block in the recent tail → append only the lines after it.
    k = 0
    maxk = min(len(cnp), 80)
    for cand in range(maxk, 0, -1):
        block = cnp[:cand]
        for st in range(len(tailp) - cand, -1, -1):
            if tailp[st:st + cand] == block:
                k = cand
                break
        if k:
            break
    new_lines = conv_orig_c[k:]
    _last_log_save[name] = now
    if not any(_STRIP_ANSI.sub("", l).strip() for l in new_lines):
        return  # nothing new since last save
    CC_LOGS.mkdir(parents=True, exist_ok=True)
    # Collapse the alt-screen's big empty band (input box anchored at the bottom)
    # so the log stays a tight transcript instead of accumulating blank gaps.
    chunk = (_collapse_blank_runs("\n".join(new_lines)) + "\n").encode("utf-8", errors="replace")
    try:
        existing_size = lp.stat().st_size if lp.exists() else 0
        if existing_size + len(chunk) > MAX_LOG_BYTES:
            existing = lp.read_bytes() if lp.exists() else b""
            lp.write_bytes((existing + chunk)[-MAX_LOG_BYTES:])
        else:
            with lp.open("ab") as f:
                f.write(chunk)
    except Exception:
        pass


# Raw cursor-move / hide-cursor escapes — the fingerprint of pre-stable-frame
# alt-screen garbage (captured TUI redraws). Clean logs and clean transcript
# renders use only colour SGR codes (…m) and have effectively zero of these.
_CURSOR_MOVE_RE = re.compile(r'\x1b\[(?:\d+;\d+H|\?25[lh]|\d+[ABCD]|H)')


def _log_looks_torn(text: str) -> bool:
    """True if a saved-log chunk is dense with raw cursor-move escapes — i.e. it
    predates the stable-frame saver and is torn TUI-redraw spam rather than a
    clean linear transcript."""
    if not text:
        return False
    n = len(text)
    if n < 2000:
        return False
    c = len(_CURSOR_MOVE_RE.findall(text))
    return c >= 20 and (c / (n / 1024)) >= 2.0


def _collapse_blank_runs(text: str, keep: int = 1) -> str:
    """Collapse runs of blank lines down to `keep`. Claude Code's alt-screen
    anchors its input box at the bottom of the terminal, so a short conversation
    leaves a big empty band between the content and the prompt that capture-pane
    records verbatim — that band reads as 'funky whitespace' in the peek. Blank
    detection is ANSI-aware (a line of only colour codes counts as blank)."""
    out: list[str] = []
    blanks = 0
    for ln in text.split("\n"):
        if _STRIP_ANSI.sub("", ln).strip() == "":
            blanks += 1
            if blanks <= keep:
                out.append("")
        else:
            blanks = 0
            out.append(ln)
    return "\n".join(out)


# amux's session-launch/relaunch scaffolding — leaks into a live capture whenever
# Claude has exited to a shell and been restarted (rate-limit, crash, /compact).
# All of it forms a contiguous block at the TOP of the frame, above the real
# terminal content, so we cut through the LAST scaffolding line we find.
_LAUNCH_MARKERS = re.compile(
    r'--dangerously-skip-permissions\s+--name\b'
    r'|unset CLAUDECODE CLAUDE_CODE_ENTRYPOINT'
    r'|Resume this session with:'
    r'|claude --resume\b'
    r'|The default interactive shell is now zsh'
    r'|please visit https://support\.apple\.com/kb/HT208050'
)
_BARE_PROMPT_RE = re.compile(r'^[A-Za-z0-9._-]{1,24}\$$')


def _strip_scroll_pill(text: str) -> str:
    """Claude Code's TUI draws a "Jump to bottom (click) ↓" scroll pill over its
    own transcript when the view is scrolled up. tmux composites that pill into
    the MIDDLE of whatever line it overlaps, so the peek shows a garbled line
    (reported on mixpeek-funnel: "…plan nudge Jump to bottom (click) ↓ these
    three…"). Strip the pill so the surrounding text reads cleanly. Conservative:
    only acts when the exact pill marker is present."""
    if not text or "Jump to bottom" not in text:
        return text
    return re.sub(r"\s*Jump to bottom \(click\)\s*[↓]?\s*", " ", text)


def _strip_launch_noise(text: str) -> str:
    """Remove amux's session-launch scaffolding from a captured frame (the
    `unset …; cd …; claude --model … --name <s>` relaunch command, the macOS zsh
    notice, and 'Resume this session with:' blocks). Conservative: only acts when
    a scaffolding marker is present, cuts through the LAST such line plus any
    trailing blank/bare-shell-prompt lines, and if nothing real remains it
    returns the input unchanged rather than blanking the peek."""
    if not text or ("--name" not in text and "Resume this session with" not in text
                    and "shell is now zsh" not in text):
        return text
    lines = text.split("\n")
    last = -1
    for i, ln in enumerate(lines):
        if _LAUNCH_MARKERS.search(_STRIP_ANSI.sub("", ln)):
            last = i
    if last < 0:
        return text
    j = last + 1
    while j < len(lines):
        clean = _STRIP_ANSI.sub("", lines[j]).strip()
        if clean == "" or _BARE_PROMPT_RE.match(clean):
            j += 1
        else:
            break
    kept = lines[j:]
    if not any(_STRIP_ANSI.sub("", l).strip() for l in kept):
        return text  # frame is all scaffolding — leave it rather than blank the peek
    return "\n".join(kept)


def load_session_log(session: str, tail_bytes: int = 0) -> str:
    """Load saved session log from disk.

    If tail_bytes > 0, read only the last tail_bytes of the file to avoid
    loading multi-MB logs into memory when only the end is needed.
    """
    lp = _log_path(session)
    if lp.exists():
        try:
            if tail_bytes > 0:
                size = lp.stat().st_size
                if size <= tail_bytes:
                    return lp.read_text(errors="replace")
                with lp.open("rb") as f:
                    f.seek(size - tail_bytes)
                    return f.read().decode("utf-8", errors="replace")
            return lp.read_text(errors="replace")
        except Exception:
            pass
    return ""


def _plain_log_path(session: str) -> Path:
    """Path to the ANSI-stripped mirror of a session log. Kept in a hidden
    subdir so it never collides with a real `<name>.log` or gets swept up by
    CC_LOGS.glob('*.log') (log-search, session listing)."""
    return CC_LOGS / ".plain" / f"{session}.log"


def _write_plain_log(session: str):
    """Materialize an ANSI-stripped copy of the session log — colour SGR *and*
    torn cursor-move escapes removed, blank runs collapsed — so a session can
    Read its own history as clean text instead of a wall of escape codes.
    Returns (path, size_bytes) or None when there is no source log."""
    lp = _log_path(session)
    if not lp.exists():
        return None
    try:
        text = _collapse_blank_runs(_STRIP_ANSI.sub("", lp.read_text(errors="replace")))
        data = text.encode("utf-8", errors="replace")
        cp = _plain_log_path(session)
        cp.parent.mkdir(parents=True, exist_ok=True)
        cp.write_bytes(data)
        return cp, len(data)
    except Exception:
        return None


def _session_jsonl_path(name: str):
    """Newest Claude Code JSONL conversation file for a session's working dir,
    or None. This is the authoritative, complete transcript (never torn like the
    alt-screen snapshot log)."""
    now = time.monotonic()
    cached = _jsonl_path_cache.get(name)
    if cached and (now - cached[0]) < 10:
        return cached[1]
    result = _session_jsonl_path_uncached(name)
    _jsonl_path_cache[name] = (now, result)
    return result


# A plan nobody has touched in over a day is not the session's live execution
# plan — the session moved on without maintaining it (Claude often leaves the
# last item 'completed' and starts new work with no TaskUpdate). Past this cutoff
# hide the strip entirely rather than headline a dead plan; the 6h client-side
# "· plan last updated Nh ago" caveat still covers the fresher-but-stale band.
# (mixpeek-clustering, 2026-07-10/14: a 4-day-old completed plan kept headlining.)
_PLAN_STALE_HIDE_SECS = float(os.environ.get("AMUX_PLAN_STALE_HIDE_HOURS", "24")) * 3600


def _session_cc_tasks(name: str) -> dict:
    """Read Claude Code's native task list for a session — the ephemeral
    TaskCreate/TaskUpdate items it stores in ~/.claude/tasks/<conv_id>/<n>.json
    (the agent's live execution plan, with blockedBy/blocks deps). Surfaced
    READ-ONLY in peek so you can see the agent's checklist without it touching
    the amux board (the durable, gated ledger stays the source of truth).
    Returns {tasks, counts, active, total}."""
    try:
        # Cross-link guard (AMUX-1730): if this session's metadata is pinned to
        # ANOTHER session's Claude conversation — two amux sessions collided onto
        # one conversation (both `--resume` the same id) — the resolved plan is
        # the OTHER session's live, actively-updated plan bleeding onto this one,
        # so it never clears (mixpeek-general showing mixpeek-frustrations'
        # MF-323 plan, 2026-07-18). A session must only surface ITS OWN plan.
        _owner = (_load_meta(name).get("cc_session_name") or "").strip()
        if _owner and _owner != name:
            return {"tasks": [], "counts": {}, "active": None, "total": 0,
                    "_suppressed": "cross-linked to " + _owner}
        p = _session_jsonl_path(name)
        if not p:
            return {"tasks": [], "counts": {}, "active": None, "total": 0}
        tdir = CLAUDE_HOME / "tasks" / p.stem
        if not tdir.is_dir():
            return {"tasks": [], "counts": {}, "active": None, "total": 0}
        # A pane showing the Claude splash with NO turns after it is a brand-new
        # conversation (previous one died — e.g. session limit — and Claude was
        # restarted). Its own id has no JSONL yet, so the resolver title-matches
        # the DEAD conversation and its plan renders as if live ("Plan 2/5" over
        # an empty session). Any plan is stale here. A --continue resume paints
        # prior ⏺ turns below the splash, so it is not suppressed.
        raw = tmux_capture(name, 40)
        if raw:
            clean = _STRIP_ANSI.sub("", raw)
            i = clean.rfind("Claude Code v")
            if i >= 0 and "⏺" not in clean[i:] and "●" not in clean[i:]:
                return {"tasks": [], "counts": {}, "active": None, "total": 0}
        tasks = []
        for jf in tdir.glob("[0-9]*.json"):
            try:
                d = json.loads(jf.read_text())
                mtime = jf.stat().st_mtime
            except Exception:
                continue
            if not isinstance(d, dict):
                continue
            tasks.append({
                "id": str(d.get("id") or jf.stem),
                "subject": (d.get("subject") or d.get("activeForm") or "").strip(),
                "activeForm": (d.get("activeForm") or "").strip(),
                "status": d.get("status") or "pending",
                "blockedBy": [str(x) for x in (d.get("blockedBy") or [])],
                "_mtime": mtime,
            })
        tasks.sort(key=lambda t: int(t["id"]) if t["id"].isdigit() else 1_000_000)
        counts = {}
        for t in tasks:
            counts[t["status"]] = counts.get(t["status"], 0) + 1
        # The headline should reflect what the session ACTUALLY last worked on.
        # Claude's convention is one in_progress at a time, but it often leaves
        # several stale in_progress items AND marks the real current task done —
        # so "first in_progress by id" points at a stale task (the reported bug).
        # The single most-recently-updated task file is the truest signal: in the
        # normal flow that's the current in_progress task; when a session just
        # finished something and hasn't started the next, it's that completed task
        # ("between tasks"), which matches reality better than a stale in_progress.
        active = max(tasks, key=lambda t: t["_mtime"]) if tasks else None
        # Newest task-file mtime = when the session last maintained its plan.
        # Surfaced so the UI can flag a stale plan: a session can keep working
        # for days without a single TaskUpdate, and a 2-day-old "Plan 10/15"
        # headline silently reads as current (mixpeek-clustering, 2026-07-10).
        updated_at = int(max((t["_mtime"] for t in tasks), default=0))
        # Dead-plan cutoff: untouched for >_PLAN_STALE_HIDE_SECS → the session
        # moved on without maintaining it, so suppress rather than headline it.
        if updated_at and (time.time() - updated_at) > _PLAN_STALE_HIDE_SECS:
            return {"tasks": [], "counts": {}, "active": None, "total": 0}
        for t in tasks:
            t.pop("_mtime", None)
        if active:
            active = {k: v for k, v in active.items() if k != "_mtime"}
        return {"tasks": tasks, "counts": counts, "active": active,
                "total": len(tasks), "updated_at": updated_at}
    except Exception:
        return {"tasks": [], "counts": {}, "active": None, "total": 0}


def _session_jsonl_path_uncached(name: str):
    env_file = CC_SESSIONS / f"{name}.env"
    if not env_file.exists():
        return None
    try:
        cfg = parse_env_file(env_file)
    except Exception:
        return None
    wd = (cfg.get("CC_DIR") or "").strip()
    if not wd:
        return None
    try:
        # Deterministic path first: the PostToolUse hook reports Claude's live
        # session_id (+ real cwd) on every tool call — <id>.jsonl IS this
        # session's conversation. Title matching below is only a fallback: in
        # shared workdirs conversations get resumed across sessions and titles
        # go stale, which made peeks render another session's (or an old)
        # transcript — whole turns missing vs tmux.
        meta = _load_meta(name)
        conv_id = (meta.get("cc_conversation_id") or "").strip()
        for base in ((meta.get("cc_cwd") or "").strip(), wd):
            if not (conv_id and base):
                continue
            cand = CLAUDE_HOME / "projects" / _project_name(base) / f"{conv_id}.jsonl"
            if cand.is_file():
                return cand
        project_dir = CLAUDE_HOME / "projects" / _project_name(wd)
        if not project_dir.is_dir():
            return None
        files = sorted(project_dir.glob("*.jsonl"),
                       key=lambda f: f.stat().st_mtime, reverse=True)
        if not files:
            return None
        if len(files) == 1:
            return files[0]
        # Multiple conversations live in this project dir — several amux sessions
        # share one CC_DIR (e.g. studio-plg + mixpeek-studio). Returning the
        # newest bleeds ANOTHER session's transcript into this session's peek, so
        # resolve to THIS session's own conversation by matching Claude Code's
        # per-conversation title (set from the launch `--name`) to the amux
        # session name. Files are mtime-desc, so the first match is this
        # session's newest conversation.
        for jf in files:
            try:
                with jf.open() as fh:
                    rec = json.loads(fh.readline() or "{}")
            except Exception:
                continue
            if rec.get("customTitle") == name or rec.get("sessionName") == name:
                return jf
        # No titled match. Do NOT fall back to the newest file — in a shared
        # workdir that's a SIBLING session's transcript bleeding into this one
        # (e.g. a freshly-created session that has no conversation of its own
        # yet). Exclude conversations already claimed by other amux sessions
        # (their meta records cc_conversation_id); only return a file if exactly
        # one plausibly-ours candidate remains, else show live-only (None).
        owned = set()
        try:
            for oenv in CC_SESSIONS.glob("*.env"):
                if oenv.stem == name:
                    continue
                ocid = (_load_meta(oenv.stem).get("cc_conversation_id") or "").strip()
                if ocid:
                    owned.add(ocid)
        except Exception:
            pass
        unclaimed = [jf for jf in files if jf.stem not in owned]
        return unclaimed[0] if len(unclaimed) == 1 else None
    except Exception:
        return None


def _tool_brief(name: str, inp) -> str:
    """A short one-line argument summary for a tool_use block."""
    if not isinstance(inp, dict):
        return ""
    for k in ("command", "file_path", "path", "pattern", "query", "url",
              "prompt", "description", "old_string"):
        v = inp.get(k)
        if isinstance(v, str) and v.strip():
            v = v.replace("\n", " ").strip()
            return v[:90] + ("…" if len(v) > 90 else "")
    return ""


def _tool_result_text(content) -> str:
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for x in content:
            if isinstance(x, dict) and x.get("type") == "text":
                parts.append(x.get("text", ""))
            elif isinstance(x, str):
                parts.append(x)
        return "\n".join(parts)
    return str(content)


# ── Markdown → ANSI (make transcript history look like Claude Code's terminal
#    render instead of raw markdown source) ─────────────────────────────────────
_MD_TABLE_SEP_RE = re.compile(r'^\s*\|?\s*:?-{2,}:?\s*(?:\|\s*:?-{2,}:?\s*)+\|?\s*$')
# base fg the assistant text is wrapped in — inline styles restore to it
_MD_BASE = "\x1b[39m"


def _md_inline(s: str) -> str:
    """Render inline Markdown (bold, italic, inline code) to ANSI, matching how
    Claude Code renders it in the terminal. Restores to the base assistant color
    so the surrounding wrapper's colour is preserved."""
    # inline code first so ** inside code isn't treated as bold. Colour 153
    # (lavender) is Claude Code's actual terminal inline-code colour — verified
    # against live `tmux capture-pane -e` frames; earlier blue/orange were wrong.
    s = re.sub(r'`([^`\n]+)`', lambda m: '\x1b[38;5;153m' + m.group(1) + _MD_BASE, s)
    # **bold** / __bold__
    s = re.sub(r'\*\*([^*\n]+?)\*\*', lambda m: '\x1b[1m' + m.group(1) + '\x1b[22m', s)
    s = re.sub(r'(?<!\w)__([^_\n]+?)__(?!\w)', lambda m: '\x1b[1m' + m.group(1) + '\x1b[22m', s)
    # *italic* / _italic_ — single delimiter, not adjacent to a word char or a
    # space (so it never eats `2*3`, `*.py` globs, `- ` bullets, or math).
    s = re.sub(r'(?<![\w*])\*(?!\s)([^*\n]+?)(?<!\s)\*(?![\w*])',
               lambda m: '\x1b[3m' + m.group(1) + '\x1b[23m', s)
    s = re.sub(r'(?<![\w_])_(?!\s)([^_\n]+?)(?<!\s)_(?![\w_])',
               lambda m: '\x1b[3m' + m.group(1) + '\x1b[23m', s)
    return s


def _md_render_table(block: list, max_width: int = 100) -> str:
    """Render a Markdown table as a box-drawing table, WRAPPING cells so the whole
    table fits within max_width columns — like Claude Code's terminal render. This
    caps table width so a wide cell can't blow the row out to hundreds of columns
    and break the peek (the box-drawing then wraps mid-glyph in the browser)."""
    import textwrap

    def cells(row: str) -> list:
        r = row.strip()
        if r.startswith('|'):
            r = r[1:]
        if r.endswith('|'):
            r = r[:-1]
        return [c.strip() for c in r.split('|')]

    def strip_md(s: str) -> str:  # width math is on plain text; no ANSI inside cells
        s = re.sub(r'`([^`]+)`', r'\1', s)
        s = re.sub(r'\*\*([^*]+)\*\*', r'\1', s)
        s = re.sub(r'__([^_]+)__', r'\1', s)
        return s

    rows = [[strip_md(c) for c in cells(block[0])]] + [[strip_md(c) for c in cells(r)] for r in block[2:]]
    ncol = max((len(r) for r in rows), default=0)
    if ncol == 0:
        return "\n".join(block)
    for r in rows:
        r.extend([''] * (ncol - len(r)))
    natural = [max((len(rows[ri][ci]) for ri in range(len(rows))), default=0) for ci in range(ncol)]
    avail = max(ncol * 6, max_width - (3 * ncol + 1))   # leave room for the borders
    widths = list(natural)
    guard = 0
    while sum(widths) > avail and guard < 10000:        # shrink the widest column until it fits
        guard += 1
        mx = max(range(ncol), key=lambda c: widths[c])
        if widths[mx] <= 6:
            break
        widths[mx] -= 1

    widths = [max(1, w) for w in widths]   # never 0 — textwrap.wrap(w=0) raises

    def wrap_cell(text: str, w: int) -> list:
        return textwrap.wrap(text, max(1, w), break_long_words=True, break_on_hyphens=False) or ['']

    def render_row(cs: list, header: bool = False) -> str:
        wrapped = [wrap_cell(cs[ci], widths[ci]) for ci in range(ncol)]
        h = max(len(w) for w in wrapped)
        out = []
        for k in range(h):
            parts = []
            for ci in range(ncol):
                seg = wrapped[ci][k] if k < len(wrapped[ci]) else ''
                pad = seg + ' ' * (widths[ci] - len(seg))
                parts.append(('\x1b[1m' + pad + '\x1b[22m') if (header and seg) else pad)
            out.append('│ ' + ' │ '.join(parts) + ' │')
        return '\n'.join(out)

    top = '┌' + '┬'.join('─' * (w + 2) for w in widths) + '┐'
    mid = '├' + '┼'.join('─' * (w + 2) for w in widths) + '┤'
    bot = '└' + '┴'.join('─' * (w + 2) for w in widths) + '┘'
    res = [top, render_row(rows[0], header=True), mid]
    res.extend(render_row(r) for r in rows[1:])
    res.append(bot)
    return "\n".join(res)


def _md_to_ansi(text: str) -> str:
    """Render a practical subset of Markdown (bold, inline code, headers, and
    tables) to ANSI so transcript history matches Claude Code's terminal render
    rather than showing raw `**`, backticks and `| pipe |` tables.

    Fail-safe: any rendering error returns the ORIGINAL text — a formatting bug
    must never blank the transcript (a table crash once turned peeks into
    "(no output)")."""
    try:
        return _md_to_ansi_inner(text)
    except Exception:
        return text


def _md_to_ansi_inner(text: str) -> str:
    lines = text.split("\n")
    out: list = []
    i = 0
    while i < len(lines):
        ln = lines[i]
        # table: a pipe row followed by a |---|---| separator
        if (ln.strip().startswith('|') and ln.count('|') >= 2
                and i + 1 < len(lines) and _MD_TABLE_SEP_RE.match(lines[i + 1])):
            blk = [ln, lines[i + 1]]
            j = i + 2
            while j < len(lines) and lines[j].strip().startswith('|') and lines[j].count('|') >= 2:
                blk.append(lines[j])
                j += 1
            out.append(_md_render_table(blk))
            i = j
            continue
        # ATX header → bold, drop the leading #s
        hm = re.match(r'^(#{1,6})\s+(.*)$', ln)
        if hm:
            out.append('\x1b[1m' + _md_inline(hm.group(2)) + '\x1b[22m')
            i += 1
            continue
        out.append(_md_inline(ln))
        i += 1
    return "\n".join(out)


def _USER_ECHO_ANSI(txt: str) -> str:
    """User-message echo in Claude Code's exact style: fg-239 '❯ ' and fg-231
    text on a bg-237 highlight block, continuations indented 2 (captured from
    a live Claude Code pane — keep byte-identical for visual parity)."""
    return ("\x1b[38;5;239m\x1b[48;5;237m❯ \x1b[38;5;231m"
            + txt.replace("\n", "\n  ") + "\x1b[39m\x1b[49m")


def _render_session_transcript(name: str, max_chars: int = 40000) -> str:
    """Render a session's JSONL conversation as clean ANSI-colored text for the
    peek Transcript tab — the gap-free, never-torn alternative to the alt-screen
    snapshot history. Returns the tail (last max_chars)."""
    path = _session_jsonl_path(name)
    if not path:
        return ""
    try:
        st = path.stat()
    except OSError:
        return ""
    cache_key = (str(path), max_chars)
    cached = _transcript_render_cache.get(cache_key)
    if cached and cached[0] == st.st_mtime and cached[1] == st.st_size:
        return cached[2]
    # Read only the tail of the file — JSONL entries are much larger than their
    # rendered form, so 5x max_chars (min 5MB) is a safe overread estimate.
    max_read = max(max_chars * 5, 5_000_000)
    out: list[str] = []
    for o in _iter_jsonl_tail(path, max_bytes=max_read):
        if o.get("type") not in ("user", "assistant"):
            continue
        msg = o.get("message")
        if not isinstance(msg, dict):
            continue
        role = msg.get("role")
        content = msg.get("content")
        if isinstance(content, str):
            blocks = [{"type": "text", "text": content}]
        elif isinstance(content, list):
            blocks = content
        else:
            continue
        for b in blocks:
            if not isinstance(b, dict):
                continue
            bt = b.get("type")
            if bt == "text":
                txt = (b.get("text") or "").strip()
                if not txt:
                    continue
                if role == "user":
                    # Harness-injected wrappers are invisible in Claude Code's own UI
                    # (reminders, background-task completions, local-command caveats) —
                    # hide them here too instead of dumping the raw XML into the peek.
                    if ("<system-reminder>" in txt or "<task-notification>" in txt
                            or "<local-command-caveat>" in txt):
                        txt = re.sub(r"<system-reminder>.*?</system-reminder>", "", txt, flags=re.S)
                        txt = re.sub(r"<task-notification>.*?</task-notification>", "", txt, flags=re.S)
                        txt = re.sub(r"<local-command-caveat>.*?</local-command-caveat>", "", txt, flags=re.S)
                        txt = txt.strip()
                        if not txt:
                            continue
                    # Local slash-command turns are stored with meta tags; Claude Code
                    # shows the bare command + dim ⎿ output, never the raw tags
                    m_cmd = re.search(r"<command-name>(.*?)</command-name>", txt, re.S)
                    m_arg = re.search(r"<command-args>(.*?)</command-args>", txt, re.S)
                    m_out = re.search(r"<local-command-stdout>(.*?)</local-command-stdout>", txt, re.S)
                    if m_cmd or m_out:
                        if m_cmd and m_cmd.group(1).strip():
                            cmd_line = m_cmd.group(1).strip()
                            if m_arg and m_arg.group(1).strip():
                                cmd_line += " " + m_arg.group(1).strip()
                            out.append(_USER_ECHO_ANSI(cmd_line))
                        body = m_out.group(1).strip() if m_out else ""
                        if body:
                            for k, ln in enumerate(body.split("\n")[:6]):
                                prefix = "  ⎿  " if k == 0 else "     "
                                out.append("\x1b[38;5;246m" + prefix + ln.rstrip() + "\x1b[0m")
                        out.append("")
                        continue
                    # Match Claude Code's real echo: dim-gray ❯ on a subtle bg-237
                    # highlight block, near-white text — captured from a live pane
                    out.append(_USER_ECHO_ANSI(txt))
                else:
                    # Claude Code prefixes each assistant message with a white
                    # ⏺ bullet and renders prose in the default fg (not dim);
                    # continuation lines indent 2 cols under the bullet.
                    body = _md_to_ansi(txt).replace("\n", "\n  ")
                    # NOTE (AMUX-2118): this ⏺ is amux's PRESENTATION choice.
                    # The live pane may show ● instead (Claude Code's fallback
                    # glyph on terminals without U+23FA). peek `history` is a
                    # reconstruction from the JSONL — never source pane-parsing
                    # fixtures from it; use `live`/tmux capture, which is what
                    # the detectors actually read.
                    out.append("\x1b[38;5;231m⏺\x1b[39m " + body + "\x1b[0m")
                out.append("")
            elif bt == "tool_use":
                nm = b.get("name", "tool")
                arg = _tool_brief(nm, b.get("input"))
                # Claude's tool line: green ⏺ + bold ToolName + (args) in default fg
                out.append("\x1b[38;5;114m⏺\x1b[39m \x1b[1m" + str(nm) + "\x1b[0m"
                           + ("(" + arg + ")" if arg else ""))
            elif bt == "tool_result":
                # Preserve multi-line tool output (tables, query results, logs)
                # as indented continuation lines — matching Claude Code's own ⎿
                # display — instead of flattening newlines into one dense run-on
                # line, which rendered as garbled "logs" in the peek.
                raw = _tool_result_text(b.get("content"))
                rlines = [ln.rstrip() for ln in raw.split("\n")]
                while rlines and not rlines[0].strip():
                    rlines.pop(0)
                while rlines and not rlines[-1].strip():
                    rlines.pop()
                if rlines:
                    MAXL, MAXW = 6, 200
                    for k, ln in enumerate(rlines[:MAXL]):
                        if len(ln) > MAXW:
                            ln = ln[:MAXW] + "…"
                        prefix = "  ⎿  " if k == 0 else "     "
                        out.append("\x1b[38;5;246m" + prefix + ln + "\x1b[0m")
                    extra = len(rlines) - MAXL
                    if extra > 0:
                        out.append("\x1b[38;5;246m     … +" + str(extra)
                                   + (" more lines" if extra != 1 else " more line") + "\x1b[0m")
    text = "\n".join(out).strip("\n")
    if len(text) > max_chars:
        text = text[-max_chars:]
        nl = text.find("\n")
        if nl > 0:
            text = text[nl + 1:]
    _transcript_render_cache[cache_key] = (st.st_mtime, st.st_size, text)
    return text


def _trim_live_overlap(transcript: str, live: str) -> str:
    """Return the live frame minus the portion that re-renders content the
    transcript already covers. History must render from ONE source: the
    transcript is canonical and width-stable, while the frame re-renders the
    same messages at whatever width the tmux window happens to be at the time
    (attach/detach resizes change it) — the old approach kept the whole frame
    and trimmed the transcript, so width-mismatched re-renders slipped past the
    string matching and the same table/paragraph appeared twice at two
    different wraps. The frame's unique value is only its tail: in-progress
    streaming output (not yet flushed to the JSONL), the input box, and the
    status bar — everything after the last frame line the transcript already
    has. If fewer than 3 frame lines match the transcript tail, the frame is
    assumed disjoint (transcript stale/empty) and kept whole."""
    if not transcript or not live:
        return live

    def _norm(s: str) -> str:
        s = _STRIP_ANSI.sub("", s)
        # drop markdown / box-drawing / status decoration so raw-markdown
        # transcript lines match their rendered live-frame counterparts
        s = re.sub(r"[*#`_|\u2502\u250c\u2510\u2514\u2518\u251c\u2524\u252c\u2534\u253c\u2500=>\u2022\u00b7\u00bb\u276f\u23bf\u23fa\u273b\u2726\u25cf]+", " ", s)
        return re.sub(r"\s+", " ", s).strip().lower()

    tail_norm = [n for n in (_norm(x) for x in transcript.split("\n")[-140:]) if len(n) >= 12]
    tail_set = set(tail_norm)
    long_tail = [n for n in tail_norm if len(n) >= 46]

    def _in_transcript(n: str) -> bool:
        if len(n) < 12:
            return False
        if n in tail_set:
            return True
        # Wrap tolerance: a frame line wrapped at the tmux width is a substring
        # of the transcript's full logical line (or vice versa for short rows).
        if len(n) >= 24:
            for tv in long_tail:
                if n in tv or tv in n:
                    return True
        return False

    ll = live.split("\n")
    matches = [i for i, x in enumerate(ll) if _in_transcript(_norm(x))]
    if len(matches) < 3:
        return live
    return "\n".join(ll[matches[-1] + 1:]).lstrip("\n")


_healing_logs: set = set()  # sessions whose log is being rebuilt right now


def _heal_log_from_transcript(name: str):
    """One-time repair: replace a torn pre-stable-frame alt-screen log with a
    clean tail rendered from the authoritative JSONL transcript. No-op if the
    session has no JSONL or a heal for it is already in flight. The full history
    always remains available via the Transcript tab; we keep only a ~2MB tail in
    the log since the peek only ever displays the last 64KB."""
    if name in _healing_logs:
        return
    _healing_logs.add(name)
    try:
        clean = _render_session_transcript(name, max_chars=2_000_000)
        if not clean.strip():
            return  # no JSONL (e.g. non-Claude session) — leave the log as-is
        header = ("=== history rebuilt from clean JSONL transcript "
                  "(full history in the Transcript tab) ===\n\n")
        data = (header + clean).rstrip() + "\n"
        lp = _log_path(name)
        CC_LOGS.mkdir(parents=True, exist_ok=True)
        lp.write_bytes(data.encode("utf-8", errors="replace"))
    except Exception:
        pass
    finally:
        _healing_logs.discard(name)


# Tracks last JSONL backup mtime per session to avoid redundant copies
_last_jsonl_backup: dict[str, float] = {}


def _session_work_dir_early(name: str) -> str:
    """Return CC_DIR for a session (early binding — before _session_work_dir is defined)."""
    env_file = CC_SESSIONS / f"{name}.env"
    if not env_file.exists():
        return ""
    for line in env_file.read_text(errors="replace").splitlines():
        line = line.strip()
        if line.startswith("CC_DIR="):
            val = line[len("CC_DIR="):].strip()
            if val:
                return str(Path(val).expanduser().resolve())
    return ""


_GIT_AUTH_ERR = ("permission denied", "could not read username", "authentication failed",
                 "host key verification failed", "publickey", "repository not found",
                 "could not read from remote repository", "connection closed by remote",
                 "connection refused", "operation timed out")

def _https_equiv(remote_url: str) -> str:
    """Anonymous-HTTPS equivalent of a git remote URL (public repos only).
    git@github.com:owner/repo.git → https://github.com/owner/repo.git"""
    m = re.match(r"^(?:ssh://)?git@([^:/]+)[:/](.+?)(?:\.git)?$", remote_url.strip())
    if m:
        return f"https://{m.group(1)}/{m.group(2)}.git"
    return remote_url

def _git_pull_with_fallback(repo_dir: str) -> tuple[bool, str]:
    """git pull --ff-only; on an AUTH failure (SSH key missing in a cron env,
    stale HTTPS credential — Doron's silent hourly failures, 2026-07-17), retry
    anonymously over HTTPS: amux is a public repo, so UPDATING must never depend
    on the user's git credentials. The origin remote config is left untouched."""
    r = subprocess.run(["git", "pull", "--ff-only"],
                       cwd=repo_dir, capture_output=True, text=True, timeout=30)
    output = (r.stdout + r.stderr).strip()
    if r.returncode == 0:
        return True, output
    if any(k in output.lower() for k in _GIT_AUTH_ERR):
        ru = subprocess.run(["git", "remote", "get-url", "origin"],
                            cwd=repo_dir, capture_output=True, text=True, timeout=10)
        https_url = _https_equiv(ru.stdout.strip()) if ru.returncode == 0 else ""
        br = subprocess.run(["git", "rev-parse", "--abbrev-ref", "HEAD"],
                            cwd=repo_dir, capture_output=True, text=True, timeout=10)
        branch = br.stdout.strip() or "main"
        if https_url.startswith("https://"):
            r2 = subprocess.run(
                ["git", "-c", "credential.helper=", "pull", "--ff-only", https_url, branch],
                cwd=repo_dir, capture_output=True, text=True, timeout=30,
                env={**os.environ, "GIT_TERMINAL_PROMPT": "0"})
            out2 = (r2.stdout + r2.stderr).strip()
            if r2.returncode == 0:
                return True, (f"origin auth failed — pulled anonymously via {https_url}\n{out2}")
            output += "\n[https fallback also failed] " + out2
    return False, output


def _install_channel() -> str:
    """How this copy of amux was installed: 'source' (git checkout — updates via
    git pull), 'brew' (Homebrew cellar), 'pip' (site-packages via pip/pipx), or
    'standalone' (a bare copied file). Drives update routing — package-managed
    copies must not git-pull themselves."""
    here = Path(__file__).resolve()
    p = str(here)
    d = here.parent
    while d != d.parent:
        if (d / ".git").exists():
            return "source"
        d = d.parent
    if "/Cellar/" in p or "/homebrew/" in p or "/Homebrew/" in p:
        return "brew"
    if "site-packages" in p or "dist-packages" in p:
        return "pip"
    return "standalone"


def backup_session_jsonl(session: str, reason: str = "manual") -> str | None:
    """Copy the latest JSONL conversation file for a session to ~/.amux/transcripts/<session>/.

    Returns the backup path on success, None if nothing to back up.
    Keeps at most 20 backups per session (removes oldest when exceeded).
    """
    wd = _session_work_dir_early(session)
    if not wd:
        return None
    project_dir = CLAUDE_HOME / "projects" / _project_name(wd)
    if not project_dir.is_dir():
        return None
    jsonl_files = sorted(project_dir.glob("*.jsonl"), key=lambda f: f.stat().st_mtime, reverse=True)
    if not jsonl_files:
        return None
    src = jsonl_files[0]
    src_mtime = src.stat().st_mtime
    # Skip if already backed up this exact version
    last_mtime = _last_jsonl_backup.get(session, 0)
    if src_mtime <= last_mtime:
        return None
    dest_dir = CC_TRANSCRIPTS / session
    dest_dir.mkdir(parents=True, exist_ok=True)
    ts = time.strftime("%Y%m%dT%H%M%S")
    dest = dest_dir / f"{ts}_{reason}_{src.name}"
    try:
        import shutil
        shutil.copy2(str(src), str(dest))
        _last_jsonl_backup[session] = src_mtime
        # Prune oldest if > 20 backups
        all_backups = sorted(dest_dir.glob("*.jsonl"), key=lambda f: f.stat().st_mtime)
        for old in all_backups[:-20]:
            try:
                old.unlink()
            except Exception:
                pass
        _emit_event(session, "checkpoint.created", {"reason": reason, "path": str(dest)}, source="jsonl-backup")
        return str(dest)
    except Exception:
        return None


def list_session_transcripts(session: str) -> list[dict]:
    """List JSONL backup transcripts for a session, newest first."""
    dest_dir = CC_TRANSCRIPTS / session
    if not dest_dir.is_dir():
        return []
    files = sorted(dest_dir.glob("*.jsonl"), key=lambda f: f.stat().st_mtime, reverse=True)
    result = []
    for f in files:
        stat = f.stat()
        result.append({
            "name": f.name,
            "size": stat.st_size,
            "mtime": int(stat.st_mtime),
        })
    return result


# ── Yolo auto-responder ──────────────────────────────────────────────────────
# When a session runs with --dangerously-skip-permissions, some Claude Code
# internal safety prompts still require a keypress. We detect and answer them.
_YOLO_PROMPTS = [
    # Claude Code internal safety prompts always show "Esc to cancel" UI chrome.
    # Model-level direction questions never do. We require that marker so we never
    # auto-answer open-ended questions where the model is asking for user guidance.
    #
    # Shell command substitution: "Command contains $() command substitution … Esc to cancel"
    (re.compile(r'command contains.*command substitution.*esc to cancel', re.IGNORECASE | re.DOTALL), '1'),
    # Generic tool proceed prompt: "Do you want to proceed? ❯ 1. Yes … Esc to cancel"
    (re.compile(r'do you want to proceed.*esc to cancel', re.IGNORECASE | re.DOTALL), '1'),
    # Leaked permission prompt: "Yes, and don't ask again … Esc to cancel"
    (re.compile(r'yes.*and don.t ask again.*esc to cancel', re.IGNORECASE | re.DOTALL), '1'),
    # Codex MCP/plugin tool approval: "Allow X to <verb> …? 1. Allow 2. Allow for this session"
    (re.compile(r'allow\s+\S+\s+to\s+\w+.*\d\.\s*allow\b.*esc to cancel', re.IGNORECASE | re.DOTALL), '2'),
]
_YOLO_COOLDOWN = 6  # seconds between auto-responses per session
_yolo_last_responded: dict = {}


def _yolo_auto_respond():
    """Check yolo sessions for known blocking prompts and auto-answer them."""
    now = time.time()
    # Fetch running tmux sessions once to avoid spawning a subprocess per session
    running_sessions = set()
    try:
        r = subprocess.run(
            ["tmux", "list-sessions", "-F", "#{session_name}"],
            capture_output=True, text=True, timeout=5,
        )
        if r.returncode == 0:
            running_sessions = set(r.stdout.splitlines())
    except Exception:
        return  # tmux not available, nothing to do
    for f in CC_SESSIONS.glob("*.env"):
        name = f.stem
        try:
            if tmux_name(name) not in running_sessions:
                continue
            if now - _yolo_last_responded.get(name, 0) < _YOLO_COOLDOWN:
                continue
            cfg = parse_env_file(f)
            _flags = cfg.get('CC_FLAGS', '')
            _is_yolo = (
                '--dangerously-skip-permissions' in _flags
                or '--dangerously-bypass-approvals-and-sandbox' in _flags
                or cfg.get('CC_AUTO_CONTINUE') in ('1', 'true', 'yes')
            )
            if not _is_yolo:
                continue
            raw = tmux_capture(name, 50)
            if not raw:
                continue
            clean = re.sub(r'\x1b\[[0-9;?]*[a-zA-Z]|\x1b[^a-zA-Z]*[a-zA-Z]', '', raw)
            for i, (pattern, response) in enumerate(_YOLO_PROMPTS):
                if pattern.search(clean):
                    send_text(name, response)
                    _yolo_last_responded[name] = now
                    _posthog_emit("yolo_auto_answered", {
                        "session": name,
                        "pattern_idx": i,
                        "response": response,
                    }, distinct_id=name)
                    break
        except Exception:
            pass


def _yolo_loop():
    try:
        _yolo_auto_respond()
    except Exception:
        pass


# ── Rate-limit watchdog ──────────────────────────────────────────────────────
# Claude Code's /rate-limit-options prompt appears when a subscription usage
# cap is hit. The three-option menu lets the user either wait, add funds, or
# upgrade. amux auto-selects option 1 ("Stop and wait for limit to reset")
# fleet-wide — when one Max account hits its cap, every active session blocks
# at once, and pressing 1 by hand on each is impractical at scale.
#
# Unlike _YOLO_PROMPTS, this runs regardless of --dangerously-skip-permissions:
# the rate-limit prompt blocks every session equally, YOLO or not.
_RATE_LIMIT_PROMPTS = [
    # Anchor on the option-1 menu line. The "1." prefix confirms it's a menu
    # render and not the phrase appearing in arbitrary scrollback noise; the
    # full phrase ("Stop and wait for limit to reset") is distinctive enough
    # that we don't need to also match options 2/3, which keeps the pattern
    # robust if Anthropic relabels the other choices.
    (re.compile(r'1\.\s*stop and wait for limit to reset', re.IGNORECASE), '1'),
]


# Reset-time formats Claude Code is known to render in scrollback when a
# session hits the cap. We scan the surrounding tmux capture for any of them
# and convert to a unix timestamp so the watchdog can schedule an auto-resume.
_RATE_LIMIT_RESET_PATTERNS = [
    # "resets HH:MM" — wall-clock; today if still ahead, otherwise tomorrow.
    re.compile(r'resets?\s+(?:at\s+)?(\d{1,2}):(\d{2})\s*(am|pm)?\b', re.IGNORECASE),
    # "Resets in: 4 hours 23 minutes" — relative duration (hours and/or minutes).
    re.compile(r'resets?\s+in[:\s]+(?:(\d+)\s*h(?:ours?)?)?\s*(?:(\d+)\s*m(?:in(?:ute)?s?)?)?', re.IGNORECASE),
    # "reset on April 15, 2026 at 10:49 PM" — absolute date + 12h time.
    re.compile(
        r'reset(?:s|\s+on)?\s+(?:on\s+)?'
        r'(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|'
        r'aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)'
        r'\s+(\d{1,2}),?\s+(\d{4})\s+at\s+(\d{1,2}):(\d{2})\s*(am|pm)',
        re.IGNORECASE,
    ),
]

_MONTHS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12,
}

# Weekly/usage-cap banner: "resets Jun 26 at 5am" / "resets Jun 26 at 5:30 pm" /
# "resets Jun 26, 2026 at 5am" — month + day, OPTIONAL year, hour with am/pm,
# OPTIONAL minutes. Distinct from the strict absolute pattern above (which needs
# a year AND :MM), this catches the weekly-limit format which omits both.
_RATE_LIMIT_RESET_MONTHDAY_RE = re.compile(
    r'reset(?:s|\s+on)?\s+(?:on\s+)?'
    r'(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|'
    r'aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)'
    r'\s+(\d{1,2})(?:,?\s+(\d{4}))?\s+at\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)',
    re.IGNORECASE,
)

# The weekly/usage-limit banner itself (no interactive menu to answer, unlike
# the 5-hour /rate-limit-options prompt). Detecting it lets amux record the
# reset time so badges, bulk actions and auto-resume treat it like any other
# rate limit. e.g. "You've hit your weekly limit · resets Jun 26 at 5am (...)".
# Non-Claude provider limit banners (ethos D1: scrape allowed only because the
# provider exposes this state nowhere else). Codex's cap banner sat on a session
# card that read HEALTHY while the agent was hard-stopped until Aug 27 — found
# by the gates-adherence probe, filed as AMUX-2088. Routed down the CREDIT path
# (badge, no auto-resume), matched only against the live region's tail, and
# spans are bounded (.{0,N}) so DOTALL can't stitch prose to a distant mention.
_PROVIDER_LIMIT_RES = [
    ("codex", re.compile(r"You've hit your usage limit\..{0,160}?(?:Codex|ChatGPT)", re.IGNORECASE | re.DOTALL)),
    ("gemini", re.compile(r"(?:Quota exceeded|You have reached your (?:daily )?quota).{0,80}Gemini", re.IGNORECASE | re.DOTALL)),
]

_WEEKLY_LIMIT_RE = re.compile(
    r"(?:you'?ve\s+)?(?:hit|reached)\s+your\s+(?:weekly|usage)\s+limit",
    re.IGNORECASE,
)

# The newer session-limit banner — also menu-less, but the 5-hour window
# (resets same-day at a wall-clock time) rather than the weekly cap. Phrased
# "You've hit your session limit · resets 9:50am (America/New_York)". Without
# this, such sessions never get a reset time recorded, so they stay invisible
# to the badge/bulk-actions/auto-resume path. Classified as NON-weekly so it
# lands in the transient ("Rate-limited until") bucket, not the weekly one.
_SESSION_LIMIT_RE = re.compile(
    r"(?:you'?ve\s+)?(?:hit|reached)\s+your\s+session\s+limit",
    re.IGNORECASE,
)

# Per-model credit/usage limit — a DIFFERENT class than the weekly/session caps
# above. Phrased "You've reached your Fable 5 limit. Run /usage-credits to
# continue or switch models with /model." There is NO reset time: the fix is to
# top up credits or switch models, so "continue" won't unblock it (and auto
# resume must NOT fire on it). Anchor on the two strings unique to this banner
# (/usage-credits, "switch models with /model") so normal content never matches;
# like the other banners it's only tested against the LIVE tail.
_MODEL_CREDIT_LIMIT_RE = re.compile(
    r"/usage-credits\b|switch\s+models?\s+with\s+/model",
    re.IGNORECASE,
)
# Required alongside the fragment above: the banner always STATES the limit
# ("You've reached your Fable 5 limit"). Prose that merely cites "/usage-credits"
# — a commit message, a code comment, a relayed report — carries no such
# statement, and citing the fragment alone used to be enough to flag a healthy
# session.
_MODEL_CREDIT_LIMIT_CTX_RE = re.compile(
    r"reached\s+your\s+[A-Za-z0-9][A-Za-z0-9.\s-]{0,19}?\s+limit",
    re.IGNORECASE,
)
# The MENU-style variant of the same gate, shipped later:
#     Fable 5 now uses usage credits
#     Fable 5 runs on usage credits, purchased separately from your plan.
#     You don't have usage credits yet.
#       1. Set up usage credits on claude.ai
#     ❯ 2. Switch to Opus 5 (1M context) and continue
#     Enter to confirm · Esc to cancel
# It carries NEITHER anchor above (no "/usage-credits", no "switch models with
# /model"), so _MODEL_CREDIT_LIMIT_RE missed it entirely and two sessions sat
# wedged with credit_limited=False — invisible to the badge and to the one-tap
# model-switch bulk action (gtm-media-assets + gtm-videos, 2026-07-27; same
# class as AMUX-1272 / AMUX-1256). Anchor on the numbered menu OPTION line,
# which only exists in a live render — the prose alone shows up whenever a
# session merely discusses the gate (this file does). Callers additionally
# require it in the live region's tail.
# ── Transient API errors (529 Overloaded / 5xx) ──────────────────────────────
# Claude Code prints these inline and then just STOPS, leaving the session at a
# prompt. amux saw status=idle with every limit flag false, so a session looping
# on 529 was indistinguishable from one that had finished its work — six sessions
# were in that state when this was found, primis having burned SEVEN consecutive
# attempts (including a manual "continue") with no badge, no alert, and no place
# in Bulk actions.
#
# Unlike a credit limit (needs a model switch) or a weekly cap (needs to wait for
# a known reset), a 5xx is server-side and immediately retryable — so the correct
# bulk action really is "send continue", which is what was asked for.
_API_ERROR_RE = re.compile(r"API Error:\s*(5\d\d)\b", re.IGNORECASE)
# Anchored form: the marker line must START with the error (after the ⏺ glyph),
# which is how Claude Code emits it. Used for the decision; the loose form above
# is only used to COUNT occurrences once the decision is made.
_API_ERROR_START_RE = re.compile(r"^(?:[⏺●]\s*)?API Error:\s*(5\d\d)\b", re.IGNORECASE)
# API-key quota exhaustion arrives IN-BAND as a 4xx, not a banner: every
# session on an exhausted key prints "⏺ API Error: 400 You have reached your
# specified API usage limits. You will regain access on 2026-08-01 at 00:00
# UTC." and then just sits there looking idle (AMUX-2111; fleet-wide live
# specimen on the cloud gateway key, 2026-07-31). Unlike a 5xx this is a HARD
# gate — but unlike the credit gates it carries a machine-readable reset, so
# it maps onto rate_limit_reset_at and auto-resume genuinely works once the
# key regains access.
# The marker test runs on one physical line; the phrase and timestamp run on
# the tail with line breaks REMOVED, because tmux hard-wraps the capture at
# pane width and splits mid-word (observed live: "You will rega/in access").
# Raw concat self-heals mid-word splits; the \s* between words absorbs
# word-boundary wraps whether or not they keep the space.
_API_QUOTA_MARKER_RE = re.compile(
    r"^(?:[⏺●]\s*)?API Error:\s*4\d\d\b", re.IGNORECASE)
_API_QUOTA_PHRASE_RE = re.compile(
    r"API\s*usage\s*limits", re.IGNORECASE)
_API_QUOTA_RESET_RE = re.compile(
    r"regain\s*access\s*on\s*(\d{4})-(\d{2})-(\d{2})\s*at\s*(\d{1,2}):(\d{2})\s*UTC",
    re.IGNORECASE)
# The gateway's own budget wall is a third in-band class (AMUX-2113): "API
# Error: 402 amux trial budget exhausted ($25.03 of $25.00). Upgrade at
# https://cloud...". No reset time exists — the fix is an upgrade/top-up — so
# it carries credit-path semantics, not a reset target. Same wrap tolerance
# as the quota patterns.
_API_BUDGET_MARKER_RE = re.compile(
    r"^(?:[⏺●]\s*)?API Error:\s*402\b", re.IGNORECASE)
_API_BUDGET_PHRASE_RE = re.compile(
    r"budget\s*exhausted", re.IGNORECASE)


def _api_error_region(clean: str) -> tuple:
    """(last activity-marker line, capture-tail lines) — the shared structural
    anchor for in-band API-error detection. See _api_error_state for why the
    anchor is the LAST activity marker above the input box, and why it reads
    the capture tail rather than _live_limit_region's slice."""
    lines = [l.rstrip() for l in clean.splitlines()[-60:]]
    box = -1
    for i, l in enumerate(lines):
        if l.strip()[:1] == "❯":
            box = i          # candidate live input box; echoes also start with ❯
    # A ❯ line is only the LIVE input box if no transcript marker follows it.
    # Echoed user messages start with ❯ too, and a session with no live box
    # rendered (manual mode) has its last echo sitting ABOVE fresh transcript:
    # cutting there swallowed everything below, and a fleet-wide cloud 400
    # read rate_limited_until=0 with the error directly under '❯ ping'
    # (AMUX-2111 respecimen, 2026-07-31). Content after the last ❯ means that
    # ❯ was an echo — keep the whole tail. Cost: error text PASTED into a
    # live composer (wrapped onto ⏺-prefixed lines below its ❯) could flag;
    # that needs the paste to persist two scans, and the inverse failure was
    # live, not hypothetical.
    if box >= 0 and any(_LIMIT_ACTIVITY_RE.match(l.strip()) for l in lines[box + 1:]):
        box = -1
    region = lines[:box] if box >= 0 else lines
    last_marker = ""
    for l in region:
        if _LIMIT_ACTIVITY_RE.match(l.strip()):
            last_marker = l.strip()
    return last_marker, lines


def _api_quota_reset(clean: str):
    """Epoch reset time when an in-band 4xx usage-limit API error is the
    session's CURRENT state (same structural anchor as _api_error_state),
    else None. Only flags when the reset timestamp parses: the timestamp is
    what makes this class actionable (rate_limit_reset_at → auto-resume), so
    a 4xx without one stays unflagged rather than badging with no target."""
    marker, lines = _api_error_region(clean)
    if not marker or not _API_QUOTA_MARKER_RE.match(marker):
        return None
    # Line breaks removed, not joined: see the _API_QUOTA_*_RE comment on
    # tmux's mid-word hard-wrapping.
    flat = "".join(lines)
    if not _API_QUOTA_PHRASE_RE.search(flat):
        return None
    m = _API_QUOTA_RESET_RE.search(flat)
    if not m:
        return None
    import datetime as _dt
    y, mo, d, h, mi = (int(x) for x in m.groups())
    try:
        return int(_dt.datetime(y, mo, d, h, mi,
                                tzinfo=_dt.timezone.utc).timestamp())
    except ValueError:
        return None


def _api_budget_gated(clean: str) -> bool:
    """True when the gateway's 402 budget wall is the session's CURRENT state
    (same structural anchor as _api_error_state). No reset time exists — the
    fix is an upgrade/top-up — so callers feed this into the CREDIT path
    rather than a reset target."""
    marker, lines = _api_error_region(clean)
    if not marker or not _API_BUDGET_MARKER_RE.match(marker):
        return False
    # Line breaks removed, not joined: see the _API_QUOTA_*_RE comment on
    # tmux's mid-word hard-wrapping.
    return bool(_API_BUDGET_PHRASE_RE.search("".join(lines)))


def _api_error_state(clean: str) -> tuple:
    """(code, occurrences) when a transient API error is the session's CURRENT
    state, else ('', 0).

    Takes the whole clean capture, NOT _live_limit_region's slice. That slice
    keeps only what follows the last activity marker — and '⏺ API Error: 529'
    IS an activity marker, so the region excluded the very line being looked
    for. Measured on roadtrip while it was visibly erroring: the live viewport
    held 4 non-empty lines (prompt box + status bar) and the slice held none of
    the error. Claude Code prints its transcript to normal scrollback and keeps
    only the input box live, so anything transcript-shaped must be read from the
    capture tail.

    The anchor is structural rather than a window size: drop the input box and
    everything below it, then take the LAST activity-marker line. On a 5xx,
    Claude Code prints the error and stops, so that last marker IS the error. If
    the session produced any output afterwards, the last marker is that output
    instead and nothing is flagged — which is what keeps a session that merely
    QUOTES the string (this file does) from flagging itself, the same false
    positive that once told a sender its delivered message had failed
    (social-media, 2026-07-27).
    """
    last_marker, lines = _api_error_region(clean)
    if not last_marker:
        return "", 0
    # Must BEGIN with the error, not merely contain it. A session explaining the
    # error ('⏺ It looks for "API Error: 529 Overloaded" in the tail') is also a
    # marker line sitting above a prompt, and a `search` flagged it — verified as
    # a false positive before this anchor was added. Claude Code emits the error
    # as the entire line, so requiring the start separates the two cleanly.
    m = _API_ERROR_START_RE.match(last_marker)
    if not m:
        return "", 0
    # Occurrences across the captured tail: one blip vs a wedged retry loop.
    return m.group(1), len(_API_ERROR_RE.findall("\n".join(lines)))


_MODEL_CREDIT_MENU_RE = re.compile(
    r"^\s*\d+\.\s*set\s+up\s+usage\s+credits",
    re.IGNORECASE | re.MULTILINE,
)
# The modal's prose lines, used only as corroboration for the option line above.
_MODEL_CREDIT_BANNER_RE = re.compile(
    r"(?:uses|runs\s+on|have)\s+usage\s+credits",
    re.IGNORECASE,
)
# Spend-limit adjustment menu (gtm-videos, 2026-08-02 / GMA-29): yet another
# gate render — "What do you want to do?  Usage credit balance: $N /
# ❯ Adjust monthly spend limit: $N / Wait for limit to reset  Resets 1pm (TZ)".
# ETHAN-32's verification of AMUX-1898 was real AND expired: a pattern list
# answers "does this render match a gate I know", which needs a new entry per
# variant forever (the pattern-free stalled-Nm badge is the durable half —
# gtm-media-assets' framing). Detection only: this menu's default-selected row
# ADJUSTS A SPEND LIMIT, i.e. money, so amux never auto-answers it regardless
# of rate_limit_action; badge + is:gated + bulk visibility, human presses keys.
_SPEND_MENU_OPT_RE = re.compile(r"Adjust\s+monthly\s+spend\s+limit", re.I)
_SPEND_MENU_WAIT_RE = re.compile(r"Wait\s+for\s+limit\s+to\s+reset", re.I)
_SPEND_MENU_BAL_RE = re.compile(r"Usage\s+credit\s+balance", re.I)

# Pull the model name out for display ("Fable 5", "Opus", ...). Best-effort.
_MODEL_CREDIT_NAME_RE = re.compile(
    r"reached\s+your\s+([A-Za-z0-9][A-Za-z0-9.\s-]{0,19}?)\s+limit"
    r"|^\s*([A-Za-z0-9][A-Za-z0-9.\s-]{0,19}?)\s+now\s+uses\s+usage\s+credits",
    re.IGNORECASE | re.MULTILINE,
)

# Permissive fallback: any bare HH:MM (optionally with AM/PM) in the
# scrollback when none of the labeled patterns above match. Real-world
# Claude Code rendering wraps lines and may push the "resets" label off
# the same line as the time, so a bare-time scan within the menu's
# scrollback window is more robust than requiring the strict label.
# A >=5min-in-the-future filter blocks pickup of the current-time status
# bar (e.g. "✦ 14:23 thinking…").
_RATE_LIMIT_BARE_TIME_RE = re.compile(r'\b(\d{1,2}):(\d{2})\s*(am|pm)?\b', re.IGNORECASE)


def _parse_rate_limit_reset(text: str, now: float | None = None) -> int | None:
    """Scan text for a Claude Code rate-limit reset time and return a unix ts.

    Recognizes three TUI formats:
      - "resets HH:MM" or "resets at H:MM PM" (today, or tomorrow if past)
      - "Resets in: <N> hours <M> minutes" (relative duration)
      - "reset on <Month> <D>, <YYYY> at <H:MM AM/PM>" (absolute)

    Returns None if no recognizable format is present. The wall-clock formats
    are interpreted in the server's local time zone — Claude Code renders
    them in the user's local zone, and amux runs on the same machine.
    """
    import datetime as _dt
    if not text:
        return None
    now_ts = now if now is not None else time.time()
    base = _dt.datetime.fromtimestamp(now_ts)
    # Defensive ANSI strip — the handler already cleans the capture before
    # calling this, but selftests and any future direct caller may pass
    # raw tmux output.
    text = _STRIP_ANSI.sub("", text)

    # 1. "Resets in: N hours M minutes" — check first so it doesn't get
    #    swallowed by the bare "resets HH:MM" pattern (no colon → no match
    #    anyway, but ordering keeps intent obvious).
    m = _RATE_LIMIT_RESET_PATTERNS[1].search(text)
    if m and (m.group(1) or m.group(2)):
        hours = int(m.group(1) or 0)
        minutes = int(m.group(2) or 0)
        if hours or minutes:
            return int(now_ts + hours * 3600 + minutes * 60)

    # 2. Absolute "reset on April 15, 2026 at 10:49 PM"
    m = _RATE_LIMIT_RESET_PATTERNS[2].search(text)
    if m:
        month_key = m.group(1).lower()[:3]
        month = _MONTHS.get(month_key)
        day = int(m.group(2))
        year = int(m.group(3))
        hour = int(m.group(4))
        minute = int(m.group(5))
        meridiem = m.group(6).lower()
        if meridiem == 'pm' and hour != 12:
            hour += 12
        elif meridiem == 'am' and hour == 12:
            hour = 0
        if month and 0 <= hour < 24 and 0 <= minute < 60:
            try:
                dt = _dt.datetime(year, month, day, hour, minute)
                return int(dt.timestamp())
            except ValueError:
                pass

    # 2b. Absolute month/day "resets Jun 26 at 5am" (weekly-limit banner) —
    #     optional year, optional minutes. Checked before the bare HH:MM scan so
    #     the full date wins (otherwise "5am" would resolve to the next 5am, not
    #     the correct future day).
    m = _RATE_LIMIT_RESET_MONTHDAY_RE.search(text)
    if m:
        month = _MONTHS.get(m.group(1).lower()[:3])
        day = int(m.group(2))
        has_year = m.group(3) is not None
        year = int(m.group(3)) if has_year else base.year
        hour = int(m.group(4))
        minute = int(m.group(5) or 0)
        meridiem = m.group(6).lower()
        if meridiem == 'pm' and hour != 12:
            hour += 12
        elif meridiem == 'am' and hour == 12:
            hour = 0
        if month and 0 <= hour < 24 and 0 <= minute < 60:
            try:
                dt = _dt.datetime(year, month, day, hour, minute)
                # No explicit year and the date already passed → roll to next year.
                if not has_year and dt.timestamp() <= now_ts:
                    dt = dt.replace(year=year + 1)
                return int(dt.timestamp())
            except ValueError:
                pass

    # 3. "resets HH:MM" — today if still ahead, otherwise tomorrow.
    m = _RATE_LIMIT_RESET_PATTERNS[0].search(text)
    if m:
        hour = int(m.group(1))
        minute = int(m.group(2))
        meridiem = (m.group(3) or '').lower()
        if meridiem == 'pm' and hour != 12:
            hour += 12
        elif meridiem == 'am' and hour == 12:
            hour = 0
        if 0 <= hour < 24 and 0 <= minute < 60:
            candidate = base.replace(hour=hour, minute=minute, second=0, microsecond=0)
            if candidate.timestamp() <= now_ts:
                candidate += _dt.timedelta(days=1)
            return int(candidate.timestamp())

    # 4. Bare-time fallback. Take the earliest HH:MM at least 5 minutes
    # in the future — that filters out current-time status-bar renders
    # like "✦ 14:23 thinking…" while still catching a "resets 14:30"
    # that landed on its own wrapped line away from the "resets" word.
    candidates = []
    for mm in _RATE_LIMIT_BARE_TIME_RE.finditer(text):
        hour = int(mm.group(1))
        minute = int(mm.group(2))
        meridiem = (mm.group(3) or '').lower()
        if meridiem == 'pm' and hour != 12:
            hour += 12
        elif meridiem == 'am' and hour == 12:
            hour = 0
        if not (0 <= hour < 24 and 0 <= minute < 60):
            continue
        cand = base.replace(hour=hour, minute=minute, second=0, microsecond=0)
        if cand.timestamp() <= now_ts:
            cand += _dt.timedelta(days=1)
        if cand.timestamp() - now_ts < 300:
            continue  # too close to now — likely the current-time bar
        candidates.append(int(cand.timestamp()))
    if candidates:
        return min(candidates)

    return None


_RATE_LIMIT_DEFAULT_RESUME_TEXT = "continue"


def _should_skip_rate_limit_resume(scrollback_clean: str) -> tuple[bool, str]:
    """Decide whether auto-resume should be skipped at reset time.

    The watchdog parks a session by pressing 1 on the /rate-limit-options
    menu, which leaves Claude Code displaying a "waiting for limit to reset"
    confirmation. If at reset time the scrollback still shows that wait
    state, auto-resume is safe — we're just unblocking what we parked.

    If the user intervened (picked option 2 or 3 from the menu, typed
    something new, or otherwise moved past the wait state), the session
    is no longer parked where we left it, and steering "continue" would
    fight the user. Skip in that case.

    Returns (skip, reason). Reason is a short human-readable string for
    the log line; empty string when skip is False.
    """
    if not scrollback_clean:
        # Empty scrollback usually means the session is stopped/archived
        # and we can't see anything; safest to skip rather than risk
        # poking a session in an unknown state.
        return True, "no scrollback to inspect"
    tail = "\n".join(scrollback_clean.splitlines()[-30:]).lower()
    # Positive markers: Claude is still parked at the wait-for-reset state.
    if "waiting for" in tail and "reset" in tail:
        return False, ""
    if "stop and wait for limit to reset" in tail:
        # User hasn't pressed anything yet — pattern was matched but
        # the menu is still showing. Resume is premature; the auto-respond
        # cycle will press 1 first.
        return True, "rate-limit menu still showing"
    if "rate-limit-options" in tail or "rate limit" in tail:
        # Some related rate-limit UI is still on screen; user may be
        # interacting with it.
        return False, ""
    # No rate-limit-related markers anywhere in the tail → the session
    # has moved on. Don't fight the user.
    return True, "session moved past wait-state"


def _session_rate_limit_resume_text(cfg: dict) -> str:
    """Return the per-session text to steer at rate-limit reset.

    Read from CC_RATE_LIMIT_RESUME_TEXT in ~/.amux/sessions/<name>.env
    (defaults to "continue"). Lets supervisors/orchestrators use a
    richer resume prompt than a bare "continue".
    """
    val = cfg.get("CC_RATE_LIMIT_RESUME_TEXT", "").strip()
    return val or _RATE_LIMIT_DEFAULT_RESUME_TEXT


# Seconds between consecutive auto-responses for the same session. The
# scheduler tick is 3s, so with a 10s cooldown the watchdog fires no more
# than once every ~12s on a persistently-matching prompt (matches the
# behavior observed during manual verification). Real Claude clears the
# menu immediately after pressing 1, so this loop only matters when the
# menu text persists in scrollback — typically a simulation artifact
# where the prompt was injected via tmux send-keys without Enter and
# stayed pinned in the input area.
_RATE_LIMIT_COOLDOWN = 10
_RATE_LIMIT_CREDIT_RECHECK_S = 120
_RATE_LIMIT_DRIFT_TOLERANCE = 30  # seconds; reset times closer than this are "in sync"
_RATE_LIMIT_DRIFT_LOG_COOLDOWN = 600  # don't repeat the drift warning more than every 10 min
_rate_limit_last_responded: dict = {}
# Swallowed-exception ledger for the fleet scan loop (AMUX-2111 post-mortem):
# per-session dedupe so a recurring throw logs every ~10 min, not every scan.
_rate_limit_scan_err: dict = {}
# How long a needs:you card stays quiet before the holder is asked whether the
# ASK still holds (AMUX-2270). Config, not a constant, because the right value
# depends on how fast the human actually answers — which is not amux's to guess.
_NEEDSYOU_RENAG_DAYS = float(os.environ.get("AMUX_NEEDSYOU_RENAG_DAYS", "3"))
_scan_demoted_last: dict = {}   # session -> last FULL scan while self-reporting (D1 demotion)
# How long a self-report licenses scan demotion, and the liveness floor kept
# underneath it. Policy in config (D3/D4 exit shape), not a constant that
# silently becomes the ceiling: raise _HOOKS_LIVE_S as hooks get more reliable,
# lower _SCAN_DEMOTE_S if a class of state change turns out to need faster eyes.
_HOOKS_LIVE_S = int(os.environ.get("AMUX_HOOKS_LIVE_S", "1800"))
_SCAN_DEMOTE_S = int(os.environ.get("AMUX_SCAN_DEMOTE_S", "60"))
# An `idle` report is self-renewing: the only way a lane leaves idle is a
# prompt, and every prompt fires UserPromptSubmit -> report. So an idle report
# does not decay the way an `active` one does, and the lanes it covers (parked
# ones) are exactly where per-tick pane capture buys least. `active`/`waiting`
# reports keep the shorter window — those states DO go stale on their own.
_HOOKS_LIVE_IDLE_S = int(os.environ.get("AMUX_HOOKS_LIVE_IDLE_S", "86400"))


def _hooks_live(rep, now: float) -> bool:
    """Does this lane's self-report still license demoting its pane scan?"""
    if not rep:
        return False
    age = now - rep.get("ts", 0)
    return age < (_HOOKS_LIVE_IDLE_S if rep.get("state") == "idle" else _HOOKS_LIVE_S)
# Scan-demotion counters, exposed at GET /api/debug/scan. A skip that leaves no
# trace is the ethos-#4 failure: when the demotion eventually hides a state
# change, whoever looks must be able to SEE that scans were being skipped and
# for which lanes — not infer it from absence.
_scan_stats: dict = {"full": 0, "demoted": 0, "by_session": {}, "since": time.time()}
_rate_limit_last_drift_log: float = 0.0

# Proof the session produced output on a line: an assistant message (⏺), an
# echoed user message (❯ [09:32 AM] …), or a tool-run summary.
# ⏺/● both accepted: the live `tmux capture-pane` (what the scan reads)
# renders Claude Code's record glyph as ● U+25CF, while the peek endpoint
# yields ⏺ U+23FA — fixtures built from peek matched, live panes did not
# (AMUX-2111, cloud stage-probe run 30644742436: the ONLY failing stage was
# the marker lookup; phrase and reset parsed clean).
_LIMIT_ACTIVITY_RE = re.compile(r"^(?:[⏺●]\s|❯\s*\[\d|Ran \d+ shell command)")


def _live_limit_region(clean: str) -> str:
    """The slice of the live screen a usage-limit banner may legitimately occupy.

    Claude Code hits a limit at the END of a turn, so a real banner is the last
    transcript content before the input box. The exact same sentence also lands
    in ordinary scrollback when a *subagent* dies on its own limit —
    '⏺ Agent "x" failed: … You've reached your Fable 5 limit. Run /usage-credits …'
    — while the main loop shrugs and keeps working. Matching the raw tail flags
    those sessions forever: the text never leaves the screen, so the flag
    outlives the event and contradicts the live 'working' status.

    Both cases are separated by one signal: whether the session produced any
    output BELOW the banner. So drop the input box and everything under it (UI
    chrome + the background-agents panel), then keep only what follows the last
    activity marker. A banner in that slice is live; anything above it is history.
    """
    lines = clean.splitlines()[-30:]
    box = -1
    for i, l in enumerate(lines):
        if l.strip()[:1] == "❯":
            box = i  # candidate live input box; echoes also start with ❯
    # Same echo-vs-live-box discrimination as _api_error_region: a ❯ with
    # transcript markers below it is an echoed message, not the input box —
    # cutting there blinded every banner class on manual-mode panes (no live
    # box rendered), the failure the AMUX-2111 cloud respecimen exposed.
    if box >= 0 and any(_LIMIT_ACTIVITY_RE.match(l.strip()) for l in lines[box + 1:]):
        box = -1
    region = lines[:box] if box >= 0 else lines
    cut = -1
    for i, l in enumerate(region):
        if _LIMIT_ACTIVITY_RE.match(l.strip()):
            cut = i
    return "\n".join(region[cut + 1:])


def _rate_limit_budget_state(actions: dict, today_utc: str, budget: int) -> tuple[bool, int]:
    """Return (exhausted, used) for a session's auto-resume budget.

    Resets the per-session counter when the stored UTC day differs from
    today_utc (mutating `actions`). Isolated here so the selftest can verify
    midnight-rollover behavior without spinning up tmux.
    """
    if actions.get("rate_limit_budget_day") != today_utc:
        actions["rate_limit_budget_day"] = today_utc
        actions["rate_limit_resumes_today"] = 0
    used = int(actions.get("rate_limit_resumes_today", 0))
    return (used >= budget, used)


def _check_rate_limit_drift():
    """Warn if reset times parsed across the fleet disagree by >30s.

    The subscription cap is account-wide, so every blocked session should
    have the same reset time (within ~seconds). Larger drift usually means
    our parser misread one session's scrollback. Log-only — no behavior
    change.
    """
    global _rate_limit_last_drift_log
    now = time.time()
    if now - _rate_limit_last_drift_log < _RATE_LIMIT_DRIFT_LOG_COOLDOWN:
        return
    future_resets = []
    for name, actions in _session_auto_actions.items():
        r = actions.get("rate_limit_reset_at")
        if r and r > now:
            future_resets.append((name, r))
    if len(future_resets) < 2:
        return
    spread = max(r for _, r in future_resets) - min(r for _, r in future_resets)
    if spread > _RATE_LIMIT_DRIFT_TOLERANCE:
        _rate_limit_last_drift_log = now
        sample = ", ".join(f"{n}={r}" for n, r in sorted(future_resets)[:6])
        slog(f"[rate-limit] reset-time drift across fleet: spread={int(spread)}s "
             f"across {len(future_resets)} sessions ({sample}). "
             f"Likely a parser mis-read — verify by peeking each session.")


def _rate_limit_auto_respond():
    """Detect /rate-limit-options across the fleet and press 1 on each match.

    Mirrors _yolo_auto_respond's shape but runs on every running session
    regardless of YOLO mode — the rate-limit prompt blocks YOLO and
    non-YOLO sessions equally. On match, presses 1 to park the session
    at "waiting for limit to reset", parses the reset time from the
    surrounding scrollback, and stores it in _session_auto_actions[name]
    for the auto-resume scheduler to pick up later.
    """
    now = time.time()
    running_sessions = set()
    try:
        r = subprocess.run(
            ["tmux", "list-sessions", "-F", "#{session_name}"],
            capture_output=True, text=True, timeout=5,
        )
        if r.returncode == 0:
            running_sessions = set(r.stdout.splitlines())
    except Exception:
        return  # tmux not available
    for f in CC_SESSIONS.glob("*.env"):
        name = f.stem
        try:
            if tmux_name(name) not in running_sessions:
                continue
            if now - _rate_limit_last_responded.get(name, 0) < _RATE_LIMIT_COOLDOWN:
                continue
            # Already handled: if we already pressed "1" and recorded a
            # reset_at in the future, skip the expensive tmux capture.
            # Re-pressing "1" is destructive: the menu text lingers in
            # scrollback and re-matches, sending "1" as user input which
            # triggers another rate-limit cycle (CPU hot-loop).
            _existing_actions = _session_auto_actions.get(name)
            if _existing_actions:
                _ra = _existing_actions.get("rate_limit_reset_at")
                if _ra and _ra > now and not _existing_actions.get("rate_limit_credits"):
                    continue
                if (_existing_actions.get("rate_limit_credits")
                        and now - _existing_actions.get("rate_limit_last_event_ts", 0)
                        < _RATE_LIMIT_CREDIT_RECHECK_S):
                    continue
            # SCAN DEMOTION for self-reporting lanes (Ethan: do all 4, #1;
            # D1-exit step). A lane whose hooks reported state within the
            # window has PROVEN its hooks fire — capturing its pane every tick
            # is the poll the report endpoint exists to replace, and the
            # per-tick tmux subprocess × 40 lanes fed both halves of the
            # 08-02/03 wedge.
            #
            # The gate is "hooks are live" (_HOOKS_LIVE_S), NOT "the report is
            # fresh" (_SELF_REPORT_FRESH_S). Freshness is the right test for
            # TRUSTING a report's contents — the status loop uses it that way.
            # It is the wrong test for demoting the scan: an idle lane reports
            # once on Stop and then says nothing until its next turn, so a
            # freshness gate demotes exactly the 25s where the lane is least
            # interesting and full-rate scans the hours where nothing can
            # change without a hook firing. What licenses the demotion is that
            # this lane's harness DOES report; a 60s floor still catches
            # crashes, kills and limit banners.
            #
            # Hookless lanes (gemini/codex, or a lane whose hooks broke and
            # aged past the window) keep full-rate scans — the scraper is
            # their only voice, and losing hooks silently restores it.
            _rep_s = _session_reported.get(name)
            _sst = _scan_stats["by_session"].setdefault(name, {"full": 0, "demoted": 0})
            if (_hooks_live(_rep_s, now)
                    and (now - _scan_demoted_last.get(name, 0)) < _SCAN_DEMOTE_S):
                _scan_stats["demoted"] += 1; _sst["demoted"] += 1
                continue
            _scan_demoted_last[name] = now
            _scan_stats["full"] += 1; _sst["full"] += 1
            # 300 lines is enough to catch the reset-time line, which can
            # appear ~10-20 lines above the menu in Claude Code's UI.
            raw = tmux_capture(name, 300)
            if not raw:
                continue
            clean = _STRIP_ANSI.sub("", raw)
            existing = _session_auto_actions.get(name)
            # An actively-generating session is, by definition, NOT rate-limited.
            # Clear any stale/false flag (e.g. the weekly-limit phrase printed by
            # a tool or sitting in scrollback) so the badge stops contradicting
            # the live "working" status.
            # Direct activity evidence, not just the classified status
            # (social-media, 2026-08-03: WEEKLY-LIMIT badge lied for ~2.5h
            # while the session visibly worked — the frame never classified
            # 'active', so this clear never fired. A running spinner line or
            # a ⏺/● turn marker in the live tail is proof of generation
            # regardless of what the classifier makes of the whole frame).
            _tail12 = "\n".join(clean.splitlines()[-12:])
            _activity_evident = bool(
                _detect_claude_status(raw) == "active"
                or re.search(r"esc to interrupt|tokens\)\s*$", _tail12, re.M)
                or any(_LIMIT_ACTIVITY_RE.match(l.strip()) for l in _tail12.splitlines()))
            if _activity_evident:
                if existing and (existing.get("rate_limit_reset_at")
                                 or existing.get("rate_limit_weekly")
                                 or existing.get("rate_limit_banner")
                                 or existing.get("rate_limit_credits")):
                    existing.pop("rate_limit_reset_at", None)
                    existing.pop("rate_limit_reset_at_fallback", None)
                    existing.pop("rate_limit_weekly", None)
                    existing.pop("rate_limit_banner", None)
                    existing.pop("rate_limit_credits", None)
                    existing.pop("rate_limit_model_name", None)
                    slog(f"[rate-limit] session={name} active — cleared stale rate-limit flag")
                continue
            # The interactive /rate-limit-options menu is always rendered LIVE at
            # the bottom of the screen, so match it against the tail only — never
            # the full 300-line capture. Scanning the whole capture for the menu
            # phrase false-matches on stale scrollback (a selftest fixture, a doc,
            # or a session discussing rate limits) and then presses "1" into a
            # healthy session. The reset-TIME parse below still scans full `clean`
            # (the reset line can sit ~10-20 lines above the menu); only the
            # decision to press a key requires a live menu render.
            tail = "\n".join(clean.splitlines()[-30:])
            # The POLICY here is the human's, set once, not amux's (ethos dev-2):
            # rate_limit_action pref — 'wait' (default) answers the menu with
            # option 1 fleet-wide; 'off' detects but leaves the menu for a human.
            # The scrape itself stays only because Claude Code exposes this state
            # nowhere else; exit condition tracked in ethos.md known-deviations.
            try:
                _rl_row = get_db().execute("SELECT value FROM prefs WHERE key='rate_limit_action'").fetchone()
                _rl_action = (_rl_row[0] or "wait").strip().lower() if _rl_row else "wait"
            except Exception:
                _rl_action = "wait"
            matched_idx = -1
            for i, (pattern, response) in enumerate(_RATE_LIMIT_PROMPTS):
                if pattern.search(tail):
                    if _rl_action != "off":
                        send_text(name, response)
                        _rate_limit_last_responded[name] = now
                    matched_idx = i
                    break
            # Weekly/usage-cap banner has no menu to answer — detect it on its own
            # so we still record the reset time (badges, bulk actions, auto-resume).
            # Only match it on the LIVE screen (bottom ~30 lines): the phrase often
            # appears in scrollback or tool output (e.g. an API echoing another
            # session's state), which must NOT flag a healthy session.
            # ...and only against the slice below the session's last output: the
            # same banner text sits in scrollback whenever a *subagent* died on
            # its own limit, and that must not flag a healthy main loop.
            live = _live_limit_region(clean)
            is_weekly = matched_idx < 0 and bool(_WEEKLY_LIMIT_RE.search(live))
            is_session_banner = (matched_idx < 0 and not is_weekly
                                 and bool(_SESSION_LIMIT_RE.search(live)))
            # Both weekly and session-limit banners are menu-less and keep their
            # banner on screen until reset — group them as "banner" limits.
            is_banner = is_weekly or is_session_banner
            # Per-model credit limit: no reset time, NOT auto-resumable. Two
            # renders: the menu-less banner (_MODEL_CREDIT_LIMIT_RE) and the
            # newer "now uses usage credits" MENU. The menu's option line is
            # only tested against the live region's TAIL — the surrounding prose
            # appears in ordinary transcript whenever a session discusses the
            # gate, and flagging on that would wedge-label a healthy session.
            # Position, not just phrasing, is what makes the menu render real.
            # _live_limit_region cuts at the highlighted "❯ 2. Switch to <model>
            # and continue" row, so in a LIVE modal the "1. Set up usage credits"
            # option is the region's LAST line — always. A looser tail-window
            # check flagged a healthy session within minutes of shipping
            # (social-media, whose screen happened to be showing a message that
            # QUOTED this modal while we were debugging it). A false credit flag
            # is not cosmetic: it would sweep that session into the model-switch
            # bulk action. Require the exact position, corroborated by the
            # banner prose just above it.
            _live_ne = [l for l in live.splitlines() if l.strip()]
            # Non-Claude provider caps (codex/gemini) — checked BEFORE the
            # Claude classification is acted on, because codex phrases its cap
            # "You've hit your usage limit", which _WEEKLY_LIMIT_RE also
            # matches: the AMUX-2088 probe classified a codex cap as a Claude
            # weekly limit and scheduled auto-resume off "8:00 PM" lifted from
            # the WRONG provider's banner (actual codex reset: Aug 27). On a
            # provider hit the banner flags are cleared and the session routes
            # down the CREDIT path — badge + is:gated + hard-gate alert, no
            # reset time, no auto-resume nudging a lane amux cannot un-cap.
            # Searched over the SAME `live` region as the Claude banner
            # regexes, deliberately wider than the credit gates' tail-only
            # window: this check exists to disambiguate, so any placement
            # where _WEEKLY_LIMIT_RE can see the codex banner must be one the
            # provider check sees too (tail-8 left a 9..30-line band where the
            # codex banner re-classified as Claude-weekly). Text that would
            # false-positive here already false-positives the weekly regex on
            # the same words, so precedence cannot widen the blast radius —
            # and the two-scan persistence gate applies to this flag too.
            _provider_hit = ""
            if matched_idx < 0:
                for _pname, _pre in _PROVIDER_LIMIT_RES:
                    if _pre.search(live):
                        _provider_hit = _pname
                        is_weekly = is_session_banner = is_banner = False
                        break
            _is_menu_gate = bool(
                _live_ne
                and _MODEL_CREDIT_MENU_RE.search(_live_ne[-1])
                and _MODEL_CREDIT_BANNER_RE.search("\n".join(_live_ne[-6:])))
            # The BANNER variant needs the same positional discipline. It used to
            # be searched across the whole live region, so the literal string
            # "/usage-credits" anywhere in a transcript flagged the session —
            # which fires hardest on exactly the sessions discussing the gate: it
            # transiently flagged THIS session while it was implementing the
            # detector, and any session relaying a report about it. That warning
            # then rides out on every send to the target, so a false FAILURE gets
            # asserted to other agents (social-media, 2026-07-27). Claude Code
            # renders the banner as the last transcript content before the input
            # box, so the region's final few lines are where a live one is.
            _is_banner_gate = bool(
                _MODEL_CREDIT_LIMIT_RE.search("\n".join(_live_ne[-5:]))
                and _MODEL_CREDIT_LIMIT_CTX_RE.search("\n".join(_live_ne[-5:])))
            # Spend-limit menu: option line + corroboration (the wait option or
            # the balance readout). Tested against the CLEAN SCREEN's tail, not
            # the live region — _live_limit_region cuts AT the highlighted
            # "❯ Adjust monthly spend limit" row, so this menu's option lines
            # always fall OUTSIDE the region (verified against the live
            # gtm-videos gate: region ends at "What do you want to do?").
            # Position still holds: a live modal owns the bottom of the screen,
            # while a session merely QUOTING these strings has its own input
            # box/activity rendered below them — and the two-scan persistence
            # gate applies on top.
            _clean_tail = "\n".join(
                [l for l in clean.splitlines() if l.strip()][-8:])
            _is_spend_menu_gate = bool(
                _SPEND_MENU_OPT_RE.search(_clean_tail)
                and (_SPEND_MENU_WAIT_RE.search(_clean_tail)
                     or _SPEND_MENU_BAL_RE.search(_clean_tail)))
            # Gateway 402 budget wall (AMUX-2113): in-band, no reset time —
            # credit-path semantics, so it feeds _credit_raw and inherits the
            # two-scan gate, badge, is:gated, hard-gate alert and clear
            # machinery wholesale. The model-name slot names the gate so the
            # badge reads "trial budget limit".
            _budget_gated = matched_idx < 0 and _api_budget_gated(clean)
            _credit_raw = bool(_provider_hit) or _budget_gated or (
                matched_idx < 0 and not is_banner
                and (_is_banner_gate or _is_menu_gate or _is_spend_menu_gate))
            # PERSISTENCE GATE. No regex fully separates "this session is gated"
            # from "this session is displaying text about the gate" — the source
            # file documenting these very patterns matches them, so any session
            # reading it trips the check. But the two differ in TIME: a real gate
            # holds the screen until a human clears it, while quoted text scrolls
            # away. Require the match on two consecutive scans. That is what
            # makes the flag trustworthy enough to assert to other agents on the
            # send path, where a false positive tells a sender its message is
            # undeliverable when it was in fact delivered (social-media,
            # 2026-07-27). Costs one scan interval of detection latency.
            _st = _session_auto_actions.setdefault(name, {})
            _credit_prev = bool(_st.get("credit_raw_prev"))
            _st["credit_raw_prev"] = _credit_raw
            is_credit = _credit_raw and _credit_prev
            # Transient API error (529/5xx). Same two-scan persistence gate as the
            # credit gate, for the same reason: text about the error must not read
            # as the error. Recorded on _st (not `actions`) so it survives the
            # `continue` below — a session showing ONLY an API error has no
            # rate-limit UI at all and would otherwise bail out before the
            # actions dict is written.
            _api_code, _api_n = _api_error_state(clean)
            _api_prev = _st.get("api_err_prev") or ""
            _st["api_err_prev"] = _api_code
            if _api_code and _api_prev == _api_code:
                if not _st.get("api_error"):
                    slog(f"[api-error] session={name} API Error {_api_code} "
                         f"x{_api_n} on live screen — flagged retryable")
                _st["api_error"] = True
                _st["api_error_code"] = _api_code
                _st["api_error_count"] = _api_n
            elif not _api_code and _st.get("api_error"):
                # Cleared as soon as it scrolls off: a 5xx is transient, and a
                # stale flag would keep a working session in Bulk actions.
                _st.pop("api_error", None)
                _st.pop("api_error_code", None)
                _st.pop("api_error_count", None)
                slog(f"[api-error] session={name} API error cleared")
            # In-band 4xx quota gate (AMUX-2111): a hard stop with a REAL
            # reset time, printed as an API error rather than a banner. Same
            # two-scan persistence as above, recorded on _st for the same
            # reason (it must survive the no-rate-limit-UI `continue` below).
            # Setting rate_limit_reset_at gives the badge, is:gated and
            # auto-resume for free; cleared as soon as the error leaves the
            # live tail — output below it means the session is working again.
            _q_reset = _api_quota_reset(clean)
            _q_prev = int(_st.get("api_quota_prev") or 0)
            _st["api_quota_prev"] = _q_reset or 0
            if _q_reset and _q_prev == _q_reset:
                if not _st.get("rate_limit_api_quota"):
                    slog(f"[api-quota] session={name} in-band API usage-limit "
                         f"error — gated until {_q_reset} (parsed UTC reset)")
                _st["rate_limit_api_quota"] = True
                _st["rate_limit_reset_at"] = _q_reset
                _st.pop("rate_limit_reset_at_fallback", None)
                _st["rate_limit_last_event_ts"] = int(now)
            elif not _q_reset and _st.get("rate_limit_api_quota"):
                _st.pop("rate_limit_api_quota", None)
                _st.pop("rate_limit_reset_at", None)
                _st.pop("rate_limit_reset_at_fallback", None)
                slog(f"[api-quota] session={name} quota error cleared")
            if matched_idx < 0 and not is_banner and not is_credit:
                # No live rate-limit UI. A real banner cap keeps its banner on
                # screen until reset, so a session flagged from a banner without a
                # live banner was a false match — clear it. (5-hour menu flags park
                # in a bannerless "waiting for reset" state, so leave those alone.)
                if existing and (existing.get("rate_limit_weekly")
                                 or existing.get("rate_limit_banner")
                                 or existing.get("rate_limit_credits")):
                    existing.pop("rate_limit_reset_at", None)
                    existing.pop("rate_limit_reset_at_fallback", None)
                    existing.pop("rate_limit_weekly", None)
                    existing.pop("rate_limit_banner", None)
                    existing.pop("rate_limit_credits", None)
                    existing.pop("rate_limit_model_name", None)
                    slog(f"[rate-limit] session={name} limit banner not on live "
                         f"screen — cleared stale flag")
                continue
            if is_banner or is_credit:
                _rate_limit_last_responded[name] = now  # cooldown; nothing to press
            actions = _session_auto_actions.setdefault(name, {})
            _was_credit = bool(actions.get("rate_limit_credits"))
            actions["rate_limit_weekly"] = is_weekly
            actions["rate_limit_banner"] = is_banner
            actions["rate_limit_credits"] = is_credit
            if is_credit:
                # No reset time exists for a credit limit; auto-resume keys off
                # rate_limit_reset_at, so leaving it unset keeps auto-resume from
                # firing a useless "continue". Record the model name for the UI.
                # Same tail restriction: a model name lifted from prose higher up
                # would mislabel the badge even when the gate itself is real.
                m = _MODEL_CREDIT_NAME_RE.search("\n".join(_live_ne[-6:]))
                actions["rate_limit_model_name"] = (
                    _provider_hit
                    or ("trial budget" if _budget_gated else "")
                    or ("monthly spend" if _is_spend_menu_gate else "")
                    or ((m.group(1) or m.group(2) or "").strip() if m else ""))
                actions["rate_limit_last_event_ts"] = int(now)
                actions.pop("rate_limit_reset_at", None)
                actions.pop("rate_limit_reset_at_fallback", None)
                if not _was_credit:
                    slog(f"[rate-limit] session={name} model/credit limit "
                         f"(model={actions['rate_limit_model_name']!r}) — no reset, "
                         f"needs model switch or credit top-up")
                    _posthog_emit("rate_limit_model_credit", {
                        "session": name,
                        "model": actions["rate_limit_model_name"],
                    }, distinct_id=name)
                continue
            actions.pop("rate_limit_credits", None)
            actions.pop("rate_limit_model_name", None)
            parsed_reset = _parse_rate_limit_reset(clean, now=now)
            actions["rate_limit_last_event_ts"] = int(now)
            if parsed_reset:
                reset_at = parsed_reset
                actions["rate_limit_reset_at"] = reset_at
                actions.pop("rate_limit_reset_at_fallback", None)
                slog(f"[rate-limit] session={name} auto-selected option 1, "
                     f"reset_at={reset_at}")
            else:
                # Couldn't parse a reset time. Apply a safety fallback so
                # auto-resume still has a target. For the 5-hour menu prompt, 5 min
                # is safe (real windows are 1h+). For a banner cap (weekly or
                # session), a 5-min retry would just re-hit the cap in a loop, so
                # fall back to 6h — far enough to avoid churn, and the banner
                # re-detection will refine it once a parseable reset is on screen.
                reset_at = int(now + (6 * 3600 if is_banner else 300))
                actions["rate_limit_reset_at"] = reset_at
                actions["rate_limit_reset_at_fallback"] = True
                # Log a sanitized snippet so future debugging can see
                # what the parser actually saw. Single-line, capped
                # length so the server log stays readable.
                snippet = " | ".join(
                    l.strip() for l in clean.splitlines()[-12:] if l.strip()
                )[:240]
                slog(f"[rate-limit] session={name} auto-selected option 1, "
                     f"reset_at={reset_at} (5min safety fallback — no "
                     f"parseable reset time in scrollback); "
                     f"tail-snippet={snippet!r}")
            _posthog_emit("rate_limit_auto_handled", {
                "session": name,
                "pattern_idx": matched_idx,
                "reset_at": reset_at,
                "fallback": not parsed_reset,
            }, distinct_id=name)
        except Exception:
            # A poisoned iteration must not kill the fleet scan — but a SILENT
            # pass here made a real cloud negative indistinguishable from "the
            # loop threw before the parser ran" (AMUX-2111). Log it, deduped,
            # so an absent flag always carries evidence one way or the other.
            try:
                import traceback as _tb
                _now_e = time.time()
                if _now_e - _rate_limit_scan_err.get(name, 0) > 600:
                    _rate_limit_scan_err[name] = _now_e
                    slog(f"[rate-limit] scan error on {name}: "
                         f"{_tb.format_exc(limit=3)}")
            except Exception:
                pass


def _rate_limit_auto_resume():
    """Steer the configured resume text to sessions whose reset time passed.

    Respects fleet mode (off/capped/unlimited) and per-session budget.
    Calls the state-aware skip predicate to avoid fighting a user who
    moved past the wait-for-reset state.
    """
    import datetime as _dt
    now = time.time()
    today_utc = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%d")

    # Collect candidates first so we can bail out cheaply when nothing's due.
    candidates = [name for name, actions in list(_session_auto_actions.items())
                  if actions.get("rate_limit_reset_at")
                  and actions["rate_limit_reset_at"] <= now]
    if not candidates:
        return

    if _RATE_LIMIT_MODE == "off":
        # Clear stale reset-at so the badge doesn't linger past reset time.
        # The user has to steer the resume themselves in this mode.
        for name in candidates:
            actions = _session_auto_actions.get(name) or {}
            actions.pop("rate_limit_reset_at", None)
            slog(f"[rate-limit] session={name} reset time reached; "
                 f"auto-resume disabled (mode=off)")
        return

    running_sessions = set()
    try:
        r = subprocess.run(
            ["tmux", "list-sessions", "-F", "#{session_name}"],
            capture_output=True, text=True, timeout=5,
        )
        if r.returncode == 0:
            running_sessions = set(r.stdout.splitlines())
    except Exception:
        return

    resumed = 0
    skipped = 0
    budget_exhausted = 0
    for name in candidates:
        actions = _session_auto_actions.get(name) or {}
        env_file = CC_SESSIONS / f"{name}.env"
        if not env_file.exists():
            actions.pop("rate_limit_reset_at", None)
            continue
        try:
            cfg = parse_env_file(env_file)

            # Archived sessions have no live tmux to resume — drop the stale
            # reset so they stop being candidates instead of retrying forever.
            if cfg.get("CC_ARCHIVED") == "1":
                actions.pop("rate_limit_reset_at", None)
                continue

            # Always run the rollover so the per-day counter doesn't grow
            # forever in unlimited mode; second return is ignored unless
            # we're enforcing a cap.
            exhausted, used = _rate_limit_budget_state(
                actions, today_utc, _RATE_LIMIT_BUDGET)
            if _RATE_LIMIT_MODE == "capped":
                if exhausted:
                    actions.pop("rate_limit_reset_at", None)
                    budget_exhausted += 1
                    slog(f"[rate-limit] session={name} auto-resume budget "
                         f"exhausted ({used}/{_RATE_LIMIT_BUDGET}), "
                         f"falling back to manual")
                    _push_alert("rate_limit_manual", name,
                                f"Rate-limit auto-resume budget exhausted for "
                                f"'{name}' — manual resume required")
                    continue

            scrollback = ""
            if tmux_name(name) in running_sessions:
                raw = tmux_capture(name, 100)
                if raw:
                    scrollback = _STRIP_ANSI.sub("", raw)
            skip, reason = _should_skip_rate_limit_resume(scrollback)
            if skip:
                actions.pop("rate_limit_reset_at", None)
                skipped += 1
                slog(f"[rate-limit] session={name} auto-resume skipped at "
                     f"reset, {reason}")
                continue

            resume_text = _session_rate_limit_resume_text(cfg)
            ok, err = send_text(name, resume_text)
            if ok:
                actions.pop("rate_limit_reset_at", None)
                actions["rate_limit_resumes_today"] = \
                    actions.get("rate_limit_resumes_today", 0) + 1
                resumed += 1
                slog(f"[rate-limit] session={name} resumed at reset, "
                     f"resume_text={resume_text!r}")
                _posthog_emit("rate_limit_auto_resumed", {
                    "session": name,
                    "resume_text": resume_text,
                }, distinct_id=name)
            else:
                # Don't clear reset_at — next tick will retry. Send can fail
                # transiently if tmux is briefly unavailable.
                slog(f"[rate-limit] session={name} resume send failed: {err}")
        except Exception as e:
            slog(f"[rate-limit] session={name} resume error: {e}")

    total = resumed + skipped + budget_exhausted
    if total > 1:
        slog(f"[rate-limit] fleet resume: {resumed} sessions steered, "
             f"{skipped} skipped (user intervened), "
             f"{budget_exhausted} budget-exhausted")
        _posthog_emit("rate_limit_fleet_event", {
            "kind": "resume",
            "resumed": resumed,
            "skipped": skipped,
            "budget_exhausted": budget_exhausted,
        })


def _rate_limit_loop():
    """Single rate-limit watchdog tick: detect prompts, handle reset."""
    try:
        _rate_limit_auto_respond()
    except Exception:
        pass
    try:
        _check_rate_limit_drift()
    except Exception:
        pass
    try:
        _rate_limit_auto_resume()
    except Exception:
        pass


_EVENTS_RETENTION_DAYS = 30
_events_last_sweep = [0.0]

def _emit_event(session: str, etype: str, data: dict | None = None,
                idem: str | None = None, source: str = "") -> None:
    """Append one observable event to the session_events log (issue #48).
    Append-only, never raises, idempotent when `idem` is set (INSERT OR IGNORE
    on the unique key — a client retry or server-restart replay can't
    double-record an externally visible action). Records observable state
    transitions and action receipts ONLY — never model reasoning."""
    try:
        db = get_db()
        db.execute(
            "INSERT OR IGNORE INTO session_events (ts, session, type, data, idem, source) "
            "VALUES (?,?,?,?,?,?)",
            (time.time(), session or "", etype,
             json.dumps(data, ensure_ascii=False) if data else None, idem, source))
        db.commit()
        now = time.time()
        if now - _events_last_sweep[0] > 3600:   # hourly retention sweep
            _events_last_sweep[0] = now
            db.execute("DELETE FROM session_events WHERE ts < ?",
                       (now - _EVENTS_RETENTION_DAYS * 86400,))
            db.commit()
    except Exception as e:
        try: slog(f"[events] emit failed ({etype}): {e}")
        except Exception: pass


def _push_alert(alert_type: str, session: str, message: str):
    """Enqueue an alert to be streamed to all SSE clients, and fan it out to
    any registered Web Push subscriptions so it reaches phones even when the
    app/tab is closed."""
    global _sse_alerts
    with _sse_alert_lock:
        _sse_alerts.append({"type": alert_type, "session": session, "message": message, "ts": int(time.time())})
        if len(_sse_alerts) > 50:
            _sse_alerts = _sse_alerts[-50:]
    try:
        # iOS notification format (no emojis): title = session, body = "<type>\n<description>"
        _web_push_broadcast(session or "amux",
                            _ALERT_TYPE_LABELS.get(alert_type, alert_type) + "\n" + message,
                            session=session, tag=alert_type)
    except Exception:
        pass


# ── Web Push (RFC 8030/8291/8292) — background notifications to phones ────────
# Implemented with stdlib + `cryptography` only (no pywebpush dependency), so it
# stays inside amux's single-file model. Delivers to the browser push service
# (Apple/Mozilla/Google) which forwards to the device even when the PWA is shut.
# Human-readable type label shown on the notification's first body line.
_ALERT_TYPE_LABELS = {
    "scheduler": "schedule", "auto_restart": "auto-restart", "auto_continue": "auto-continue",
    "auto_compact": "compact", "rate_limit_manual": "rate limit", "task_pickup": "task",
    "steering_delivered": "steering", "uncommitted": "uncommitted", "thinking_reset": "thinking reset",
    "urgent": "URGENT", "git_orphan": "git rebase orphaned",
    "stale_cli": "stale amux CLI on PATH",
    "selector_block": "selector blocking coordination",
    "session_gated": "session stopped at a model gate",
}
# A session parked at a human-gated selector can't receive inter-session
# messages — they queue until it resolves. Past this many seconds, surface the
# block to the owner so the held coordination isn't silently stuck (AMUX-1882:
# an Ethan-gated selector froze mvs-infra's READY GO to backend for ~2.5h).
_SELECTOR_BLOCK_ALERT_SECS = 600


def _waiting_since_from_events(name: str, now: float) -> float:
    """When the session's CURRENT waiting episode began, per the durable log.

    Falls back to `now` unless the newest recorded status transition is
    session.waiting — i.e. nothing has moved the session since. Without this the
    stall clock lives only in memory and resets on every server reload, so a
    long-wedged session reads as freshly waiting and never crosses the alert
    threshold (this server execv-reloads on every save).
    """
    try:
        db = get_db()
        # Last time the session actually MOVED. Anything after this is one
        # unbroken waiting episode.
        _mv = db.execute(
            "SELECT MAX(ts) AS ts FROM session_events WHERE session=? AND type IN "
            "('session.working','session.idle','session.started')", (name,)).fetchone()
        last_move = float((_mv["ts"] if _mv else 0) or 0)
        # EARLIEST waiting since then — not the latest. A server reload clears
        # _session_prev_status and the send path re-seeds it to "active", so a
        # session that never moved can log a second, spurious session.waiting;
        # taking the newest row would credit it with a fresh clock and hide a
        # long wedge (gtm-media-assets logged one at 02:34 while waiting since
        # 02:11).
        _w = db.execute(
            "SELECT MIN(ts) AS ts FROM session_events WHERE session=? AND "
            "type='session.waiting' AND ts > ?", (name, last_move)).fetchone()
        ts = float((_w["ts"] if _w else 0) or 0)
    except Exception:
        return now
    # Guard against a clock-skewed or absurdly old row seeding a bogus age.
    return ts if 0 < ts <= now else now


def _env_set(key: str, value: str):
    """Upsert KEY=value in ~/.amux/server.env and apply it live to os.environ."""
    lines = _server_env_file.read_text().splitlines() if _server_env_file.exists() else []
    found = False
    for i, l in enumerate(lines):
        if l.startswith(key + "=") or l.startswith(key + " ="):
            lines[i] = f"{key}={value}"; found = True; break
    if not found:
        lines.append(f"{key}={value}")
    _server_env_file.parent.mkdir(parents=True, exist_ok=True)
    _server_env_file.write_text("\n".join(lines) + "\n")
    if value:
        os.environ[key] = value
    else:
        os.environ.pop(key, None)


def _send_sms(phone: str, text: str):
    """Best-effort SMS to the owner. Twilio if TWILIO_* configured, else macOS
    Messages (timeout-guarded so a permission/TCC wall can't hang the server).
    Returns (ok, detail)."""
    if not phone:
        return False, "no phone configured"
    sid = os.environ.get("TWILIO_ACCOUNT_SID", ""); tok = os.environ.get("TWILIO_AUTH_TOKEN", "")
    frm = os.environ.get("TWILIO_FROM", "")
    if sid and tok and frm:
        try:
            import urllib.request, urllib.parse
            data = urllib.parse.urlencode({"From": frm, "To": phone, "Body": text}).encode()
            req = urllib.request.Request(
                f"https://api.twilio.com/2010-04-01/Accounts/{sid}/Messages.json",
                data=data, method="POST",
                headers={"Authorization": "Basic " + base64.b64encode(f"{sid}:{tok}".encode()).decode()})
            urllib.request.urlopen(req, timeout=15).read()
            return True, "twilio"
        except Exception as e:
            return False, f"twilio error: {str(e)[:120]}"
    # macOS Messages fallback — guarded by a hard timeout (Messages scripting can
    # block on an Automation-permission prompt).
    # `buddy ph of s` is the form that actually delivers; `participant ph of svc`
    # compiles but hangs until the osascript timeout fires.
    try:
        r = subprocess.run([
            "osascript",
            "-e", "on run {msg, ph}",
            "-e", 'tell application "Messages"',
            "-e", "set s to first service whose service type = iMessage",
            "-e", "set b to buddy ph of s",
            "-e", "send msg to b",
            "-e", "end tell",
            "-e", "end run",
            "--", text, phone,
        ], capture_output=True, text=True, timeout=12)
        if r.returncode == 0:
            return True, "imessage"
        return False, f"imessage error: {(r.stderr or '').strip()[:100]}"
    except subprocess.TimeoutExpired:
        return False, "imessage timed out — grant Automation permission for Messages, or set TWILIO_* creds"
    except Exception as e:
        return False, f"imessage error: {str(e)[:100]}"


# ── Internal SMS bridge (AMUX-186x, smart-business-card) ─────────────────────
# Programmatic outbound SMS for the card funnel. This is the ONE outward-effect
# amux uniquely owns; everything else lives in the public sidecar. Hard rules:
#  • NOT in _PUBLIC_PREFIXES — the cloud gateway 401s it for the internet.
#  • Caller must be loopback OR present the shared AMUX_INTERNAL_TOKEN (so the
#    cloud-VM sidecar on the private net can reach it, nothing else can).
#  • Inert until TWILIO_* is configured — refuses to fall back to the owner's
#    personal iMessage for stranger-facing sends.
#  • Daily total cap + per-number cap + short dedupe window — a form-spam loop
#    can't run up the Twilio bill or text a victim repeatedly.
_sms_bridge_lock = threading.Lock()
_sms_bridge_log: dict = {"day": "", "total": 0, "per_num": {}, "recent": {}}


def _sms_bridge_gate(to: str, text: str) -> tuple[bool, str]:
    """Rate/dedupe gate for /api/sms. Returns (ok, reason)."""
    import datetime as _dt
    day = _dt.datetime.utcnow().strftime("%Y-%m-%d")
    daily_cap = int(os.environ.get("AMUX_SMS_DAILY_CAP", "50") or "50")
    per_num_cap = int(os.environ.get("AMUX_SMS_PER_NUMBER_CAP", "5") or "5")
    now = time.time()
    with _sms_bridge_lock:
        if _sms_bridge_log["day"] != day:
            _sms_bridge_log.update({"day": day, "total": 0, "per_num": {}, "recent": {}})
        # dedupe: identical (to,text) within 10 min
        key = to + "|" + text
        if now - _sms_bridge_log["recent"].get(key, 0) < 600:
            return False, "duplicate (same message to same number within 10 min)"
        if _sms_bridge_log["total"] >= daily_cap:
            return False, f"daily SMS cap reached ({daily_cap})"
        if _sms_bridge_log["per_num"].get(to, 0) >= per_num_cap:
            return False, f"per-number cap reached ({per_num_cap}/day for {to})"
        # reserve
        _sms_bridge_log["total"] += 1
        _sms_bridge_log["per_num"][to] = _sms_bridge_log["per_num"].get(to, 0) + 1
        _sms_bridge_log["recent"][key] = now
    return True, ""


_urgent_alert_last = {}  # message-hash → ts, for a light flood guard

# ── Owner-alert STORM guard (AMUX / MF-427) ──────────────────────────────────
# MEASURED 2026-08-02/03: 38 identical owner pages, message '--help', one every
# ~302s for 3h06m, every one a real push AND a real iMessage, deduped=false on
# all 38. Nothing noticed.
#
# The 60s dedupe above is the wrong SHAPE for that failure, not merely too
# short: a storm on a 302s cadence steps cleanly between 60s windows, so each
# page is individually distinct and legitimate. A guard whose window is shorter
# than the interval it must suppress suppresses nothing.
#
# Why this matters more than noise: the owner alert is the fire alarm, and its
# entire value is that a page means act now. 38 empty pages in one night trains
# the owner to ignore it, which destroys the signal exactly as thoroughly as a
# dead alert path — the failure the canary existed to prevent, reached from the
# other side.
#
# THE NEGATIVE CONTROL IS PART OF THE DESIGN, not an afterthought: the key
# includes the message and the claimed session, so 38 DISTINCT genuine alerts
# have 38 distinct keys, accumulate nothing, and all deliver. Collapsing real
# incidents would be the remediation-riskier-than-the-defect version of this.
_urgent_alert_hist: dict = {}   # key → [send timestamps within the window]
_urgent_alert_mute: dict = {}   # key → mute expiry ts
URGENT_STORM_THRESHOLD = 2      # identical sends in-window before collapsing
URGENT_STORM_WINDOW = 1800.0    # 30m: comfortably wider than any plausible cadence
URGENT_STORM_MUTE = 1800.0      # sliding — each suppressed attempt extends it


def urgent_alert_decision(key, now, hist, mute_until, *, dedupe_last=None):
    """Pure decision for one alert attempt. No I/O, so the 38-row storm can be
    replayed exactly.

    Returns (action, new_hist, new_mute_until) where action is one of:
      'send'         deliver normally
      'dedupe'       inside the existing 60s repeat window
      'storm_notice' threshold crossed: deliver ONE 'storming' page, then mute
      'muted'        storm already declared and still active; deliver nothing

    The mute SLIDES: every suppressed attempt pushes the expiry out, so a storm
    that keeps firing stays muted instead of resuming every window. A storm ends
    by stopping, which is the only evidence that it ended.
    """
    # `dedupe_last` falsy means NEVER SENT. The old call site used .get(key, 0),
    # which conflates "never" with "sent at epoch 0" — harmless against a real
    # time.time() and wrong for anything that supplies its own clock, including
    # the replay of the incident this guard exists for.
    if dedupe_last and now - dedupe_last < 60:
        return "dedupe", hist, mute_until

    if mute_until and now < mute_until:
        # Still storming. Extend rather than count down toward a resume.
        return "muted", hist, now + URGENT_STORM_MUTE

    recent = [t for t in (hist or []) if now - t < URGENT_STORM_WINDOW]
    recent.append(now)
    if len(recent) >= URGENT_STORM_THRESHOLD:
        return "storm_notice", recent, now + URGENT_STORM_MUTE
    return "send", recent, 0.0
# ─────────────────────────────────────────────────────────────────────────────


def _record_owner_alert(origin: str, claimed: str, message: str, reason: str,
                        channels: dict, deduped: bool) -> None:
    """Append an owner-alert to the durable, provenance-stamped ledger (AMUX-1795),
    so a safety-critical action is first-hand verifiable — who ACTUALLY fired it
    (server-verified origin), not who a conversation believed did. Best-effort:
    never let a ledger-write failure block the alarm itself."""
    try:
        db = get_db()
        db.execute(
            "INSERT INTO owner_alerts (ts, origin, claimed, message, reason, channels, deduped) "
            "VALUES (?,?,?,?,?,?,?)",
            (int(time.time()), origin or "", claimed or "", message or "", reason or "",
             json.dumps(channels or {}), 1 if deduped else 0))
        db.commit()
    except Exception as e:
        slog(f"[urgent-alert] LEDGER WRITE FAILED: {e}")


def _send_urgent_alert(message: str, session: str = "", reason: str = "", origin: str = ""):
    """Owner URGENT alert — fan out to enabled channels (in-app push + SMS).
    Meant to be used *sparingly*; a soft 60s dedupe blocks accidental repeats.

    `session` is the CLAIMED origin (self-reported by the caller/body). `origin` is
    the SERVER-VERIFIED sender (X-Amux-Session, from the tmux identity). Every
    attempt is recorded to the owner_alerts ledger with BOTH, so this
    safety-critical action is first-hand verifiable and a claimed≠verified mismatch
    (the AMUX-1730 entanglement signature) is caught rather than believed."""
    # Junk-message rejection (the 38-SMS night, 2026-08-03): '--help' fired 38
    # real iMessages because a probe's flag became the MESSAGE. Flags and
    # empty strings are never legitimate pages; refuse loudly instead of
    # texting the owner's phone.
    _m = (message or "").strip()
    if not _m or _m.startswith("-") or _m.lower() in ("help", "usage", "test"):
        slog(f"[alert] REFUSED junk owner-alert message {_m!r} from "
             f"{origin or session or 'unknown'} — flags/empty are never pages")
        return {"error": f"refused: {_m!r} is not an alert message", "sent": False}

    msg = (message or "").strip()
    if not msg:
        return {"ok": False, "error": "empty message"}
    if reason:
        msg = f"{msg}\n({reason})"
    # Provenance red flag: the caller claims a DIFFERENT session than the one the
    # server actually verified. Surface it loudly (this is the exact shape of the
    # AMUX-1730 near-miss: a belief that some other session did the critical thing).
    _mismatch = bool(origin and session and origin != session)
    if _mismatch:
        slog(f"[urgent-alert] PROVENANCE MISMATCH: verified origin={origin!r} but claimed session={session!r} — recording both")
    key = _hashlib.sha256((session + "|" + msg).encode()).hexdigest()[:16]
    now = time.time()
    action, _hist, _mute = urgent_alert_decision(
        key, now, _urgent_alert_hist.get(key), _urgent_alert_mute.get(key, 0.0),
        dedupe_last=_urgent_alert_last.get(key),
    )
    _urgent_alert_hist[key] = _hist
    _urgent_alert_mute[key] = _mute

    if action == "dedupe":
        _record_owner_alert(origin, session, msg, reason, {}, deduped=True)
        return {"ok": True, "deduped": True, "channels": {}, "message": msg,
                "origin": origin, "claimed": session, "provenance_mismatch": _mismatch}

    if action == "muted":
        # Recorded, deliberately not delivered. The ledger still shows every
        # attempt, so a storm remains fully visible at GET /api/alert/owner —
        # the suppression must not also hide the evidence.
        _record_owner_alert(origin, session, msg, reason, {}, deduped=True)
        slog(f"[urgent-alert] STORM-MUTED key={key} origin={origin!r} msg={message[:80]!r}")
        return {"ok": True, "deduped": True, "storm_muted": True, "channels": {},
                "message": msg, "origin": origin, "claimed": session,
                "provenance_mismatch": _mismatch}

    if action == "storm_notice":
        # One page saying it is storming, then silence. This page is the LAST
        # one for this message until the storm stops, so it has to carry where
        # to look rather than just repeating the alert.
        n = len(_hist)
        msg = (f"STORM: this alert has fired {n}x and is now MUTED for "
               f"{int(URGENT_STORM_MUTE // 60)}m. Original: {msg}\n"
               f"Full history: GET /api/alert/owner")
    _urgent_alert_last[key] = now
    channels = {}
    if os.environ.get("AMUX_URGENT_PUSH", "1") != "0":
        try:
            _push_alert("urgent", session or "amux", msg)
            channels["push"] = "sent"
        except Exception as e:
            channels["push"] = f"error: {str(e)[:80]}"
    phone = os.environ.get("AMUX_OWNER_PHONE", "")
    if os.environ.get("AMUX_URGENT_SMS", "1") != "0" and phone:
        # Stamp the originating session into the SMS/iMessage so the owner has a
        # reference for WHICH session raised the alarm (the push already carries
        # it as the notification title; the SMS previously dropped it).
        _sms_prefix = f"amux URGENT [{session}]: " if session else "amux URGENT: "
        ok, detail = _send_sms(phone, _sms_prefix + msg.replace("\n", " — "))
        channels["sms"] = detail if ok else ("failed: " + detail)
    _record_owner_alert(origin, session, msg, reason, channels, deduped=False)
    slog(f"[urgent-alert] origin={origin!r} claimed={session!r} reason={reason!r} channels={channels} msg={message[:120]!r}")
    return {"ok": True, "channels": channels, "message": msg,
            "origin": origin, "claimed": session, "provenance_mismatch": _mismatch}
_VAPID_CACHE = None
_VAPID_PATH = CC_HOME / "vapid_private.pem"
_PUSH_SUBS_PRESENT = None  # None=unknown, False=confirmed empty (skip), True=have subs


_PUSH_SSL_CTX = None


def _push_ssl_context():
    """SSL context for outbound calls to push services. macOS' bundled Python
    doesn't read the system keychain, so plain urlopen fails Apple's cert with
    'unable to get local issuer certificate' — back it with certifi's CA bundle."""
    global _PUSH_SSL_CTX
    if _PUSH_SSL_CTX is not None:
        return _PUSH_SSL_CTX
    try:
        import certifi
        _PUSH_SSL_CTX = ssl.create_default_context(cafile=certifi.where())
    except Exception:
        _PUSH_SSL_CTX = ssl.create_default_context()
    return _PUSH_SSL_CTX


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(s: str) -> bytes:
    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))


def _vapid_keys():
    """Return (private_key_obj, public_key_b64url). Generated once and persisted."""
    global _VAPID_CACHE
    if _VAPID_CACHE:
        return _VAPID_CACHE
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives import serialization
    if _VAPID_PATH.exists():
        pk = serialization.load_pem_private_key(_VAPID_PATH.read_bytes(), password=None)
    else:
        pk = ec.generate_private_key(ec.SECP256R1())
        _VAPID_PATH.write_bytes(pk.private_bytes(
            serialization.Encoding.PEM,
            serialization.PrivateFormat.PKCS8,
            serialization.NoEncryption()))
        try:
            _VAPID_PATH.chmod(0o600)
        except Exception:
            pass
    pub = pk.public_key().public_bytes(
        serialization.Encoding.X962,
        serialization.PublicFormat.UncompressedPoint)
    _VAPID_CACHE = (pk, _b64url(pub))
    return _VAPID_CACHE


def _vapid_jwt(audience: str) -> str:
    """Signed ES256 JWT for the VAPID Authorization header."""
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
    pk, _ = _vapid_keys()
    sub = os.environ.get("AMUX_VAPID_SUBJECT", "mailto:amux@localhost")
    header = _b64url(json.dumps({"alg": "ES256", "typ": "JWT"}, separators=(",", ":")).encode())
    claims = _b64url(json.dumps(
        {"aud": audience, "exp": int(time.time()) + 12 * 3600, "sub": sub},
        separators=(",", ":")).encode())
    signing_input = (header + "." + claims).encode("ascii")
    der = pk.sign(signing_input, ec.ECDSA(hashes.SHA256()))
    r, s = decode_dss_signature(der)
    raw = r.to_bytes(32, "big") + s.to_bytes(32, "big")
    return header + "." + claims + "." + _b64url(raw)


def _encrypt_web_push(p256dh_b64: str, auth_b64: str, payload: bytes) -> bytes:
    """Encrypt payload with aes128gcm content coding (RFC 8291). Returns the
    full message body (salt+rs+keyid header followed by the GCM ciphertext)."""
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives import serialization, hashes
    from cryptography.hazmat.primitives.kdf.hkdf import HKDF
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM

    ua_public_bytes = _b64url_decode(p256dh_b64)
    auth_secret = _b64url_decode(auth_b64)
    ua_public = ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), ua_public_bytes)

    as_private = ec.generate_private_key(ec.SECP256R1())
    as_public_bytes = as_private.public_key().public_bytes(
        serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
    shared = as_private.exchange(ec.ECDH(), ua_public)

    # PRK / IKM per RFC 8291 §3.4
    key_info = b"WebPush: info\x00" + ua_public_bytes + as_public_bytes
    ikm = HKDF(algorithm=hashes.SHA256(), length=32, salt=auth_secret, info=key_info).derive(shared)

    salt = os.urandom(16)
    cek = HKDF(algorithm=hashes.SHA256(), length=16, salt=salt,
               info=b"Content-Encoding: aes128gcm\x00").derive(ikm)
    nonce = HKDF(algorithm=hashes.SHA256(), length=12, salt=salt,
                 info=b"Content-Encoding: nonce\x00").derive(ikm)

    # Single record: plaintext + 0x02 delimiter (last-record marker), then GCM.
    ciphertext = AESGCM(cek).encrypt(nonce, payload + b"\x02", None)
    rs = (4096).to_bytes(4, "big")
    header = salt + rs + bytes([len(as_public_bytes)]) + as_public_bytes
    return header + ciphertext


def _send_one_push(endpoint: str, p256dh_b64: str, auth_b64: str, payload: bytes):
    """Send one encrypted push. Returns (status, detail). status is the HTTP code
    (0 on transport error); detail carries the push service's error body so we can
    surface why Apple/Mozilla/Google rejected it."""
    import urllib.request as _ur
    from urllib.parse import urlparse as _urlparse
    try:
        body = _encrypt_web_push(p256dh_b64, auth_b64, payload)
        parts = _urlparse(endpoint)
        aud = f"{parts.scheme}://{parts.netloc}"
        _, vapid_pub = _vapid_keys()
        req = _ur.Request(endpoint, data=body, method="POST", headers={
            "TTL": "2419200",
            "Urgency": "high",            # wake the device promptly (iOS)
            "Content-Encoding": "aes128gcm",
            "Content-Type": "application/octet-stream",
            "Content-Length": str(len(body)),
            "Authorization": f"vapid t={_vapid_jwt(aud)},k={vapid_pub}",
        })
    except Exception as e:
        slog(f"[webpush] build error: {e}")
        return 0, f"build error: {e}"
    try:
        with _ur.urlopen(req, timeout=10, context=_push_ssl_context()) as resp:
            return resp.status, ""
    except _ur.HTTPError as e:
        detail = ""
        try:
            detail = e.read().decode("utf-8", "replace")[:300]
        except Exception:
            pass
        slog(f"[webpush] {endpoint[:50]}… -> {e.code} {detail}")
        return e.code, detail
    except Exception as e:
        slog(f"[webpush] transport error: {e}")
        return 0, f"transport error: {e}"


def _web_push_send_all(title: str, body: str, session: str = "", tag: str = "amux", url: str = "/"):
    """Send synchronously to every subscription. Returns a list of per-endpoint
    {host, status, detail} results. Prunes dead (404/410) subscriptions."""
    global _PUSH_SUBS_PRESENT
    from urllib.parse import urlparse as _urlparse
    payload = json.dumps({"title": title, "body": body, "session": session, "tag": tag, "url": url}).encode()
    try:
        db = get_db()
        rows = db.execute("SELECT endpoint, p256dh, auth FROM push_subscriptions").fetchall()
    except Exception as e:
        return [{"host": "", "status": 0, "detail": f"db error: {e}"}]
    _PUSH_SUBS_PRESENT = len(rows) > 0
    results = []
    for r in rows:
        status, detail = _send_one_push(r["endpoint"], r["p256dh"], r["auth"], payload)
        results.append({"host": _urlparse(r["endpoint"]).netloc, "status": status, "detail": detail})
        if status in (404, 410):
            try:
                db.execute("DELETE FROM push_subscriptions WHERE endpoint=?", (r["endpoint"],))
                db.commit()
                slog("[webpush] pruned expired subscription")
            except Exception:
                pass
    return results


def _web_push_broadcast(title: str, body: str, session: str = "", tag: str = "amux", url: str = "/"):
    """Fan out a notification to every registered subscription (in a background
    thread so callers never block on the network)."""
    # Fast path: if a prior broadcast confirmed there are no subscriptions, skip
    # spawning a thread for every alert. Reset to True on subscribe.
    if _PUSH_SUBS_PRESENT is False:
        return
    threading.Thread(target=lambda: _web_push_send_all(title, body, session, tag, url), daemon=True).start()

    threading.Thread(target=_run, daemon=True).start()


def _read_jsonl_tail(filepath: Path, max_bytes: int = 5_000_000) -> list:
    """Read the last max_bytes of a JSONL file and return parsed lines.

    Avoids reading entire multi-hundred-MB files into memory when only
    recent entries are needed. Skips the first (likely partial) line
    when seeking into the middle of a file.
    """
    try:
        size = filepath.stat().st_size
    except OSError:
        return []
    lines = []
    try:
        with filepath.open("rb") as fh:
            if size > max_bytes:
                fh.seek(size - max_bytes)
                fh.readline()  # discard partial first line
            for raw in fh:
                try:
                    lines.append(json.loads(raw))
                except (json.JSONDecodeError, ValueError):
                    continue
    except Exception:
        pass
    return lines


def _iter_jsonl_tail(filepath: Path, max_bytes: int = 5_000_000):
    """Iterate over parsed entries from the tail of a JSONL file.

    Unlike _read_jsonl_tail, this yields entries one at a time instead of
    accumulating them all in a list — much less memory for large files.
    """
    try:
        size = filepath.stat().st_size
    except OSError:
        return
    try:
        with filepath.open("rb") as fh:
            if size > max_bytes:
                fh.seek(size - max_bytes)
                fh.readline()  # discard partial first line
            for raw in fh:
                try:
                    yield json.loads(raw)
                except (json.JSONDecodeError, ValueError):
                    continue
    except Exception:
        pass


def _last_meaningful_user_message(work_dir: str) -> str:
    """Extract the last meaningful user message (>20 chars) from the session's JSONL history."""
    if not work_dir:
        return ""
    project_dir = CLAUDE_HOME / "projects" / _project_name(work_dir)
    if not project_dir.is_dir():
        return ""
    jsonl_files = sorted(project_dir.glob("*.jsonl"), key=lambda f: f.stat().st_mtime, reverse=True)
    if not jsonl_files:
        return ""
    last_msg = ""
    try:
        for entry in _iter_jsonl_tail(jsonl_files[0], max_bytes=2_000_000):
            try:
                msg = entry.get("message", {})
                if msg.get("role") == "user":
                    content = msg.get("content", [])
                    text = ""
                    if isinstance(content, list):
                        for block in content:
                            if isinstance(block, dict) and block.get("type") == "text":
                                text = block.get("text", "")
                    elif isinstance(content, str):
                        text = content
                    if len(text) > 20:
                        last_msg = text
            except (json.JSONDecodeError, AttributeError):
                continue
    except Exception:
        pass
    return last_msg


_STRIP_ANSI = re.compile(
    r'\x1b\[[0-9;?]*[a-zA-Z]|\x1b\]8;[^\x1b]*\x1b\\|\x1b\][^\x07]*\x07'
    r'|\x1b\][^\x1b]*\x1b\\|\x1b[()][A-Z0-9]|\x1b[\x20-\x2f]*[\x40-\x7e]'
)


def _claude_ui_visible(clean_output: str) -> bool:
    """Return True if Claude's or Codex's status bar/spinner is present in the terminal output."""
    lines = [l for l in clean_output.splitlines() if l.strip()]
    # Check last 3 lines for Claude status bar markers.
    # Guard: when Claude is killed (signal 9), its status bar text can leak
    # into the bash prompt line as garbled output (e.g. "videos$ ass permissions
    # on \u00b7 1 shell"). Require that the line does NOT start with a shell prompt.
    _shell_prompt_re = re.compile(r'^.*[$%]\s')
    for l in lines[-3:]:
        ls = l.strip().lower()
        if _shell_prompt_re.match(ls):
            continue
        if "\u23f5\u23f5" in l or "bypass permissions" in ls or "plan mode" in ls:
            return True
        if "codex" in ls and ("full-auto" in ls or "suggest" in ls or "workspace" in ls or "approval" in ls or "-a never" in ls):
            return True
    # Check last 12 lines for an active spinner (dingbat-prefixed status line
    # like "\u273b Crunched for 1m 38s"). Exclude U+276F \u276f \u2014 that's Claude's input
    # prompt; after /exit, "\u276f /exit" stays in scrollback and false-positives.
    for l in lines[-12:]:
        s = l.strip()
        if s and "\u2700" <= s[0] <= "\u27bf" and s[0] != "\u276f":
            return True
    # Codex UI patterns — checked unconditionally so long-running sessions still
    # match after the initial "codex" banner has scrolled past the capture window
    for l in lines[-12:]:
        s = l.strip()
        # "• Working (Xs • esc to interrupt)" spinner — U+2022 is below dingbats range
        if s.startswith("•") and "working" in s.lower() and "esc to interrupt" in s.lower():
            return True
        # Codex model status bar: "gpt-5.5 xhigh · ~/path"
        if "·" in s and re.search(r"gpt-\d|o[34][-m]", s):
            return True
    # Codex idle prompt: > or › (gate on "codex" in first 15 OR last 20 lines)
    has_codex = any("codex" in l.lower() for l in lines[:15] + lines[-20:])
    if has_codex:
        for l in lines[-5:]:
            ls = l.strip()
            if ls == ">" or ls.startswith("> "):
                return True
            if ls.startswith("›"):
                return True
            # Codex model status line: "gpt-X xhigh · ~/path"
            if "·" in ls and ("gpt-" in ls or "o3" in ls or "o4" in ls):
                return True
    # Gemini CLI prompt/status. Gemini's UI is also Ink-based and may use
    # ">" / "›" prompt lines, but only treat those as ready if the banner/model
    # is visible somewhere in the recent pane.
    has_gemini = any("gemini" in l.lower() for l in lines[:20] + lines[-12:])
    if has_gemini:
        for l in lines[-8:]:
            ls = l.strip().lower()
            if ls == ">" or ls.startswith("> ") or ls.startswith("›"):
                return True
            if "gemini-" in ls or "yolo" in ls or "approval" in ls:
                return True
    return False


def _at_resume_picker(clean_output: str) -> bool:
    """Return True if Claude's --resume picker is showing (interactive session selector)."""
    return bool(clean_output and
                ("Resume Session" in clean_output or "Type to Search" in clean_output or
                 "Enter to select" in clean_output or "Esc to cancel" in clean_output) and
                "⌕" in clean_output)  # ⌕ search icon in the picker


def _at_compact_resume_prompt(clean_output: str) -> bool:
    """Return True if Claude is showing the 'Resume from summary' compaction dialog.

    This appears when a session's context is large and Claude Code asks whether to
    compact before resuming. Option 1 (Resume from summary) is pre-selected.
    """
    return bool(clean_output and
                "Resume from summary" in clean_output and
                "Resume full session" in clean_output)


def _at_shell_prompt(clean_output: str) -> bool:
    """Return True if the terminal looks like a bare shell prompt (no Claude UI)."""
    if _claude_ui_visible(clean_output):
        return False
    lines = [l for l in clean_output.splitlines() if l.strip()]
    for l in lines[-5:]:
        ls = l.strip()
        # Bash/zsh prompt: ends with $ or % (not Claude's ❯ prompt)
        if re.search(r'[$%]\s*$', ls) and "\u276f" not in ls:
            return True
        # After Killed/signal 9, status bar text leaks after the prompt char:
        # e.g. "mixpeek$ ss permissions on · 5 shells"
        if re.match(r'\S+[$%]\s', ls) and "\u276f" not in ls:
            return True
    return False


_snapshot_running = False

def _snapshot_all_sessions():
    """Capture scrollback for health checks on all running sessions.

    Session output is streamed to disk in real-time via tmux pipe-pane (set up
    in start_session). This loop only reads output for health-check logic:
    1. Proactive: if context < 50% remaining before auto-compact, send /compact
    2. Reactive: if thinking-block corruption error detected, restart conversation
       and replay the last meaningful user message automatically.
    3. Auto-continue: if CC_AUTO_CONTINUE=1 and session is stuck waiting for user
       input for 2+ consecutive snapshots (~60s), auto-respond to unblock it.
    4. Auto-restart: if CC_AUTO_CONTINUE=1 and Claude has exited to a shell prompt,
       restart it automatically (handles context-limit exits mid-task).
    """
    global _snapshot_running
    if _snapshot_running:
        return
    _snapshot_running = True
    try:
        _snapshot_all_sessions_inner()
    finally:
        _snapshot_running = False

def _steer_guard_stale(name: str, guard: str):
    """Is a guarded nudge still TRUE at delivery time? Returns (stale, why).

    A nudge waits in the queue until the session's next turn boundary — that is
    the correct grain (see the no-global-pub-sub decision in ethos.md) — but it
    means every nudge asserting a fact must re-check that fact before speaking
    it. Unknown guards are never stale, so an unguarded nudge is unaffected."""
    if guard == "commit":
        wd = _session_work_dir(name)
        return (bool(wd) and not _session_dirty_files(name, wd)), "tree clean at delivery"
    if guard.startswith("dep:"):
        cid = guard[4:]
        it = _item_by_id(cid)
        if not it or it.get("deleted"):
            return True, f"{cid} no longer exists"
        if it.get("archived"):
            return True, f"{cid} archived before delivery"
        if _status_canon(it.get("status")) not in ("todo", "backlog"):
            return True, f"{cid} is {it.get('status')} before delivery"
        if _deps_blocking(it):
            return True, f"{cid} blocked again before delivery"
        return False, ""
    if guard.startswith("verify:"):
        cid = guard[7:]
        it = _item_by_id(cid)
        if not it or it.get("deleted"):
            return True, f"{cid} no longer exists"
        if _status_canon(it.get("status")) != "done":
            return True, f"{cid} left done before delivery ({it.get('status')})"
        return False, ""
    if guard.startswith("sched:"):
        # Drop a failure nudge if the schedule has since run clean — the same
        # delivery-time revalidation the dep:/watch: guards use.
        sid = guard[6:]
        try:
            db = get_db()
            # DELETED or DISABLED schedules first. I wrote this guard checking
            # only "has it since run clean" and then proved the gap with my own
            # fixture: I deleted the test schedule, and its failure nudge still
            # delivered — announcing a failure of something that no longer
            # exists. The dep: guard already checks non-existence; I applied the
            # lesson to the operand that burned me and not to the new one, which
            # is the exact habit-transfer failure in ethos rule 7.
            srow = db.execute("SELECT deleted, enabled FROM schedules WHERE id=?", (sid,)).fetchone()
            if not srow or srow["deleted"]:
                return True, f"{sid} no longer exists"
            if not srow["enabled"]:
                return True, f"{sid} disabled before delivery"
            row = db.execute(
                "SELECT status FROM schedule_runs WHERE schedule_id=? ORDER BY ran_at DESC LIMIT 1",
                (sid,)).fetchone()
            if row and row["status"] == "ok":
                return True, f"{sid} has since run clean"
        except Exception:
            pass
        return False, ""
    if guard.startswith("watch:"):
        # Same lesson as dep: — a watch closed or stood down while its review
        # nudge waited must not be announced as still armed.
        cid = guard[6:]
        it = _item_by_id(cid)
        if not it or it.get("deleted"):
            return True, f"{cid} no longer exists"
        if it.get("archived"):
            return True, f"{cid} archived before delivery"
        if _status_canon(it.get("status")) not in ("todo", "backlog", "doing"):
            return True, f"{cid} is {it.get('status')} before delivery"
        return False, ""
    return False, ""


def _steer_enqueue(name: str, text: str, guard: str = "") -> str:
    """Append a message to a session's durable steering queue (memory + DB).
    Delivered (batched) at the next turn boundary by _steer_try_deliver.

    Dedup-on-enqueue: an identical text already waiting is REPLACED, not
    stacked — observed live on mvs-infra: recurring scheduled prompts piled up
    behind a busy session (the same PULSE health-loop queued twice runs the
    same loop back-to-back for nothing), and sender retries queued literal
    duplicates ("YES to the census" ×2).

    `guard`: optional re-validation tag (e.g. "commit"). _steer_try_deliver
    rechecks the condition at DELIVERY and drops the entry if it went stale —
    a commit-guard nudge whose tree got committed while the nudge waited
    (AMUX-1737). In-memory only; a restart-reloaded entry delivers without it."""
    msg_id = f"steer-{int(time.time()*1000)}"
    entry = {"id": msg_id, "text": text, "queued_at": time.time(), "guard": guard}
    with _steering_lock:
        q = _steering_queue.setdefault(name, [])
        # One nudge max per guard type: a fresh commit-nudge REPLACES a queued
        # one (file lists differ, so text-dedup alone never matched) — guard
        # messages were stacking up and saturating queues (2026-07-17).
        stale = [m for m in q if not m.get("_inflight")
                 and (m["text"] == text or (guard and m.get("guard") == guard))]
        if stale:
            _steering_queue[name] = [m for m in q if m not in stale]
        _steering_queue[name].append(entry)
    if stale:
        try:
            db = get_db()
            for m in stale:
                db.execute("DELETE FROM steering_queue WHERE id=?", (m["id"],))
            db.commit()
        except Exception:
            pass
    try:
        db = get_db()
        db.execute(
            "INSERT OR REPLACE INTO steering_queue(id, session, text, queued_at, guard) VALUES(?,?,?,?,?)",
            (msg_id, name, text, entry["queued_at"], guard or None),
        )
        db.commit()
    except Exception:
        pass
    _emit_event(name, "message.queued", {"chars": len(text), "preview": text[:120], "guard": guard or None},
                idem="q:" + msg_id, source="steering")
    return msg_id


_STEER_HISTORY_KEEP = 100  # per-session cap on delivered-steer log rows


def _steer_record_history(name: str, text: str, queued_at=None, msg_id: str = "") -> None:
    """Log a steering message that was actually delivered to a session, so the
    steering tab can show what was sent (queue rows are deleted on delivery).
    Best-effort: never let history bookkeeping break a delivery. Pruned to the
    most recent _STEER_HISTORY_KEEP rows per session."""
    try:
        hid = msg_id or f"steerh-{int(time.time()*1000)}"
        db = get_db()
        db.execute(
            "INSERT OR REPLACE INTO steering_history(id, session, text, queued_at, delivered_at) "
            "VALUES(?,?,?,?,?)",
            (hid, name, text, queued_at, time.time()),
        )
        db.execute(
            "DELETE FROM steering_history WHERE session=? AND id NOT IN "
            "(SELECT id FROM steering_history WHERE session=? ORDER BY delivered_at DESC LIMIT ?)",
            (name, name, _STEER_HISTORY_KEEP),
        )
        db.commit()
    except Exception:
        pass


_CMD_HIST_KEEP = 400  # per-session cap on the Messages history


def _cmd_hist_record(session: str, text: str, ctype: str = "user", origin: str = "") -> None:
    """Record a command/message sent to a session in the Messages history, tagged
    by ORIGIN so the peek can distinguish who sent it:
      user     — a human typed it in the dashboard
      session  — another amux session sent it (origin = sender name)
      schedule — a scheduled command fired it (origin = schedule title)
      system   — amux itself (commit-guard nudge, auto-continue) (origin = what)
    Best-effort; pruned per-session so the table stays bounded."""
    try:
        if not (session and text):
            return
        db = get_db()
        db.execute("INSERT INTO cmd_history (text, type, session, ts, origin) VALUES (?,?,?,?,?)",
                   (text, ctype, session, int(time.time() * 1000), (origin or "")[:80]))
        db.execute("DELETE FROM cmd_history WHERE session=? AND id NOT IN "
                   "(SELECT id FROM cmd_history WHERE session=? ORDER BY ts DESC LIMIT ?)",
                   (session, session, _CMD_HIST_KEEP))
        db.commit()
        # Mirror into the unified ledger. cmd_history is per-session and pruned
        # aggressively for the Messages tab; the ledger is fleet-wide and keeps
        # the cross-session picture, which is the one you need when asking "what
        # touched this lane, and who told it to".
        _ilog("inter_session" if ctype == "session" else "session",
              ctype, actor=(origin or ctype), target=session,
              detail={"text": text, "origin": origin})
    except Exception:
        pass


# A single tmux frame that momentarily reads idle is not proof a session
# finished — captures tear. Before delivering steering we require the session to
# read idle *continuously* for this settle window; any active/unknown frame in
# between resets the timer. The PRIMARY "still working" gate is the animated
# spinner (_detect_claude_status → 'active' throughout a turn), so this window
# only needs to bridge the rare torn frame: with the 4s fast tick it means ~2
# consecutive idle ticks. Kept short (4s) so a queued message lands promptly once
# the session is actually done — a 9s value read as "idle but not picking up"
# (2026-07-20). With the 2s fast tick this is ~2 consecutive idle ticks (~2-4s to
# deliver). Tunable via env (raise it for a more conservative hold).
_STEER_SETTLE_SECS = float(os.environ.get("AMUX_STEER_SETTLE_SECS", "2"))
_steer_settle_since: dict = {}   # name -> monotonic ts of first deliverable observation

# ── Undeliverable-nudge sweep (AC-176) ───────────────────────────────────────
# Guard revalidation (above) only runs inside _steer_try_deliver, which is only
# reached for a session the poller is WATCHING. A nudge addressed to a lane that
# never comes back is therefore never delivered AND never dropped — nothing ever
# looks at it again. Measured 2026-08-03: 9 rows, oldest 21 days, for
# __steertest2__, steertest2, limitprobe (env file deleted) and lucihub,
# ts-troubleshooting (env present, simply never idle again).
#
# This is not only untidiness. It makes "the queue row is gone" an unreliable
# success signal, and something was already resting on it: AMUX-2275's stated
# closing condition was exactly that. Its specimen only cleared because the amux
# lane happened to go idle during review — had it stalled, the card could never
# have closed by its own criterion, through no fault of the code under test.
#
# TWO causes, kept as SEPARATE reasons on purpose. message.dropped is already the
# discriminator that made AMUX-2275 verifiable (709 "tree clean at delivery" vs 1
# "AMUX-2274 is discarded before delivery"); an expiry sweep that dropped rows
# without saying which cause applied would reintroduce the blindness that fix
# removed. Emitted under source="steer-expiry", never "steer-guard", so an
# expiry can never be mistaken for a guard firing.
_STEER_MAX_AGE_SECS = float(os.environ.get("AMUX_STEER_MAX_AGE_SECS", str(14 * 86400)))
_STEER_SWEEP_EVERY = float(os.environ.get("AMUX_STEER_SWEEP_EVERY", "3600"))

def _steer_sweep_undeliverable() -> None:
    """Drop queued nudges that can never be delivered. Returns nothing; audits all.

    Driven off the DB rather than `_steering_queue`, deliberately: the in-memory
    map is rebuilt at startup and a dead lane's rows may exist in the table with
    no live entry, which is precisely the population this sweep exists to find.
    """
    now = time.time()
    try:
        db = get_db()
        rows = db.execute(
            "SELECT id, session, queued_at FROM steering_queue").fetchall()
    except Exception:
        return
    by_session: dict = {}
    for r in rows:
        mid, name, qat = r["id"], r["session"], float(r["queued_at"] or now)
        # A session EXISTS iff it has an env file — the same test list_sessions()
        # uses. Deliberately not "is it running": a stopped session is expected to
        # come back and its nudge is still legitimately pending. Only a session
        # whose env file is gone can never be polled again.
        alive = (CC_SESSIONS / f"{name}.env").exists()
        age = now - qat
        if not alive:
            why = f"session {name} no longer exists"
        elif age > _STEER_MAX_AGE_SECS:
            why = f"undelivered {int(age // 86400)}d — never reached an idle turn boundary"
        else:
            continue
        by_session.setdefault(name, []).append((mid, why))
    for name, drops in by_session.items():
        ids = {mid for mid, _ in drops}
        with _steering_lock:
            q = _steering_queue.get(name)
            if q:
                # Never yank a message mid-delivery: _inflight is set under this
                # same lock by the deliverer. Rows with no in-memory entry at all
                # (the dead-lane case) stay in `ids` — they cannot be in flight.
                ids -= {m["id"] for m in q if m.get("_inflight")}
                _steering_queue[name] = [m for m in q if m["id"] not in ids]
                if not _steering_queue[name]:
                    _steering_queue.pop(name, None)
        if not ids:
            continue
        try:
            db = get_db()
            for mid in ids:
                db.execute("DELETE FROM steering_queue WHERE id=?", (mid,))
            db.commit()
        except Exception:
            # Do NOT swallow this silently — a sweep that fails to persist would
            # re-drop the same rows every hour and emit a duplicate audit event
            # each time, which reads as recurring breakage rather than one bug.
            slog(f"[steer-expiry] {name}: DB delete FAILED for {len(ids)} row(s) — will retry next sweep")
            continue
        reasons = sorted({why for mid, why in drops if mid in ids})
        slog(f"[steer-expiry] {name}: dropped {len(ids)} undeliverable nudge(s) — " + "; ".join(reasons))
        _emit_event(name, "message.dropped",
                    {"count": len(ids), "reason": "; ".join(reasons)},
                    source="steer-expiry")


def _steer_try_deliver(name: str, status: str, raw: str = "") -> None:
    """Deliver the head of a session's steering queue once it has sat at an IDLE
    turn boundary *continuously* for _STEER_SETTLE_SECS.

    The settle window is the accuracy guard: a lone torn/between-task frame that
    momentarily reads idle only starts the timer — the session must STILL be
    idle on a later confirming tick before anything is sent, and any active
    frame in the meantime resets it. Shared by the 60s snapshot loop and the 4s
    steering tick; the in-flight marker under the lock prevents the two loops
    from double-delivering the same message.

    `raw` (the tmux frame) lets us look past the main loop: a session whose main
    loop rests at the prompt while a background subagent is still working is NOT
    done, so an in-flight subagent holds steering exactly like an active frame
    (mirrors the client-facing status).

    Delivery requires a genuinely IDLE prompt — NOT 'waiting'. A 'waiting' frame
    means a live selector is up (a tool-approval "Do you want to proceed?", an
    AskUserQuestion, or a rate-limit/compact picker). Injecting a queued message
    there does NOT answer the selector — send_text's picker-closing Escape
    REJECTS the pending tool ("[Request interrupted by user] for tool use",
    gtm-engine 2026-07-15). Hold until the selector resolves (human answer or
    auto-continue) and the session returns to an empty prompt."""
    now = time.monotonic()
    deliverable = status == "idle"
    if deliverable and raw and _has_running_subagent(raw):
        deliverable = False  # main loop idle but a subagent is still running
    # NOTE: do NOT gate on "esc to interrupt" here. On the current Claude Code the
    # NORMAL idle status bar contains it ("⏵⏵ bypass permissions on … · esc to
    # interrupt · ← N agents"), so holding on that string stalls steering forever
    # for genuinely-idle sessions (regression 2026-07-20). The reliable "still
    # generating" signal is the SPINNER, which _detect_claude_status already
    # detects → status != 'idle' while the turn runs. The 6s continuous settle
    # below is what guards against a torn/between-task frame.
    # Re-validate GUARDED nudges at DELIVERY. A nudge sits in the queue until the
    # session's next turn boundary, and the world moves in between — so anything
    # asserting a fact has to re-check that fact before it is spoken.
    #   commit — enqueued idle-dirty, held while the next turn commits, then would
    #            warn against a now-clean tree (AMUX-1737, fired 4/4 that day).
    #   dep:ID — enqueued when ID's blocker closed, then would announce "pickable
    #            now" about a card since discarded, closed, archived or re-blocked.
    #            I hit this one myself: a dependency-unblock nudge for a test card
    #            arrived after I had discarded it. A nudge that tells a session to
    #            pick up a closed card spends a whole turn on a dead lead, which is
    #            worse than no nudge.
    if deliverable:
        with _steering_lock:
            _guarded = [(m["id"], m.get("guard") or "") for m in _steering_queue.get(name, [])
                        if m.get("guard") and not m.get("_inflight")]
        if _guarded:
            _drop, _reasons, _had_commit = set(), {}, False
            for _mid, _g in _guarded:
                _stale, _why = _steer_guard_stale(name, _g)
                if _stale:
                    _drop.add(_mid); _reasons[_mid] = _why
                    if _g == "commit":
                        _had_commit = True
            if _drop:
                with _steering_lock:
                    _steering_queue[name] = [m for m in _steering_queue.get(name, []) if m["id"] not in _drop]
                try:
                    _db = get_db()
                    for _mid in _drop:
                        _db.execute("DELETE FROM steering_queue WHERE id=?", (_mid,))
                    _db.commit()
                except Exception:
                    pass
                if _had_commit:
                    _commit_guard_nudged.pop(name, None)   # tree clean → re-arm the guard
                slog(f"[steer-guard] {name}: dropped {len(_drop)} stale nudge(s) — "
                     + "; ".join(sorted(set(_reasons.values()))))
                _emit_event(name, "message.dropped",
                            {"count": len(_drop), "reason": "; ".join(sorted(set(_reasons.values())))},
                            source="steer-guard")
    with _steering_lock:
        queue = _steering_queue.get(name, [])
        if not queue or not deliverable:
            # Working again (active/unknown/subagent) or nothing queued → drop
            # the timer so the next idle stretch has to settle from scratch.
            _steer_settle_since.pop(name, None)
            return
        first = _steer_settle_since.get(name)
        if first is None:
            _steer_settle_since[name] = now
            return  # start settling; a later confirming tick delivers
        if (now - first) < _STEER_SETTLE_SECS:
            return  # idle, but not for long enough yet — keep waiting
        if any(m.get("_inflight") for m in queue):
            return
        # Deliver ONE message per turn boundary, oldest first (2026-07-17). The
        # queue is a sequential task list: batching N messages into one turn made
        # the agent do them "all at once" instead of task-by-task. The original
        # reason for batching — a correction sitting queued behind the thing it
        # corrects — is covered differently now: Send (the default mode) types
        # corrections straight into the live turn; Queue is the explicit
        # do-these-in-order tool. A short trailer tells the agent more work is
        # queued so it doesn't over-scope the current turn.
        # Guard nudges (commit reminders etc.) must not spend their own turn
        # ahead of real work: when real messages are queued, every guard item
        # FOLDS into this delivery as a one-line reminder trailer (2026-07-17).
        # A guard delivers standalone only when it's all the queue holds.
        _non_guard = [m for m in queue if not m.get("guard")]
        _folded = []
        if _non_guard:
            _folded = [m for m in queue if m.get("guard") and not m.get("_inflight")]
            batch = [_non_guard[0]] + _folded
        else:
            batch = [queue[0]]
        for m in batch:
            m["_inflight"] = True
        _remaining = len(queue) - len(batch)
    combined = batch[0]["text"]
    for g in _folded:
        _first = (g["text"].splitlines() or [""])[0].strip()
        combined += f"\n\n[amux reminder] {_first} Commit at your next good stopping point."
    if _remaining > 0:
        combined += (f"\n\n[amux: {_remaining} more queued message"
                     f"{'s' if _remaining != 1 else ''} will deliver after this turn, "
                     f"oldest first — finish THIS task first]")
    ok, err = send_text(name, combined, _from_steering=True)
    if ok:
        ids = {m["id"] for m in batch}
        with _steering_lock:
            q = _steering_queue.get(name, [])
            _steering_queue[name] = [m for m in q if m["id"] not in ids]
            # Reset settle: the session is now busy handling what we just sent,
            # and any following message must settle against a fresh idle stretch.
            _steer_settle_since.pop(name, None)
        try:
            db = get_db()
            for mid in ids:
                db.execute("DELETE FROM steering_queue WHERE id=?", (mid,))
            db.commit()
        except Exception:
            pass
        for m in batch:
            _steer_record_history(name, m["text"], m.get("queued_at"), m["id"])
            _emit_event(name, "message.delivered", {"preview": m["text"][:120]},
                        idem="d:" + m["id"], source="steering")
        _push_alert("steering_delivered", name,
                    f"{len(batch)} steering message{'s' if len(batch) > 1 else ''} delivered to '{name}'")
    else:
        with _steering_lock:
            for m in batch:
                m.pop("_inflight", None)


def _steering_fast_tick():
    """Deliver queued steering to idle/waiting sessions within seconds — the
    snapshot loop only ticks every 60s, which read as 'queue does nothing'
    when a message was queued to an already-idle session. Only captures
    sessions that actually have a queue, so it costs nothing when empty."""
    with _steering_lock:
        names = [n for n, q in _steering_queue.items() if q]
    for name in names:
        try:
            if not is_running(name):
                continue
            raw = tmux_capture(name, 60)
            if not raw:
                continue
            # Provider-aware (Ethan 16:06: 1 QUEUED sat 2h at IDLE on a
            # Gemini lane — this tick was hardwired to the Claude detector,
            # which reads '' for Gemini frames, so delivery never fired).
            _prov_t = (get_session_info(name) or {}).get("provider", "claude")
            # Event-first (Ethan 2026-08-04): the hook knows the turn boundary;
            # the regex infers it. _session_state falls back to the scrape for
            # hookless lanes, so nothing regresses for gemini/codex.
            _steer_try_deliver(name, _session_state(name, raw, provider=_prov_t), raw)
        except Exception:
            pass


def _snapshot_all_sessions_inner():
    # Fetch running tmux sessions once to avoid spawning a subprocess per session
    running_sessions = set()
    try:
        r = subprocess.run(
            ["tmux", "list-sessions", "-F", "#{session_name}"],
            capture_output=True, text=True, timeout=5,
        )
        if r.returncode == 0:
            running_sessions = set(r.stdout.splitlines())
    except Exception:
        return
    _HIBERNATE_IDLE_SECS = int(os.environ.get("AMUX_HIBERNATE_IDLE_SECS", "1800") or "1800")  # 0 disables
    _HIBERNATE_STARTUP_GRACE = 600  # 10 min grace after server restart
    # Auto-hibernate exists to prevent OOM when MANY Claude processes (400-750MB
    # each) run at once. With only a handful of sessions the memory saved isn't
    # worth the risk: waking a hibernated session goes through --resume, which can
    # fail (large conversation / resume-picker) and fall back to a FRESH start,
    # losing the whole conversation ("leave a session too long → auto clear").
    # So only hibernate once enough sessions are running to actually threaten
    # memory. Tunable: AMUX_HIBERNATE_MIN_SESSIONS, AMUX_HIBERNATE_IDLE_SECS=0 off.
    _hib_min = int(os.environ.get("AMUX_HIBERNATE_MIN_SESSIONS", "8") or "8")
    _running_amux = sum(1 for _e in CC_SESSIONS.glob("*.env")
                        if tmux_name(_e.stem) in running_sessions)
    _hibernate_enabled = _HIBERNATE_IDLE_SECS > 0 and _running_amux >= _hib_min
    for f in CC_SESSIONS.glob("*.env"):
        name = f.stem
        if _is_session_blocked(name):
            continue
        if tmux_name(name) not in running_sessions:
            continue
        try:
            output = tmux_capture(name, 500)
            if not output:
                continue

            # Strip ANSI codes for pattern matching
            clean = _STRIP_ANSI.sub("", output)
            now = time.time()
            actions = _session_auto_actions.setdefault(name, {})

            # ── 1. Proactive: auto-compact when context is low ──────────────
            # Skip if the context % appears in /status output (user was just checking)
            ctx_match = re.search(r'context left until auto-compact[:\s]+(\d+)%', clean, re.IGNORECASE)
            _from_status_cmd = bool(ctx_match and re.search(r'❯\s*/status', clean))
            if ctx_match and not _from_status_cmd:
                pct = int(ctx_match.group(1))
                _ac_row = get_db().execute("SELECT value FROM prefs WHERE key='auto_compact_enabled'").fetchone()
                _ac_enabled = (_ac_row is None) or (_ac_row[0] != "0")  # default ON
                # Backup JSONL before compaction (regardless of whether auto-compact fires)
                if pct < 30 and now - actions.get("last_backup", 0) > 120:
                    actions["last_backup"] = now
                    threading.Thread(target=backup_session_jsonl, args=(name, "pre_compact"), daemon=True).start()
                # Threshold is a pref, not amux's hardcoded judgment (ethos dev-5):
                # WHEN to summarize is increasingly the model's own call. 0 disables
                # the proactive path entirely while keeping resume-dialog handling.
                try:
                    _th_row = get_db().execute("SELECT value FROM prefs WHERE key='auto_compact_threshold'").fetchone()
                    _ac_threshold = int(_th_row[0]) if _th_row and str(_th_row[0]).strip() else 50
                except Exception:
                    _ac_threshold = 50
                if _ac_enabled and _ac_threshold > 0 and pct < _ac_threshold and now - actions.get("last_compact", 0) > 300:
                    actions["last_compact"] = now
                    actions["post_compact_continue"] = True  # send continuation when compact finishes
                    send_text(name, "/compact")
                    _push_alert("auto_compact", name,
                                f"Auto-compacted '{name}' — context was at {pct}%")

            # ── 1b. Reactive: image dimension limit → auto-compact ─────────
            # Sessions using browser screenshots fill context with large images
            # until Claude errors with "image exceeds the dimension limit".
            # The session gets stuck at the prompt unable to proceed.
            # Guard: only fire once per error. The error text persists in tmux
            # scrollback after compaction, so without this flag the handler
            # re-triggers every 120s and floods /compact commands.
            _img_dim_error = "image" in clean and "exceeds the dimension limit" in clean
            if (_img_dim_error and not actions.get("img_dim_compacted") and
                    now - actions.get("last_compact", 0) > 120):
                actions["last_compact"] = now
                actions["img_dim_compacted"] = True
                actions["post_compact_continue"] = True
                threading.Thread(target=backup_session_jsonl, args=(name, "pre_compact_img"), daemon=True).start()
                send_text(name, "/compact")
                _push_alert("auto_compact", name,
                            f"Auto-compacted '{name}' — image dimension limit hit")
            elif not _img_dim_error:
                actions.pop("img_dim_compacted", None)

            # ── 1c. Reactive: corrupted image in context → auto-compact ────
            # When a malformed image (truncated PNG, SVG-as-PNG, etc.) gets
            # loaded via Read, every subsequent API call fails with "Could not
            # process image". The bad image is stuck in conversation history.
            _img_corrupt_error = "Could not process image" in clean
            if (_img_corrupt_error and not actions.get("img_corrupt_compacted") and
                    now - actions.get("last_compact", 0) > 120):
                actions["last_compact"] = now
                actions["img_corrupt_compacted"] = True
                actions["post_compact_continue"] = True
                threading.Thread(target=backup_session_jsonl, args=(name, "pre_compact_img"), daemon=True).start()
                send_text(name, "/compact")
                _push_alert("auto_compact", name,
                            f"Auto-compacted '{name}' — corrupted image in context")
            elif not _img_corrupt_error:
                actions.pop("img_corrupt_compacted", None)

            # ── 1d. Reactive: compact/resume dialog → auto-select "Resume from summary" ──
            # When a session's context is large, CC shows an interactive dialog:
            #   ❯ 1. Resume from summary (recommended)
            #     2. Resume full session as-is
            #     3. Don't ask me again
            # Option 1 is pre-selected; pressing Enter confirms it.
            # Guard: 120s cooldown to avoid double-firing if the dialog lingers.
            if (_at_compact_resume_prompt(clean) and
                    now - actions.get("last_compact_prompt", 0) > 120):
                # Dedicated pref (default ON): auto_compact_enabled used to gate this
                # too, so turning off auto-compaction ALSO silently disabled answering
                # the resume dialog — sessions sat at the selector for hours
                # (observability's 3am audit blocked until 4:22, 2026-07-17).
                _ar_row = get_db().execute("SELECT value FROM prefs WHERE key='auto_resume_summary'").fetchone()
                _ar_enabled = (_ar_row is None) or (_ar_row[0] != "0")
                if _ar_enabled:
                    actions["last_compact_prompt"] = now
                    subprocess.run(
                        ["tmux", "send-keys", "-t", tmux_target(name), "Enter"],
                        capture_output=True, timeout=5,
                    )
                    _push_alert("auto_compact", name,
                                f"Auto-selected 'Resume from summary' for '{name}'")
                    _emit_event(name, "session.dialog_answered",
                                {"dialog": "resume_from_summary", "choice": 1}, source="auto-resume")

            # ── 2. Reactive: thinking-block corruption → restart + replay ───
            if ("redacted_thinking" in clean and
                    "cannot be modified" in clean and
                    now - actions.get("last_restart", 0) > 120):
                actions["last_restart"] = now
                wd = _session_work_dir(name)
                last_msg = _last_meaningful_user_message(wd)
                _hard_kill_claude(name)
                start_session(name)
                if last_msg:
                    def _replay(sname=name, msg=last_msg):
                        time.sleep(6)
                        send_text(sname, msg)
                    threading.Thread(target=_replay, daemon=True).start()
                _emit_event(name, "session.crashed", {"reason": "thinking_block_corruption", "replayed": bool(last_msg)},
                            source="self-heal")
                _push_alert("thinking_reset", name,
                            f"Session '{name}' auto-restarted: thinking block corruption"
                            + (" — last message replayed" if last_msg else ""))

            # ── 2b. Reactive: session ID already in use → hard-kill + restart ─
            # Claude Code exits with "Session ID ... is already in use" when a
            # stale process holds the lock.
            if ("is already in use" in clean and "Session ID" in clean and
                    now - actions.get("last_restart", 0) > 120):
                actions["last_restart"] = now
                wd = _session_work_dir(name)
                last_msg = _last_meaningful_user_message(wd)
                _hard_kill_claude(name)
                start_session(name)
                if last_msg:
                    def _replay_id(sname=name, msg=last_msg):
                        time.sleep(6)
                        send_text(sname, msg)
                    threading.Thread(target=_replay_id, daemon=True).start()
                _emit_event(name, "session.crashed", {"reason": "session_id_conflict", "replayed": bool(last_msg)},
                            source="self-heal")
                _push_alert("auto_restart", name,
                            f"Session '{name}' auto-restarted: session ID conflict resolved"
                            + (" — last message replayed" if last_msg else ""))

            # ── 3. Auto-continue: unblock waiting sessions ───────────────────
            status = _detect_claude_status(clean)

            # ── 2c. Ghost-text rescue: amux-injected text stuck in the box ──
            # Every message amux sends carries a client-side "[H:MM AM]" prefix,
            # so pending input starting with one is OURS — never something the
            # user is composing at a real terminal. If it's sitting unsubmitted
            # in an IDLE session, its Enter was eaten (typically keystrokes
            # buffered through a Claude restart) and it will sit there forever:
            # submit it. Space-stripped match because _pending_input strips.
            if status == "idle":
                _ghost = _pending_input(clean)
                if _ghost and re.match(r"^\[\d{1,2}:\d{2}[AP]M\]", _ghost):
                    with _get_send_lock(name):
                        raw2 = tmux_capture(name, 25) or ""
                        if (_detect_claude_status(raw2) == "idle"
                                and _pending_input(_STRIP_ANSI.sub("", raw2)) == _ghost):
                            subprocess.run(["tmux", "send-keys", "-t", tmux_target(name), "Escape"],
                                           capture_output=True, timeout=5)
                            time.sleep(0.06)
                            subprocess.run(["tmux", "send-keys", "-t", tmux_target(name), "Enter"],
                                           capture_output=True, timeout=5)
                            slog(f"[ghost-rescue] session={name} submitted stuck "
                                 f"amux message: {_ghost[:80]!r}")
                            _emit_event(name, "message.rescued", {"preview": _ghost[:120]}, source="ghost-rescue")
                            _push_alert("ghost_rescue", name,
                                        f"Rescued a stuck message in '{name}' — it was typed but never submitted")

            # Track last time Claude UI was visible (used by auto-restart below)
            if _claude_ui_visible(clean):
                actions["last_claude_alive"] = now
                actions.pop("hibernated", None)

            # ── 4. Auto-restart: Claude exited to shell prompt ────────────────
            # Triggered when: CC_AUTO_CONTINUE=1 AND terminal shows a bare shell
            # prompt (no Claude UI). Rate-limited to once per 90s.
            # Always restarts when CC_AUTO_CONTINUE=1 — the user explicitly opted
            # in. Previous logic required last_alive < 600s which failed after
            # macOS hibernate (hours-long SIGKILL gaps).
            if _at_shell_prompt(clean) and not actions.get("restarting") and not actions.get("hibernated"):
                cfg_ar = parse_env_file(f)
                if cfg_ar.get("CC_ARCHIVED") == "1":
                    pass  # don't auto-restart archived sessions
                elif cfg_ar.get("CC_AUTO_CONTINUE") in ("1", "true", "yes"):
                    last_restart = actions.get("last_auto_restart", 0)
                    if now - last_restart > 90:
                        actions["restarting"] = True
                        actions["last_auto_restart"] = now
                        def _do_restart(sname=name, _actions=actions):
                            time.sleep(3)
                            start_session(sname)
                            # Wait for Claude UI to appear before clearing
                            # restarting flag — prevents auto-continue from
                            # sending text into the resume picker.
                            for _w in range(30):
                                time.sleep(1)
                                _o = tmux_capture(sname, 10)
                                if _o and _claude_ui_visible(_o):
                                    break
                            _actions.pop("restarting", None)
                        threading.Thread(target=_do_restart, daemon=True).start()
                        _push_alert("auto_restart", name,
                                    f"Claude exited in '{name}' — auto-restarting")

            # ── 4b. Process-level auto-restart: Claude killed (OOM / signal 9) ──
            # _at_shell_prompt can miss exits when Claude's status bar text leaks
            # into scrollback after a kill (causes _claude_ui_visible to
            # false-positive). This check doesn't parse terminal output — it
            # directly checks if the shell's child process is gone.
            # During startup grace, only fire if stale Claude UI is visible
            # (killed mid-operation) — skip bare shell prompts (legitimately hibernated).
            _in_grace = now - _server_start_time < _HIBERNATE_STARTUP_GRACE
            _ui_stale = _claude_ui_visible(clean) and not _at_resume_picker(clean)
            if (not actions.get("restarting") and not actions.get("hibernated")
                    and (not _in_grace or _ui_stale)):
                cfg_pl = parse_env_file(f)
                if cfg_pl.get("CC_ARCHIVED") != "1":
                    last_restart = actions.get("last_auto_restart", 0)
                    if now - last_restart > 90:
                        try:
                            tmux_sess = tmux_name(name)
                            r_pp = subprocess.run(
                                ["tmux", "list-panes", "-t", tmux_sess, "-F", "#{pane_pid}"],
                                capture_output=True, text=True, timeout=5)
                            if r_pp.returncode == 0 and r_pp.stdout.strip():
                                shell_pid = r_pp.stdout.strip().split("\n")[0]
                                r_ch = subprocess.run(
                                    ["pgrep", "-P", shell_pid],
                                    capture_output=True, text=True, timeout=5)
                                if not r_ch.stdout.strip():
                                    # Shell has no children — Claude is gone. Two cases:
                                    #  • clean shell prompt on screen = intentional /exit →
                                    #    honor the CC_AUTO_CONTINUE opt-in (unchanged).
                                    #  • blank/garbled pane = a CRASH (SIGKILL/OOM/silent
                                    #    death) → self-heal REGARDLESS of the opt-in. This
                                    #    is the hole amux-users fell through: created without
                                    #    CC_AUTO_CONTINUE, it died and sat silently dead
                                    #    because both restart paths required the opt-in.
                                    _auto = cfg_pl.get("CC_AUTO_CONTINUE") in ("1", "true", "yes")
                                    _crashed = not _at_shell_prompt(clean)
                                    if not (_auto or _crashed):
                                        pass  # clean /exit on a non-auto-continue session — leave it
                                    else:
                                        # Crash-loop cap: a session that keeps dying is a real
                                        # problem (e.g. shared CC_DIR) — don't restart forever.
                                        _deaths = [t for t in actions.get("crash_deaths", []) if now - t < 900]
                                        if _crashed and not _auto and len(_deaths) >= 3:
                                            if not actions.get("crash_gaveup"):
                                                actions["crash_gaveup"] = now
                                                slog(f"[4b] {name}: crashed {len(_deaths)}x/15min — NOT restarting, alerting")
                                                _push_alert("auto_restart", name,
                                                            f"'{name}' Claude keeps crashing ({len(_deaths)}x in 15min) — "
                                                            f"stopped auto-restarting. Likely a shared working directory "
                                                            f"(two sessions in one CC_DIR) — give it its own dir.")
                                        else:
                                            _deaths.append(now)
                                            actions["crash_deaths"] = _deaths
                                            actions.pop("crash_gaveup", None)
                                            slog(f"[4b] {name}: no child under shell PID {shell_pid} "
                                                 f"({'crash' if _crashed else 'exit'}, auto_continue={_auto}) — restarting")
                                            actions["restarting"] = True
                                            actions["last_auto_restart"] = now
                                            def _do_oom_restart(sname=name, _actions=actions):
                                                time.sleep(3)
                                                start_session(sname)
                                                for _w in range(30):
                                                    time.sleep(1)
                                                    _o = tmux_capture(sname, 10)
                                                    if _o and _claude_ui_visible(_o):
                                                        break
                                                _actions.pop("restarting", None)
                                            threading.Thread(target=_do_oom_restart, daemon=True).start()
                                            _push_alert("auto_restart", name,
                                                        f"Claude {'crashed' if _crashed else 'exited'} in '{name}' — auto-restarting")
                                else:
                                    actions.pop("crash_deaths", None)  # healthy — reset crash tracker
                            else:
                                slog(f"[4b] {name}: list-panes failed rc={r_pp.returncode}")
                        except Exception as e:
                            slog(f"[4b] {name}: exception: {e}")
                    else:
                        pass  # rate-limited (restart < 90s ago)

            # ── 5. Stale process reaper: restart idle sessions with old Claude processes
            # Claude processes lose their API connection after ~2 days but stay running.
            # Sends succeed (tmux delivers text) but Claude never processes them.
            # Check once per hour; restart if Claude process uptime > 48h and session is idle.
            if status == "idle" and not actions.get("restarting"):
                last_stale_check = actions.get("last_stale_check", 0)
                if now - last_stale_check > 3600:  # check once per hour
                    actions["last_stale_check"] = now
                    try:
                        tmux_sess = tmux_name(name)
                        r = subprocess.run(["tmux", "list-panes", "-t", tmux_sess, "-F", "#{pane_pid}"],
                                           capture_output=True, text=True, timeout=5)
                        if r.returncode == 0 and r.stdout.strip():
                            shell_pid = r.stdout.strip().split("\n")[0]
                            r2 = subprocess.run(["pgrep", "-P", shell_pid],
                                                capture_output=True, text=True, timeout=5)
                            if r2.stdout.strip():
                                claude_pid = r2.stdout.strip().split("\n")[0]
                                r3 = subprocess.run(["ps", "-o", "etime=", "-p", claude_pid],
                                                    capture_output=True, text=True, timeout=5)
                                if r3.stdout.strip():
                                    # Parse etime format: [[DD-]HH:]MM:SS
                                    _et = r3.stdout.strip()
                                    _parts = _et.replace("-", ":").split(":")
                                    _parts = [int(p) for p in _parts]
                                    if len(_parts) == 2: elapsed_secs = _parts[0]*60 + _parts[1]
                                    elif len(_parts) == 3: elapsed_secs = _parts[0]*3600 + _parts[1]*60 + _parts[2]
                                    elif len(_parts) == 4: elapsed_secs = _parts[0]*86400 + _parts[1]*3600 + _parts[2]*60 + _parts[3]
                                    else: elapsed_secs = 0
                                    if elapsed_secs > 48 * 3600:  # > 48 hours
                                        last_restart = actions.get("last_auto_restart", 0)
                                        if now - last_restart > 300:
                                            actions["restarting"] = True
                                            actions["last_auto_restart"] = now
                                            def _do_stale_restart(sname=name, _actions=actions, _age=elapsed_secs):
                                                _hard_kill_claude(sname)
                                                time.sleep(3)
                                                start_session(sname)
                                                for _w in range(30):
                                                    time.sleep(1)
                                                    _o = tmux_capture(sname, 10)
                                                    if _o and _claude_ui_visible(_o):
                                                        break
                                                _actions.pop("restarting", None)
                                            threading.Thread(target=_do_stale_restart, daemon=True).start()
                                            _push_alert("auto_restart", name,
                                                        f"Recycled stale session '{name}' — Claude process was "
                                                        f"{elapsed_secs // 3600}h old")
                    except Exception:
                        pass

            # ── 6. Auto-hibernate: stop idle sessions to reclaim memory ───────
            # Claude processes hold 400-750 MB each even when idle. With 30+
            # sessions that causes OOM kills. Stop Claude in sessions idle for
            # >30 min. The conversation is preserved — next send auto-wakes it.
            # Auto-continue sessions are hibernated too — auto-restart already
            # checks `not actions.get("hibernated")` so they won't bounce back.
            # They wake on next send_text (which calls start_session).
            if _hibernate_enabled and status == "idle" and not actions.get("restarting"):
                cfg_hib = parse_env_file(f)
                _skip_hibernate = (
                    # Grace period after server restart: actions dict is wiped
                    # so we can't tell if a session was recently active
                    now - _server_start_time < _HIBERNATE_STARTUP_GRACE
                )
                if not _skip_hibernate:
                    last_activity = actions.get("last_claude_alive", 0)
                    meta_h = _load_meta(name)
                    last_send = meta_h.get("last_send", 0)
                    last_real_activity = max(last_activity, last_send)
                    if last_real_activity and now - last_real_activity > _HIBERNATE_IDLE_SECS:
                        if not actions.get("hibernated"):
                            actions["hibernated"] = True
                            def _do_hibernate(sname=name):
                                try:
                                    stop_session(sname)
                                    print(f"[hibernate] {sname}: stopped after {int(now - last_real_activity)}s idle")
                                except Exception:
                                    pass
                            threading.Thread(target=_do_hibernate, daemon=True).start()

            # ── 3a. Post-compact continuation ──────────────────────────────────
            # After we trigger auto-compact, the session goes idle at the ❯ prompt.
            # status == 'idle' doesn't trigger normal auto-continue, so we handle
            # it explicitly: wait ≥30s for compact to finish, then send a continue msg.
            # Skip if mid-restart — text would land in resume picker search box.
            if actions.get("post_compact_continue") and status in ("idle", "waiting") and not actions.get("restarting"):
                elapsed_since_compact = now - actions.get("last_compact", 0)
                if elapsed_since_compact > 30 and now - actions.get("last_auto_continue", 0) > 60:
                    cfg_ac = parse_env_file(f)
                    cont_msg = cfg_ac.get("CC_AUTO_CONTINUE_MSG", "continue")
                    send_text(name, cont_msg)
                    actions["last_auto_continue"] = now
                    actions.pop("post_compact_continue", None)
                    _push_alert("auto_continue", name,
                                f"Post-compact auto-continue sent to '{name}'")

            if status == "waiting" and not actions.get("restarting"):
                if "ac_waiting_since" not in actions:
                    # First snapshot seeing this session waiting. _session_auto_actions
                    # is in-memory, so a plain `now` restarts the stall clock on every
                    # server reload — and this server reloads on every file save, which
                    # made a session wedged for hours report "waiting 0 min" and reset
                    # the alert threshold each time. Recover the true start from the
                    # durable event log instead: if the newest status transition on
                    # record is session.waiting, the session has been waiting since it.
                    actions["ac_waiting_since"] = _waiting_since_from_events(name, now)
                else:
                    # Still waiting on a subsequent snapshot — check opt-in flag
                    cfg_ac = parse_env_file(f)
                    if cfg_ac.get("CC_AUTO_CONTINUE") in ("1", "true", "yes"):
                        if now - actions.get("last_auto_continue", 0) > 30:
                            # Determine what kind of waiting and what to send
                            lines_ac = [l.strip() for l in clean.splitlines() if l.strip()]
                            response = None
                            label = ""
                            for l in reversed(lines_ac[-15:]):
                                sl = l.lower()
                                if "enter to select" in sl:
                                    response = ""   # bare Enter → select current option
                                    label = "Enter (select option)"
                                    break
                                if re.match(r".*\u276f\s*\d+\.", l):  # ❯ 1. Yes selector
                                    response = "1"
                                    label = "1 (first option)"
                                    break
                                if "do you want to proceed" in sl:
                                    response = "1"
                                    label = "1 (proceed)"
                                    break
                                if "interrupted" in sl and "what should claude do" in sl:
                                    custom = cfg_ac.get("CC_AUTO_CONTINUE_MSG", "continue")
                                    response = custom
                                    label = repr(custom)
                                    break
                            if response is not None:
                                send_text(name, response)
                                actions["last_auto_continue"] = now
                                actions.pop("ac_waiting_since", None)
                                actions.pop("selector_block_alerted", None)
                                _push_alert("auto_continue", name,
                                            f"Auto-continued '{name}': sent {label}")
                # ── 4b. Selector head-of-line-block escalation (AMUX-1882) ────
                # A human-gated selector can't receive an inter-session message,
                # so queued coordination sits until it resolves — silently, for
                # as long as the human takes. Once that's held real coordination
                # past the threshold, alert the owner (who can resolve it) with
                # who's blocked. Once per waiting-episode; auto-continue sessions
                # resolve in <1min and never reach the threshold.
                _ws = actions.get("ac_waiting_since")
                if (_ws and now - _ws > _SELECTOR_BLOCK_ALERT_SECS
                        and not actions.get("selector_block_alerted")):
                    with _steering_lock:
                        _held = [m for m in _steering_queue.get(name, [])
                                 if m.get("guard") != "commit"]
                    if _held:
                        _origins = []
                        for _m in _held:
                            _mo = re.search(r"\[amux-origin:\s*(\S+)", _m.get("text", ""))
                            if _mo and _mo.group(1) not in _origins:
                                _origins.append(_mo.group(1))
                        _mins = int((now - _ws) / 60)
                        _frm = (" from " + ", ".join(_origins[:4])) if _origins else ""
                        actions["selector_block_alerted"] = now
                        slog(f"[selector-block] {name}: at a selector {_mins}m, "
                             f"holding {len(_held)} coordination msg(s){_frm}")
                        _push_alert("selector_block", name,
                                    f"'{name}' has sat at a user selector for {_mins}m and is "
                                    f"holding {len(_held)} inter-session message(s){_frm}. Resolve "
                                    f"the selector to unblock coordination.")
                        _emit_event(name, "selector.blocking",
                                    {"held": len(_held), "mins": _mins, "origins": _origins[:8]},
                                    source="selector-block")
                    elif actions.get("rate_limit_credits"):
                        # ── 4c. HARD GATE with an empty queue ────────────────
                        # The branch above only fires when something is queued
                        # BEHIND the selector. A per-model credit gate has no
                        # reset time and no auto-resume, so a session that hit
                        # it between messages just stops — queue empty, status
                        # 'waiting', nobody notified. That is exactly how
                        # gtm-media-assets and gtm-videos sat 80m+ at the
                        # "Fable 5 now uses usage credits" modal while a
                        # delivered message went unworked (2026-07-27), and how
                        # AMUX-1272 / AMUX-1256 played out before it. Alert on
                        # the gate itself, not on who's blocked behind it.
                        _mins = int((now - _ws) / 60)
                        _mdl = actions.get("rate_limit_model_name") or "the current model"
                        actions["selector_block_alerted"] = now
                        slog(f"[gate] {name}: hard model/credit gate for {_mins}m "
                             f"(model={_mdl!r}) — needs a model switch or credits")
                        _push_alert("session_gated", name,
                                    f"'{name}' has been stopped {_mins}m at a {_mdl} "
                                    f"usage-credits gate. It won't self-resolve — switch "
                                    f"models or top up credits to unblock the lane.")
                        _emit_event(name, "session.gated",
                                    {"mins": _mins, "model": _mdl, "kind": "credits"},
                                    source="gate-watch")
            else:
                # Session no longer waiting — reset tracking
                actions.pop("ac_waiting_since", None)
                actions.pop("selector_block_alerted", None)

            # ── 5. Steering: deliver queued messages at turn boundary ────────
            _steer_try_deliver(name, status, output)

        except Exception:
            pass


def _snapshot_loop():
    try:
        _snapshot_all_sessions()
    except Exception:
        pass


# ── Browser idle reaper ──────────────────────────────────────────────────────
_BROWSER_IDLE_SECONDS = 15 * 60   # kill browser-use sessions idle >15 min
_BROWSER_MAX_TTL_SECONDS = 2 * 3600  # hard cap: kill any browser process >2h regardless

def _parse_etime(etime: str) -> int | None:
    """Parse ps etime format [[DD-]HH:]MM:SS into seconds."""
    if not etime:
        return None
    parts = etime.replace("-", ":").split(":")
    try:
        parts = [int(p) for p in parts]
    except ValueError:
        return None
    if len(parts) == 2: return parts[0]*60 + parts[1]
    elif len(parts) == 3: return parts[0]*3600 + parts[1]*60 + parts[2]
    elif len(parts) == 4: return parts[0]*86400 + parts[1]*3600 + parts[2]*60 + parts[3]
    return None

def _reap_stale_browsers():
    """Kill browser-use Chrome/Playwright processes that are idle or exceed max TTL.

    Two checks:
    1. Idle check — if no API call has touched a session in _BROWSER_IDLE_SECONDS, close it.
    2. Hard TTL — any browser-use Chrome process older than _BROWSER_MAX_TTL_SECONDS is killed
       regardless of activity (safety net for leaked processes).
    """
    now = time.time()

    # ── Phase 1: close idle browser-use sessions via CLI ──
    idle_sessions = []
    for session, last_active in list(_browser_session_activity.items()):
        if now - last_active > _BROWSER_IDLE_SECONDS:
            idle_sessions.append(session)
    for session in idle_sessions:
        try:
            _bu_call(["close"], session=session, timeout_s=10)
            slog(f"[browser-reaper] closed idle session '{session}' "
                 f"(idle {int(now - _browser_session_activity.get(session, now))}s)")
        except Exception:
            pass
        _browser_session_activity.pop(session, None)

    # ── Phase 2: hard-kill orphan Chrome/Playwright processes past max TTL ──
    try:
        r = subprocess.run(["pgrep", "-f", "browser-use-user-data-dir"],
                           capture_output=True, text=True, timeout=5)
        pids = [p.strip() for p in r.stdout.strip().split("\n") if p.strip()]
        if not pids:
            return
        reaped = 0
        for pid in pids:
            try:
                r2 = subprocess.run(["ps", "-o", "etime=", "-p", pid],
                                    capture_output=True, text=True, timeout=5)
                secs = _parse_etime(r2.stdout.strip())
                if secs is None:
                    continue
                if secs > _BROWSER_MAX_TTL_SECONDS:
                    os.kill(int(pid), 9)
                    reaped += 1
            except (ProcessLookupError, ValueError, subprocess.TimeoutExpired):
                pass
        if reaped:
            slog(f"[browser-reaper] hard-killed {reaped} orphan Chrome processes "
                 f"(>{_BROWSER_MAX_TTL_SECONDS//3600}h old)")
    except Exception:
        pass


# ── Ray Serve killer — Ray should never be running locally for extended periods ──
_last_ray_check = 0.0

def _kill_stale_ray():
    """Kill Ray Serve if it's been running for more than 30 minutes.
    Sessions occasionally start Ray for local testing but never stop it,
    consuming massive CPU/RAM (multiple ML model workers)."""
    global _last_ray_check
    now = time.time()
    if now - _last_ray_check < 600:
        return
    _last_ray_check = now
    try:
        r = subprocess.run(["pgrep", "-f", "ray::ServeController"],
                           capture_output=True, text=True, timeout=5)
        if not r.stdout.strip():
            return
        pid = r.stdout.strip().split("\n")[0]
        r2 = subprocess.run(["ps", "-o", "etime=", "-p", pid],
                            capture_output=True, text=True, timeout=5)
        etime = r2.stdout.strip()
        if not etime:
            return
        parts = etime.replace("-", ":").split(":")
        parts = [int(p) for p in parts]
        if len(parts) == 2: secs = parts[0]*60 + parts[1]
        elif len(parts) == 3: secs = parts[0]*3600 + parts[1]*60 + parts[2]
        elif len(parts) == 4: secs = parts[0]*86400 + parts[1]*3600 + parts[2]*60 + parts[3]
        else: return
        if secs > 1800:  # > 30 minutes
            subprocess.run("pkill -9 -f 'ray::' 2>/dev/null; pkill -9 -f 'ray/core/src/ray' 2>/dev/null; "
                           "pkill -9 -f 'ray/dashboard' 2>/dev/null; pkill -9 -f 'ray/autoscaler' 2>/dev/null; "
                           "pkill -9 -f 'ray.util.client' 2>/dev/null",
                           shell=True, timeout=15)
            slog(f"[ray-reaper] killed Ray Serve cluster — was running for {secs//60}m")
    except Exception:
        pass


def get_claude_stats(work_dir: str) -> dict:
    """Get token usage and last activity from Claude Code session files for a directory.

    Only reads the tail of the JSONL file (last 5MB) to avoid loading
    hundreds of MB into memory for long-running sessions.
    """
    if not work_dir:
        return {"tokens": 0, "last_active": ""}
    # Map dir path to Claude project directory name
    project_name = _project_name(work_dir)
    project_dir = CLAUDE_HOME / "projects" / project_name
    if not project_dir.is_dir():
        return {"tokens": 0, "last_active": ""}
    # Find the most recent JSONL file
    jsonl_files = sorted(project_dir.glob("*.jsonl"), key=lambda f: f.stat().st_mtime, reverse=True)
    if not jsonl_files:
        return {"tokens": 0, "last_active": ""}
    # Sum tokens from tail of most recent session, get last timestamp
    total_in = 0
    total_out = 0
    last_ts = ""
    for entry in _iter_jsonl_tail(jsonl_files[0], max_bytes=5_000_000):
        try:
            ts = entry.get("timestamp", "")
            if ts:
                last_ts = ts
            msg = entry.get("message", {})
            usage = msg.get("usage", {})
            if usage:
                total_in += usage.get("input_tokens", 0)
                total_in += usage.get("cache_read_input_tokens", 0)
                total_out += usage.get("output_tokens", 0)
        except (json.JSONDecodeError, AttributeError):
            continue
    return {"tokens": total_in + total_out, "last_active": last_ts}


_model_cache = {}  # {work_dir: (model, mtime, timestamp)}
_MODEL_CACHE_TTL = 15  # seconds

# `/model opus` is recorded as a plain user turn — command name, message and
# args in one entry — and carries no `message.model` anywhere. Without reading
# it, a model switch stays invisible until the session's next assistant turn,
# which for an idle session never comes.
_SLASH_MODEL_RE = re.compile(
    r"<command-name>\s*/model\s*</command-name>.*?<command-args>(.*?)</command-args>",
    re.DOTALL,
)


def _entry_text(entry: dict) -> str:
    """Flatten a JSONL entry's message content to text. Content is a bare string
    for simple turns and a list of blocks for richer ones; slash commands appear
    in both shapes depending on how the turn was composed."""
    content = (entry.get("message") or {}).get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return " ".join(b.get("text", "") for b in content if isinstance(b, dict))
    return ""


def _slash_model_switch(entry: dict) -> str:
    """Return the model a `/model <arg>` turn switched to, or "" if this entry is
    not one — or is the bare `/model` that opens the interactive picker, which
    records no id we could trust."""
    if entry.get("type") != "user":
        return ""
    text = _entry_text(entry)
    if "/model" not in text:
        return ""
    m = _SLASH_MODEL_RE.search(text)
    if not m:
        return ""
    ok, model, _err = _validate_model_name(m.group(1).strip())
    return model if ok else ""


def detect_active_model(work_dir: str, conversation_id: str = "") -> str:
    """Detect the model in use from the session's own JSONL conversation file.

    Reads backward and returns whichever signal is most recent: an explicit
    `/model <id>` switch, or the model observed on the last assistant turn.
    """
    if not work_dir:
        return ""
    # Time-based cache check BEFORE filesystem work — the no-conversation_id
    # path globs+stats every *.jsonl in the project dir (hundreds of files),
    # so skipping that when the cache is fresh eliminates the hot path entirely.
    cache_key = (work_dir, conversation_id)
    cached = _model_cache.get(cache_key)
    if cached:
        c_model, c_mtime, c_ts = cached
        if time.time() - c_ts < _MODEL_CACHE_TTL:
            return c_model
    project_name = _project_name(work_dir)
    project_dir = CLAUDE_HOME / "projects" / project_name
    if not project_dir.is_dir():
        return ""
    # Prefer the session's own conversation JSONL file
    if conversation_id:
        conv_file = project_dir / f"{conversation_id}.jsonl"
        if conv_file.exists():
            f = conv_file
        else:
            return ""
    else:
        jsonl_files = sorted(project_dir.glob("*.jsonl"), key=lambda f: f.stat().st_mtime, reverse=True)
        if not jsonl_files:
            return ""
        f = jsonl_files[0]
    try:
        mtime = f.stat().st_mtime
    except OSError:
        return ""
    # Mtime-based cache check — TTL already passed, but file hasn't changed
    if cached and cached[1] == mtime:
        _model_cache[cache_key] = (cached[0], mtime, time.time())
        return cached[0]
    try:
        # Search from end in increasing chunks until we find a model
        size = f.stat().st_size
        for chunk_size in [200_000, 1_000_000, size]:
            with f.open("rb") as fh:
                offset = max(0, size - chunk_size)
                if offset > 0:
                    fh.seek(offset)
                    fh.readline()  # skip partial line
                data = fh.read().decode("utf-8", errors="replace")
            for line in reversed(data.splitlines()):
                try:
                    entry = json.loads(line)
                    # Whichever comes first scanning backward is the newer
                    # signal, so a /model switch after the last assistant turn
                    # wins, and a later assistant turn overrides the switch.
                    model = entry.get("message", {}).get("model", "") or _slash_model_switch(entry)
                    if model:
                        _model_cache[cache_key] = (model, mtime, time.time())
                        return model
                except (json.JSONDecodeError, AttributeError):
                    continue
            if chunk_size >= size:
                break
    except Exception:
        pass
    _model_cache[cache_key] = ("", mtime, time.time())
    return ""


_TOKEN_BASELINE_FILE = CC_HOME / "token_baseline.json"


def _load_token_baseline() -> dict:
    if _TOKEN_BASELINE_FILE.exists():
        try:
            data = json.loads(_TOKEN_BASELINE_FILE.read_text())
            from datetime import datetime
            if data.get("date") == datetime.now().strftime("%Y-%m-%d"):
                return data
        except Exception:
            pass
    return {}


def save_token_baseline(stats: dict):
    from datetime import datetime
    baseline = {"date": datetime.now().strftime("%Y-%m-%d"), "sessions": {}}
    # Key by project dir (stable) not by display label (can change)
    for s in stats.get("sessions", []):
        key = s.get("proj_dir", s["name"])
        baseline["sessions"][key] = {"input": s["input"], "output": s["output"]}
    baseline["total_input"] = stats.get("total_input", 0)
    baseline["total_output"] = stats.get("total_output", 0)
    _TOKEN_BASELINE_FILE.write_text(json.dumps(baseline))


