def _get_slash_commands():
    import pathlib as _p
    cmds = [{"cmd": c, "desc": d} for c, d in _BUILTIN_SLASH_COMMANDS]
    seen = {c for c, _ in _BUILTIN_SLASH_COMMANDS}
    for d in [_p.Path.home() / ".claude" / "commands", _p.Path(".")  / ".claude" / "commands"]:
        if not d.is_dir():
            continue
        for f in sorted(d.glob("*.md")):
            name = "/" + f.stem
            if name in seen:
                continue
            seen.add(name)
            desc = ""
            try:
                text = f.read_text()
                if text.startswith("---"):
                    fm_end = text.find("---", 3)
                    if fm_end > 0:
                        for line in text[3:fm_end].splitlines():
                            if line.startswith("description:"):
                                desc = line.split(":", 1)[1].strip()
                                break
            except Exception:
                pass
            cmds.append({"cmd": name, "desc": desc})
    return cmds


def _init_db():
    """Create SQLite tables if they don't exist."""
    db = get_db()
    db.executescript(_DB_SCHEMA)
    # Ensure built-in statuses have correct positions (idempotent for existing DBs)
    for pos, (sid, label) in enumerate([
        ("backlog",   "Backlog"),
        ("todo",      "To Do"),
        ("doing",     "In Progress"),
        ("review",    "In Review"),
        ("done",      "Done"),
        ("verified",  "Verified"),
        ("discarded", "Discarded"),
    ]):
        db.execute(
            "INSERT INTO statuses (id, label, position, is_builtin) VALUES (?, ?, ?, 1)"
            " ON CONFLICT(id) DO UPDATE SET position = ?, is_builtin = 1",
            (sid, label, pos, pos),
        )
    db.commit()
    # Migrations: add columns that may not exist on older DBs
    for migration in [
        "ALTER TABLE issues ADD COLUMN owner_type TEXT NOT NULL DEFAULT 'human'",
        "ALTER TABLE issues ADD COLUMN due_time TEXT",
        "ALTER TABLE issues ADD COLUMN pinned INTEGER NOT NULL DEFAULT 0",
        "ALTER TABLE schedules ADD COLUMN run_count INTEGER NOT NULL DEFAULT 0",
        "ALTER TABLE schedules ADD COLUMN schedule_expr TEXT",
        "ALTER TABLE schedules ADD COLUMN watch INTEGER NOT NULL DEFAULT 0",
        "ALTER TABLE schedules ADD COLUMN watch_timeout INTEGER NOT NULL DEFAULT 120",
        "ALTER TABLE schedules ADD COLUMN done_pattern TEXT",
        "ALTER TABLE schedules ADD COLUMN done_action TEXT NOT NULL DEFAULT 'disable'",
        "ALTER TABLE schedules ADD COLUMN gcal_event_id TEXT",
        # kind:shell exit-code action map (MG audit #1 / AMUX-2199): JSON like
        # {"1":"alert","2":"retry_once_then_alert","3":"log"}. NULL = today's
        # behavior (nonzero -> error row). This is what lets a monitoring
        # schedule run WITHOUT a model in the loop: the script decides, the
        # map escalates, the session is the escalation path not the poller.
        "ALTER TABLE schedules ADD COLUMN exit_actions TEXT",
        # Monitor-card provenance (AMUX-2204 / MG audit #10): a derived card
        # decays independently of its source — 3 of 4 SLA-breach cards
        # escalated to Ethan were already resolved in the thread (one had
        # CONVERTED TO PAYING). source_ref names what the card derives from;
        # last_verified_at is when the producer last re-checked the source.
        "ALTER TABLE issues ADD COLUMN source_ref TEXT",
        "ALTER TABLE issues ADD COLUMN last_verified_at INTEGER",
        # WHY a run happened. Without this a hand-pressed "Run now" is byte-identical
        # to a cron fire in the runs list, so an extra same-day fire reads as the
        # scheduler double-firing. That cost a real investigation (AMUX-1998:
        # SCHED-108 "re-fired 3x" was one cron fire + two Run-now taps, from an
        # iPhone and a laptop). Default 'cron' so pre-existing rows stay honest —
        # they were overwhelmingly cron, and 'cron' is the claim least likely to
        # invent attribution that was never recorded.
        "ALTER TABLE schedule_runs ADD COLUMN source TEXT NOT NULL DEFAULT 'cron'",
        # Archiving a session must take its cards with it. Kept SEPARATE from
        # `deleted` on purpose: deleted means gone, archived means "this lane is
        # closed but the work is still readable". Cards carrying real findings
        # (cost analysis, pricing, root causes) should survive their session
        # being put away, just not clutter the live board.
        "ALTER TABLE issues ADD COLUMN archived INTEGER NOT NULL DEFAULT 0",
        # When a TAG was applied (AC-178). The needs:you re-nag timed
        # `issues.updated`, which is last-touch, not ask-age: a log append bumps it
        # (10489) and so does any field PATCH, and amux writes to descs constantly
        # — status-requests, sweeps, review notes. So the cards carrying the most
        # commentary were exactly the ones whose stale-ask check could never fire,
        # while quiet cards re-nagged on schedule. Measured: 16 needs:you cards,
        # none over the 3d threshold, the 8 oldest all clustered at 1.9d — the >3d
        # branch had never executed in production.
        "ALTER TABLE issue_tags ADD COLUMN added_at INTEGER",
        # Graph edges (2026-07-31). depends_on: JSON list of card ids — a card is
        # BLOCKED while any of them is open; the autonomy loop traverses these
        # instead of parsing "BLOCKS X" prose. reviewer: session name — when set,
        # review->done requires the ACK to come from the reviewer, making
        # cross-session verification first-class instead of voluntary.
        "ALTER TABLE issues ADD COLUMN depends_on TEXT",
        "ALTER TABLE issues ADD COLUMN reviewer TEXT",
        # Append-only system history (2026-07-31, AMUX-2112). _append_board_log
        # used to append into desc, where any full-desc PATCH (the normal way
        # sessions and the detail-panel textarea update a card) silently
        # destroyed it — a hook-attached commit line lived 2 minutes before an
        # evidence update wiped it. log is system-owned: written only by
        # _append_board_log, deliberately absent from the PATCH allow-list.
        "ALTER TABLE issues ADD COLUMN log TEXT",
        # Optimistic concurrency (2026-07-31, AMUX-1711). rev increments on
        # every PATCH and log-append; PATCH may send If-Match / expect_rev and
        # gets a 409 with the current item on mismatch instead of silently
        # last-writer-winning. Absent header = legacy behavior.
        "ALTER TABLE issues ADD COLUMN rev INTEGER NOT NULL DEFAULT 0",
        # Message->card join (2026-08-01, AMUX-2143). Capture stamps the id of
        # the card it created/folded onto the message row itself — a FIELD,
        # not a timestamp heuristic — so 'what happened to what I asked' is a
        # join, not an inference.
        "ALTER TABLE cmd_history ADD COLUMN card_id TEXT",
        # Messages history: tag each command by WHO sent it (origin session name
        # or schedule title), so the peek can color-code user vs inter-session vs
        # scheduled vs system commands.
        "ALTER TABLE cmd_history ADD COLUMN origin TEXT NOT NULL DEFAULT ''",
        # Event triggers: wake a schedule's session when something changes (closed-loop
        # orchestration), in addition to (not instead of) the cron schedule_expr heartbeat.
        # trigger_on is a comma-separated set of event names (e.g. 'session_idle,board').
        "ALTER TABLE schedules ADD COLUMN trigger_on TEXT",
        "ALTER TABLE schedules ADD COLUMN trigger_cooldown INTEGER NOT NULL DEFAULT 120",
        # Optional comma-separated allowlist of sessions whose events count for this
        # trigger (empty/null = any session). Scopes session_idle to e.g. the sessions
        # an orchestrator manages, so unrelated fleet activity doesn't wake it.
        "ALTER TABLE schedules ADD COLUMN trigger_sessions TEXT",
        "ALTER TABLE graph_nodes ADD COLUMN source_path TEXT NOT NULL DEFAULT ''",
        "ALTER TABLE issues ADD COLUMN gcal_event_id TEXT",
        "ALTER TABLE issues ADD COLUMN pos REAL NOT NULL DEFAULT 0",
        "ALTER TABLE issues ADD COLUMN notified INTEGER NOT NULL DEFAULT 0",
        "ALTER TABLE schedules ADD COLUMN kind TEXT NOT NULL DEFAULT 'tmux'",
        "ALTER TABLE saved_messages ADD COLUMN session TEXT NOT NULL DEFAULT ''",
        "ALTER TABLE statuses ADD COLUMN gate TEXT",
        "ALTER TABLE issues ADD COLUMN gate TEXT",
        # AMUX-1712: `session` was doing two jobs — who is ACCOUNTABLE for an item
        # moving, and who is merely WATCHING it for a resting lane. When those
        # diverge the board asserted the wrong one confidently: a shepherd's claim
        # rendered identically to ownership, so the router read watching as ROUTED
        # and a P0 sat idle in a lane that could not execute it (4h on the critical
        # path, looking busy the whole time). `session` now means OWNER only;
        # `shepherd` is the watcher. A field that cannot express a distinction will
        # silently collapse it.
        "ALTER TABLE issues ADD COLUMN shepherd TEXT",
        # AMUX-1713: gates are DERIVED from the item type. Default 'code' keeps the
        # strict merge/tests gate for existing items — never silently weaken a gate.
        "ALTER TABLE issues ADD COLUMN type TEXT NOT NULL DEFAULT 'code'",
        # Guard tag must survive restarts: without it a restored commit-nudge
        # delivered as a REAL message (own turn, no revalidation/folding).
        "ALTER TABLE steering_queue ADD COLUMN guard TEXT",
        # AMUX-2312: is a status EXPECTED of everyone, or only where opted in?
        # 'implicit' (default) is today's behaviour — the status applies fleet
        # wide. 'explicit' means it applies ONLY to scopes that opted in, so a
        # lane that does not deploy anything is never told to advance a card to
        # `verified`. Default 'implicit' keeps every existing status unchanged;
        # a mode is never silently tightened or weakened by the migration.
        "ALTER TABLE statuses ADD COLUMN mode TEXT NOT NULL DEFAULT 'implicit'",
    ]:
        try:
            db.execute(migration)
            db.commit()
        except Exception:
            pass  # column already exists
    # Backfill added_at for tags that predate the column (AC-178). `created` is the
    # only defensible source: the board log records the ask, but its timestamps are
    # HH:MM with no date, so they cannot be resolved to an absolute time — and a tag
    # cannot have been applied before its card existed. That makes `created` a true
    # LOWER BOUND, which is exactly why the re-nag phrasing says "at least N days"
    # rather than asserting an age it cannot know for a backfilled row. Getting that
    # wrong would trade a valve that never fires for one that states a falsehood.
    # Leaving them NULL was the alternative and it is worse: the valve would stay
    # dead for every pre-existing needs:you card, which is the very failure this
    # fixes. Only touches NULL rows, so it is idempotent across restarts.
    try:
        db.execute(
            "UPDATE issue_tags SET added_at = COALESCE("
            " (SELECT created FROM issues WHERE issues.id = issue_tags.issue_id), ?)"
            " WHERE added_at IS NULL", (int(time.time()),))
        db.commit()
    except Exception:
        pass
    for _sid, _items in {
        "doing":    ["Scope & acceptance criteria are clear", "No blocking dependency", "Has an owner"],
        "review":   ["Implemented and self-tested", "Diff / PR is up", "Ready for another set of eyes"],
        "done":     ["Implemented and merged", "Tests / lint pass"],
        "verified": ["CI/CD green (incl. e2e)", "Deployed to prod", "Confirmed working in prod", "Zero regressions"],
    }.items():
        try:
            db.execute("UPDATE statuses SET gate=? WHERE id=? AND (gate IS NULL OR gate='')", (json.dumps(_items), _sid))
        except Exception:
            pass
    db.commit()
    _load_steering_from_db()
    # One-time migration: import existing flat skill files into SQLite
    skills_dir = CC_HOME / "skills"
    if skills_dir.exists():
        for f in skills_dir.glob("*.md"):
            try:
                content = f.read_text(errors="replace")
                db.execute(
                    "INSERT OR IGNORE INTO skills(name, content, updated) VALUES(?,?,?)",
                    (f.stem, content, int(f.stat().st_mtime)),
                )
            except Exception:
                pass
        db.commit()


def _load_steering_from_db():
    """Populate _steering_queue from SQLite on startup."""
    db = get_db()
    rows = db.execute(
        "SELECT id, session, text, queued_at, guard FROM steering_queue ORDER BY queued_at ASC"
    ).fetchall()
    with _steering_lock:
        _steering_queue.clear()
        for row in rows:
            _steering_queue.setdefault(row["session"], []).append(
                {"id": row["id"], "text": row["text"], "queued_at": row["queued_at"],
                 "guard": (row["guard"] if "guard" in row.keys() else None) or ""}
            )


def _load_board_raw() -> dict:
    """Read items.json — used only for migration."""
    if _BOARD_FILE.exists():
        try:
            return json.loads(_BOARD_FILE.read_text())
        except Exception:
            pass
    return {}


# ── Report type registry ─────────────────────────────────────────────────────
# Each entry: { label, description, vendors: { id: { label, color, env_vars, fetch } } }
# To add a new report type, append an entry here — no other code changes needed.

def _report_fetch_anyscale(cfg):
    import json as _j, urllib.request as _ur
    key = os.environ.get("AMUX_ANYSCALE_API_KEY", "")
    if not key:
        return {"name": "Anyscale", "error": "AMUX_ANYSCALE_API_KEY not set", "daily": [], "monthly": []}
    try:
        req = _ur.Request("https://console.anyscale.com/api/v2/billing_invoices?limit=12",
                          headers={"Authorization": f"Bearer {key}"})
        with _ur.urlopen(req, timeout=10) as r:
            inv = _j.loads(r.read())
        monthly = [{"month": i.get("period_start", "")[:7],
                    "amount": float(i.get("amount_due", 0)) / 100}
                   for i in inv.get("results", [])]
        return {"name": "Anyscale", "daily": [], "monthly": monthly, "currency": "USD", "error": None}
    except Exception as e:
        return {"name": "Anyscale", "error": str(e), "daily": [], "monthly": []}


